const e="65 chapters",t=[{id:"chapter-57",number:57,title:"Lexical causatives: V + -이/히/리/기/우/구/추- · V-게 하다",goal:"Build natural causative pairs such as 먹다/먹이다, 자다/재우다, 입다/입히다, and 앉다/앉히다.",biteCount:9,bites:[{kind:"words",title:"단어 Words 1 · 먹이다~",cards:[{kind:"guess",word:{ko:"먹이다",romanization:"meogida",en:"to feed / make someone take",pos:"verb",nuance:"The subject is the causer, not the person eating."},sentence:{ko:"엄마가 아이에게 약을 먹였어요.",en:"The mother gave the child medicine."},target:"먹였",options:["to feed / make someone take","to inform / let know","to lower"],note:"Linked to chapter card word-ext-ch38-meogida."},{kind:"guess",word:{ko:"재우다",romanization:"jaeuda",en:"to put someone to sleep",pos:"verb",nuance:"자다 is intransitive: 아기가 자요. 재우다 adds a causer: 엄마가 아기를 재워요."},sentence:{ko:"아빠가 아기를 재웠어요.",en:"The father put the baby to sleep."},target:"재웠",options:["to inform / let know","to lower","to put someone to sleep"],note:"Chapter card word-ext-ch57-jaeuda."},{kind:"guess",word:{ko:"입히다",romanization:"iphida",en:"to dress someone / put clothing on someone",pos:"verb",nuance:"입다 is wear; 입히다 is dress someone else."},sentence:{ko:"아버지가 아기에게 코트를 입혔어요.",en:"The father put a coat on the baby."},target:"입혔",options:["to dress someone / put clothing on someone","to inform / let know","to lower"],note:"Linked to chapter card word-ext-ch38-iphida."},{kind:"guess",word:{ko:"읽히다",romanization:"ilkida",en:"to make someone read / to be read",pos:"verb",nuance:"With texts, 읽히다 often describes how easily something is read or understood."},sentence:{ko:"선생님이 학생들에게 본문을 읽혔어요.",en:"The teacher had the students read the passage."},target:"읽혔",options:["to make someone read / to be read","to inform / let know","to lower"],note:"Causative use; linked to word-ext-ch38-ilkida-passive."},{kind:"guess",word:{ko:"앉히다",romanization:"anjhida",en:"to seat someone",pos:"verb",nuance:"앉다 is what the person does; 앉히다 is what someone else does to seat them."},sentence:{ko:"직원이 손님을 창가 자리에 앉혔어요.",en:"The staff seated the guest by the window."},target:"앉혔",options:["to seat someone","to inform / let know","to lower"],note:"Linked to chapter card word-ext-ch38-anjhida."}],canDo:"Use lexical causatives for everyday care (밥을 먹이다, 옷을 입히다, 재우다)",id:"chapter-57-b1",chapterId:"chapter-57",index:0},{kind:"pattern",title:"무늬 Pattern · Lexical causatives: V + -이/히/리/기/우/구/추-",cards:[{kind:"teach",name:"Lexical causatives: V + -이/히/리/기/우/구/추-",sub:"",rows:[{when:"-이- (e.g. after ㄱ, ㅁ, vowel stems)",add:"먹다 → 먹이다 (feed), 죽다 → 죽이다 (kill), 끓다 → 끓이다 (boil sth)",ex:"엄마가 아기에게 밥을 먹여요. (Mom feeds the baby.)"},{when:"-히- (often after ㄱ, ㄷ, ㅂ)",add:"입다 → 입히다 (dress sb), 앉다 → 앉히다 (seat sb), 눕다 → 눕히다 (lay sb down)",ex:"아이에게 옷을 입혔어요. (I dressed the child.)"},{when:"-리- (often after ㄹ)",add:"살다 → 살리다 (save), 울다 → 울리다 (make cry), 알다 → 알리다 (let know)",ex:"동생이 형을 울렸어요. (The younger one made the older one cry.)"},{when:"-기-",add:"웃다 → 웃기다 (make laugh), 벗다 → 벗기다 (take sth off sb), 남다 → 남기다 (leave sth)",ex:"그 영화가 저를 웃겼어요. (That movie made me laugh.)"},{when:"-우- (note the stem often changes shape)",add:"자다 → 재우다 (put to sleep), 깨다 → 깨우다 (wake sb), 타다 → 태우다 (give a ride)",ex:"아빠가 아기를 재웠어요. (Dad put the baby to sleep.)"},{when:"-구-/-추- (a very small set)",add:"달다 → 달구다 (heat sth up), 낮다 → 낮추다 (lower), 맞다 → 맞추다 (set/adjust)",ex:"소리를 좀 낮춰 주세요. (Please turn the volume down.)"}],examples:[{ko:"제가 강아지한테 밥을 먹였어요.",en:"I fed the puppy.",romanization:"Jega gangaji-hante bab-eul meogyeosseoyo.",note:"먹다 (eat) → 먹이다 (feed): the eater (강아지) takes -한테/에게, and the new causer (저) becomes the subject."},{ko:"엄마가 아이를 일찍 재웠어요.",en:"Mom put the child to bed early.",romanization:"Eomma-ga ai-reul iljjik jaewosseoyo.",note:"자다 (sleep) → 재우다: the stem changes shape (자→재우), so memorize this pair — you can't just add a suffix."}],more:{func:"A fixed, closed set of verbs that build a causative meaning ('make/get X to happen', or 'do the action to X') right into the verb stem by inserting -이-, -히-, -리-, -기-, -우-, -구-, or -추-. The doer of the plain verb becomes the object (usually -을/를), and a new causer becomes the subject. Because the set is fixed, you can't apply it to just any verb — each causative pair is learned as its own vocabulary item.",keyPoint:{label:"Same suffix, opposite job: causative vs. passive",body:"The suffixes -이/히/리/기- also build passives, so one word can be either. 보이다 = 'be seen' (passive) or 'show' (causative); 잡히다 = 'be caught' (passive) or 'get sb to hold' (causative). Tell them apart by the arguments: a causative ADDS a causer-subject and keeps an object (친구가 저를 웃겨요 'my friend makes me laugh'), while a passive DROPS the agent and the old object becomes the subject (도둑이 잡혔어요 'the thief got caught'). If there's still a direct object being acted on, it's causative."},pronunciation:"Listen for the linking and aspiration the inserted consonant creates: 먹이다 is [머기다] (ㄱ links across), 입히다 is [이피다] (ㅂ+ㅎ → aspirated ㅍ), and 앉히다 is [안치다] (ㅈ+ㅎ → ㅊ). The suffix tends to fuse with the stem-final sound rather than staying separate."}}],canDo:"Use lexical causatives for everyday care (밥을 먹이다, 옷을 입히다, 재우다)",id:"chapter-57-b2",chapterId:"chapter-57",index:1},{kind:"words",title:"단어 Words 2 · 웃기다~",cards:[{kind:"guess",word:{ko:"웃기다",romanization:"utgida",en:"to make someone laugh / to be funny",pos:"verb",nuance:"웃다 is what the person does; 웃기다 is what causes the laughing. In speech, 웃기다 also works like 'to be funny.'"},sentence:{ko:"그 농담이 모두를 웃겼어요.",en:"That joke made everyone laugh."},target:"웃겼",options:["to inform / let know","to lower","to make someone laugh / to be funny"],note:"Chapter card word-ext-ch57-utgida."},{kind:"guess",word:{ko:"울리다",romanization:"ullida",en:"to make someone cry / to ring",pos:"verb",nuance:"울다 is cry or ring by itself; 울리다 makes someone cry or makes a sound ring."},sentence:{ko:"그 영화가 저를 울렸어요.",en:"That movie made me cry."},target:"울렸",options:["to inform / let know","to lower","to make someone cry / to ring"],note:"Chapter card word-ext-ch57-ullida."},{kind:"guess",word:{ko:"알리다",romanization:"allida",en:"to inform / let know",pos:"verb",nuance:"알리다 is the causative of 알다 ('to know'), so literally 'to make (someone) know' — you give a piece of information to a person, who takes 에게/한테, while the fact taught takes 을/를. The form you will reach for ten times a day is 알려 주세요 ('please let me know'), used to ask for an address, a time, a price, or any update. The near-synonym 가르치다 also means 'let know', but 가르치다 leans toward teaching a skill or directions ('역으로 가는 길 좀 가르쳐 주세요'), while 알리다 is just transmitting a fact ('결과를 알려 주세요'). The classic learner error is using plain 알다: 알아요 means 'I know' (a state), and you cannot make a request with it — you must use the causative 알려 주세요 to mean 'inform me'. Beyond person-to-person, 알리다 also covers public announcing — '진실을 세상에 알리다' (reveal the truth to the world)."},sentence:{ko:"일정이 바뀌면 바로 알려 주세요.",en:"If the schedule changes, please let me know right away."},target:"알려",options:["to feed / make someone take","to put someone to sleep","to inform / let know"],note:"Linked to dictionary card word-verb-075."},{kind:"guess",word:{ko:"낮추다",romanization:"natchuda",en:"to lower",pos:"verb",nuance:"낮다 is an adjective, while 낮추다 is an action verb. Compare 소리가 낮아요 with 소리를 낮춰 주세요."},sentence:{ko:"회의 중이라서 목소리를 낮췄어요.",en:"I lowered my voice because we were in a meeting."},target:"낮췄",options:["to feed / make someone take","to put someone to sleep","to lower"],note:"Chapter card word-ext-ch57-natchuda."},{kind:"guess",word:{ko:"먹다",romanization:"meokda",en:"to eat",pos:"verb",nuance:"먹다 is used for meals and food. For medicine, Korean often uses 약을 먹어요, literally “eat medicine,” which means “take medicine.”"},sentence:{ko:"아이가 밥을 먹어요.",en:"The child eats rice."},target:"먹어",options:["to feed / make someone take","to put someone to sleep","to eat"],note:"Base verb for comparison with 먹이다."},{kind:"payoff",line:{speaker:"민서",ko:"아이가 밥을 먹었어요와 엄마가 아이에게 밥을 먹였어요는 다르죠?",en:"The child ate and the mother fed the child are different, right?"},hl:"먹었"}],canDo:"Make or have someone do something with V-게 하다 (아이를 웃게 했어요)",id:"chapter-57-b3",chapterId:"chapter-57",index:2},{kind:"pattern",title:"무늬 Pattern · V-게 하다",cards:[{kind:"hunt",name:"V-게 하다",sub:"make / have / let someone do something",lines:[{tokens:[{pre:"엄마가",mid:"",post:"",hit:!1},{pre:"저를",mid:"",post:"",hit:!1},{pre:"매일",mid:"",post:"",hit:!1},{pre:"운동하",mid:"게",post:"",hit:!0},{pre:"해요.",mid:"",post:"",hit:!1}],ko:"엄마가 저를 매일 운동하게 해요.",en:"My mom makes me exercise every day.",romanization:"Eomma-ga jeo-reul maeil undonghage haeyo."},{tokens:[{pre:"선생님이",mid:"",post:"",hit:!1},{pre:"학생들에게",mid:"",post:"",hit:!1},{pre:"책을",mid:"",post:"",hit:!1},{pre:"읽",mid:"게",post:"",hit:!0},{pre:"했어요.",mid:"",post:"",hit:!1}],ko:"선생님이 학생들에게 책을 읽게 했어요.",en:"The teacher had the students read the book.",romanization:"Seonsaengnim-i haksaengdeul-ege chaek-eul ilkge haesseoyo."}],rule:{name:"V-게 하다",rows:[{when:"Verb stem + -게 하다",add:"가다 → 가게 하다, 먹다 → 먹게 하다, 공부하다 → 공부하게 하다",ex:"선생님이 학생들을 일찍 가게 했어요. (The teacher made the students leave early.)"},{when:"Adjective stem + -게 하다 ('make become ~')",add:"행복하다 → 행복하게 하다, 깨끗하다 → 깨끗하게 하다",ex:"그 소식이 저를 행복하게 했어요. (That news made me happy.)"},{when:"Causee marker sets the nuance",add:"-이/가 (let/allow, softer), -을/를 (make, direct), -에게/한테 (get sb to do)",ex:"아이에게 채소를 먹게 했어요. (I got the child to eat vegetables.)"},{when:"Past / negative command",add:"-게 했어요, -게 하지 마(세요)",ex:"동생을 울게 하지 마. (Don't make your little sibling cry.)"}]},more:{func:"The productive, all-purpose causative: add -게 하다 to almost any verb or adjective stem to mean 'make/have/let someone do or become something.' Unlike the lexical causatives, this works with every verb, so it's the go-to whenever no special causative form exists. The causee is marked with -이/가, -을/를, or -에게/한테 depending on the nuance (letting vs. making vs. getting someone to do it).",keyPoint:{label:"Lexical causative vs. V-게 하다 — how hands-on is the causer?",body:"When both exist, they differ in directness. 재우다 / 먹이다 mean the causer DOES the action to the causee (physically putting to sleep, spoon-feeding). 자게 하다 / 먹게 하다 mean the causer gets the causee to do it THEMSELVES. So 아기를 재웠어요 = 'I put the baby to sleep,' but 아기를 자게 했어요 = 'I made the baby sleep (e.g., by turning off the lights).' Use -게 하다 whenever there's no lexical form, or when you specifically mean indirect causing / letting."},pronunciation:"-게 하다 is said as written, [게 하다]; in fast speech 하다 can weaken, but unlike some patterns it does NOT contract into one word — keep 게 and 하다 separate. Don't confuse the causative with plain adverbial -게 (e.g. 크게 'loudly'); the causative needs the following 하다."}}],canDo:"Make or have someone do something with V-게 하다 (아이를 웃게 했어요)",id:"chapter-57-b4",chapterId:"chapter-57",index:3},{kind:"words",title:"단어 Words 3 · 자다~",cards:[{kind:"guess",word:{ko:"자다",romanization:"jada",en:"to sleep",pos:"verb",nuance:"자다 becomes 잘 before some future or ability forms: 잘 거예요, 잘 수 있어요."},sentence:{ko:"아기가 자요.",en:"The baby sleeps."},target:"자요",options:["to feed / make someone take","to sleep","to dress someone / put clothing on someone"],note:"Base verb for comparison with 재우다."},{kind:"guess",word:{ko:"입다",romanization:"ipda",en:"to wear",pos:"verb",nuance:"입다 is a regular verb (입어요, 입었어요, 입습니다) meaning to put on or wear clothing on the torso and legs — shirts, coats, dresses, trousers, uniforms. The thing English speakers must internalize is that Korean has no single verb for 'wear'; it splits the action by body part: 입다 for body clothes, 신다 for footwear (shoes, socks), 쓰다 for things on the head/face (hats, glasses), 끼다 for snug items (gloves, rings), 차다 for things you strap on (watch, belt), and 매다 for ties/scarves you knot. So 'wear shoes' is never 신발을 입다 — it must be 신발을 신다. A second nuance is aspect: 입다 is the action of putting on, while the resulting state 'be wearing' is 입고 있다 (티셔츠를 입고 있어요 = is wearing a T-shirt). The opposite, for taking off any of these, is the single verb 벗다. The pitfall is simply over-extending 입다 to cover everything 'wear' covers in English."},sentence:{ko:"아기가 코트를 입었어요.",en:"The baby wore a coat."},target:"입었",options:["to wear","to feed / make someone take","to put someone to sleep"],note:"Base verb for comparison with 입히다."},{kind:"guess",word:{ko:"앉다",romanization:"anjda",en:"to sit",pos:"verb",nuance:"앉아 주세요 is a polite request; 앉으세요 is also common and a little more direct."},sentence:{ko:"학생들이 앞자리에 앉았어요.",en:"The students sat in the front row."},target:"앉았",options:["to feed / make someone take","to put someone to sleep","to sit"],note:"Base verb for comparison with 앉히다."},{kind:"guess",word:{ko:"울다",romanization:"ulda",en:"to cry",pos:"verb",nuance:"울다 means to cry and is a ㄹ irregular verb: the stem ㄹ drops before endings starting with ㅂ, ㄴ, or ㅅ, so the formal present is 웁니다 (not 울습니다) and the honorific is 우세요; before a plain vowel the ㄹ stays, giving 울어요 and 울었어요, and the future keeps it too in 울 거예요. The crier is the subject and takes 이/가 (아기가 울어요), unlike English where 'cry' can feel transitive. Its natural opposite is 웃다 (laugh), and its near-synonyms split by intensity and register: 눈물을 흘리다 ('shed tears', literally, more composed/quiet) describes tears running down without sobbing, while 흐느끼다 ('to sob') is heavier and more literary; plain 울다 is the everyday all-purpose word, often boosted by mimetics like 펑펑 울다 (bawl) or 엉엉 울다. Note 울다 also describes animals making their cry/call (새가 울다 = a bird sings/cries) and even a phone or alarm 'ringing/sounding'. The English-speaker pitfall is the conjugation — writing 울습니다 by habit when the ㄹ must drop to 웁니다 — plus confusing 울다 with 웃다, which differ by a single jamo."},sentence:{ko:"저는 그 영화를 보고 울었어요.",en:"I cried after watching that movie."},target:"울었",options:["to feed / make someone take","to put someone to sleep","to cry"],note:"Base verb for comparison with 울리다."}],canDo:"Say something brought about a result with V-게 만들다 (영화가 울게 만들었어요)",id:"chapter-57-b5",chapterId:"chapter-57",index:4},{kind:"pattern",title:"무늬 Pattern · V-게 만들다",cards:[{kind:"teach",name:"V-게 만들다",sub:"bring about a result (often emotional or forceful)",rows:[{when:"Verb stem + -게 만들다",add:"울다 → 울게 만들다, 떠나다 → 떠나게 만들다, 포기하다 → 포기하게 만들다",ex:"그 영화가 저를 울게 만들었어요. (That movie made me cry.)"},{when:"Adjective stem + -게 만들다 ('cause to become ~')",add:"화나다 → 화나게 만들다, 행복하다 → 행복하게 만들다",ex:"그 말이 저를 화나게 만들었어요. (Those words made me angry.)"},{when:"Inanimate / situational causer (very common)",add:"스트레스가 / 그 일이 / 날씨가 ... + -게 만들다",ex:"스트레스가 저를 아프게 만들었어요. (Stress made me sick.)"},{when:"Past / negative command",add:"-게 만들었어요, -게 만들지 마(세요)",ex:"분위기를 어색하게 만들지 마세요. (Don't make things awkward.)"}],examples:[{ko:"그 드라마가 모두를 울게 만들었어요.",en:"That drama made everyone cry.",romanization:"Geu deurama-ga modu-reul ulge mandeureosseoyo.",note:"Emotional result + inanimate causer (드라마): the most typical use of -게 만들다."},{ko:"네 말이 나를 화나게 만들었어.",en:"What you said made me angry.",romanization:"Ne mal-i na-reul hwanage mandeureosseo.",note:"-게 만들다 fits strong feelings; here it sounds more loaded than the neutral 화나게 했어."}],more:{func:"Structurally just like V-게 하다 (add -게 만들다 to a verb or adjective stem), but with a stronger 'bring about / cause to become' flavor. Since 만들다 means 'make/create,' V-게 만들다 stresses that the causer actively PRODUCES the resulting state or behavior. It's especially common when the result is emotional (made me cry / angry / happy) or when the causing feels forceful, unintended, or hard to resist. The causer is very often an inanimate thing or a situation.",keyPoint:{label:"-게 하다 vs. -게 만들다 — neutral instruction vs. strong/emotional result",body:"-게 하다 is the neutral default: a person tells or gets someone to do something (엄마가 저를 운동하게 해요 'Mom makes me exercise'). -게 만들다 highlights a produced result, usually emotional or forceful, and very often with a thing/situation as the cause (그 영화가 저를 울게 만들었어요 'That movie made me cry'). You usually wouldn't say 엄마가 저를 운동하게 만들어요 for routine instructing — that sounds like she forced an unwilling you into it. Rule of thumb: choosing/instructing → -게 하다; an event or feeling that takes you over → -게 만들다."},pronunciation:"만들다 is [만들다]; in the past tense the ㄹ stays and you get 만들었어요 [만드러써요] — don't drop the ㄹ. -게 is light and unstressed, so the phrase often runs together as one breath group: 울게 만들었어요 → [울게 만드러써요]."}}],canDo:"Say something brought about a result with V-게 만들다 (영화가 울게 만들었어요)",id:"chapter-57-b6",chapterId:"chapter-57",index:5},{kind:"dialogue",title:"대화 Dialogue · 진짜 한국어",cards:[{kind:"chat",setting:"A learner practices causative pairs in caregiving, classroom, and emotion scenes.",lines:[{speaker:"민서",ko:"아이가 밥을 먹었어요와 엄마가 아이에게 밥을 먹였어요는 다르죠?",en:"The child ate and the mother fed the child are different, right?",romanization:"aiga babeul meogeosseoyowa eommaga aiege babeul meogyeosseoyoneun dareujyo?"},{speaker:"지훈",ko:"네. 먹었어요는 아이가 한 행동이고, 먹였어요는 엄마가 하게 한 행동이에요.",en:"Yes. Ate is what the child did; fed is what the mother caused to happen.",romanization:"ne. meogeosseoyoneun aiga han haengdongigo, meogyeosseoyoneun eommaga hage han haengdongieyo."},{speaker:"민서",ko:"그럼 선생님이 학생들에게 본문을 읽혔어요도 사동이에요?",en:"Then is 'the teacher had the students read the passage' also causative?",romanization:"geureom seonsaengnimi haksaengdeurege bonmuneul ilkyeosseoyodo sadongieyo?"},{speaker:"지훈",ko:"맞아요. 하지만 책이 잘 읽혀요는 사동보다 피동처럼 느껴져요.",en:"Right. But 'the book reads well' feels more passive-like than causative.",romanization:"majayo. hajiman chaegi jal ilkyeoyoneun sadongboda pidongcheoreom neukkyeojyeoyo."},{speaker:"민서",ko:"웃기다와 울리다는 감정이 바뀌는 사동으로 보면 되겠네요.",en:"So I can see utgida and ullida as causatives where emotions change.",romanization:"utgidawa ullidaneun gamjeongi bakkwineun sadongeuro bomyeon doegenneyo."}]},{kind:"order",prompt:"Build: 'The teacher made the student read the book.'",tokens:["선생님이","학생에게","책을 읽혔어요"],correct:"선생님이 학생에게 책을 읽혔어요",explanation:"읽히다 can be causative: make someone read. 학생에게 marks who was made to read."}],canDo:"Use lexical causatives for everyday care (밥을 먹이다, 옷을 입히다, 재우다)",id:"chapter-57-b7",chapterId:"chapter-57",index:6},{kind:"reading",title:"읽기 Reading · 누가 하게 만들었는지 보기",cards:[{kind:"read",title:"누가 하게 만들었는지 보기",chunks:["사동사를 공부할 때는 접미사만 외우면 헷갈리기 쉬워요. 먼저 누가 실제 행동을 하는지 보고, 그다음 누가 그 행동을 하게 했는지 확인해야 해요. 아이가 밥을 먹으면 아이가 행동의 주체예요. 하지만 엄마가 아이에게 밥을 먹이면 엄마가 사동의 주체이고 아이가 먹는 사람이에요.","선생님이 학생들에게 본문을 읽혔어요는 학생들이 읽지만 선생님이 읽게 한 문장이에요. 반대로 책이 잘 읽혀요는 책이 쉽게 읽힌다는 뜻이라 사동보다 피동처럼 느껴져요. 그래서 먹이다, 재우다, 입히다, 앉히다 같은 단어는 기본형과 짝으로 외우는 것이 좋아요."],translation:"When studying causative verbs, memorizing only suffixes can be confusing. First check who actually performs the action, and then who causes that action to happen. If a child eats rice, the child is the doer. But if a mother feeds the child, the mother is the causative subject and the child is the one eating. In 'the teacher had the students read the passage,' the students read but the teacher caused it. By contrast, 'the book reads well' means the book is easy to read, so it feels more passive-like than causative. That is why words like 먹이다, 재우다, 입히다, and 앉히다 are best memorized as pairs with their base forms.",qas:[{q:"사동사를 공부할 때 먼저 무엇을 확인해야 해요?",a:"누가 실제 행동을 하는지 확인해야 해요."},{q:"엄마가 아이에게 밥을 먹이면 누가 밥을 먹어요?",a:"아이가 밥을 먹어요."},{q:"책이 잘 읽혀요는 사동보다 무엇처럼 느껴져요?",a:"피동처럼 느껴져요."}]}],canDo:"Make or have someone do something with V-게 하다 (아이를 웃게 했어요)",id:"chapter-57-b8",chapterId:"chapter-57",index:7},{kind:"boss",title:"보스 Boss bite · 다 걸어요",cards:[{kind:"drill",prompt:"Which sentence means the mother fed the child?",sentence:null,options:[{text:"엄마가 아이에게 밥을 먹였어요.",ok:!0},{text:"엄마가 아이에게 밥을 먹었어요.",ok:!1},{text:"아이가 엄마에게 밥을 먹였어요.",ok:!1}],explanation:"먹이다 means someone causes or helps another person eat."},{kind:"drill",prompt:"Which sentence is causative 읽히다?",sentence:null,options:[{text:"선생님이 학생들에게 본문을 읽혔어요.",ok:!0},{text:"책이 술술 읽혔어요.",ok:!1},{text:"학생들이 책을 읽었어요.",ok:!1}],explanation:"The teacher causes the students to read. 책이 술술 읽혔어요 is passive-like/text-focused."},{kind:"drill",prompt:"Which form is better for a strong emotional result?",sentence:null,options:[{text:"그 영화가 저를 울게 만들었어요.",ok:!0},{text:"그 영화가 저를 자게 했어요.",ok:!1},{text:"그 영화 때문에 저는 울었어요.",ok:!1}],explanation:"V-게 만들다 fits emotional or resultative causation."},{kind:"drill",prompt:"아이___ 자리에 앉혔어요. (I seated the child.)",sentence:null,options:[{text:"를",ok:!0},{text:"가",ok:!1},{text:"에",ok:!1}],explanation:"앉히다 is causative, and 아이 is the person caused/helped to sit. That person takes 를."},{kind:"order",prompt:"Build: 'The teacher made the student read the book.'",tokens:["선생님이","학생에게","책을 읽혔어요"],correct:"선생님이 학생에게 책을 읽혔어요",explanation:"읽히다 can be causative: make someone read. 학생에게 marks who was made to read."},{kind:"drill",prompt:"Which sentence means “The news made me cry”?",sentence:null,options:[{text:"그 소식이 저를 울렸어요.",ok:!0},{text:"그 소식에 제가 울었어요.",ok:!1},{text:"그 소식이 울었어요.",ok:!1}],explanation:"울리다 can mean make someone cry. 저를 marks the person affected by the news."}],canDo:"Say something brought about a result with V-게 만들다 (영화가 울게 만들었어요)",id:"chapter-57-b9",chapterId:"chapter-57",index:8}]},{id:"chapter-58",number:58,title:"V-겠어요 / V-겠습니다 · A/V-겠네요 / A/V-겠군요",goal:"Use -겠습니다 for formal commitment and service speech.",biteCount:10,bites:[{kind:"words",title:"단어 Words 1 · 확인하다~",cards:[{kind:"guess",word:{ko:"확인하다",romanization:"hwaginhada",en:"to check / confirm",pos:"verb",nuance:"확인하다 (確認하다, 確 'certain/firm' + 認 'recognize') means to check, verify, or confirm that something is correct or true — facts, times, reservations, messages — making sure reality matches what you expect. The crucial contrast is with 찾다, which English 'check' can blur: 찾다 is 'to look FOR / search' something not yet located (열쇠를 찾다, 'look for the keys'), whereas 확인하다 is 'to verify' something you can already see (열쇠가 있는지 확인하다, 'check whether the keys are there'). It also differs from 알아보다 ('look into/inquire to find out', 가격을 알아보다). It's a regular noun+하다 verb: 확인하 + 여요 → 확인해요, past 확인했어요, with 안/못 splitting before 하다 (확인 안 해요, 확인 못 해요). English-speaker pitfall: 'check the box' or 'check off' is NOT 확인하다 — ticking a box is 체크하다/표시하다; and 'check out a book/check out (a hotel)' uses 빌리다 or 체크아웃하다, not 확인하다, which strictly means 'verify/confirm'."},sentence:{ko:"주문은 제가 바로 확인하겠습니다.",en:"I will check the order right away."},target:"확인하",options:["to handle / process","to check / confirm","to help politely"],note:"Linked to dictionary card word-verb-482."},{kind:"guess",word:{ko:"처리하다",romanization:"cheorihada",en:"to handle / process",pos:"verb",nuance:"처리하다 (處理하다, 處 'manage/place' + 理 'put in order') is a workhorse meaning to process, handle, or take care of a task, request, or problem, and the passive 처리되다 ('be processed') saturates official status messages. The register is neutral-professional, ideal for office work and paperwork. Watch three near-neighbors: 해결하다 ('to solve/resolve') implies fully fixing a problem so it's gone, whereas 처리하다 can just mean 'deal with / move it along the pipeline' without a happy ending; 다루다 means 'to handle/treat' in the sense of how you manage a topic or object; and bare 하다 ('do') cannot stand in for 'take care of a matter.' The English-speaker pitfall is exactly that bare-하다 trap: 'I'll do this issue' translated literally as '이 문제를 할게요' is wrong — you must say 처리할게요. Reach for 처리하다 whenever English would say 'handle,' 'take care of,' or 'process.'"},sentence:{ko:"이 일은 제가 처리하겠습니다.",en:"I will handle this matter."},target:"처리하",options:["to check / confirm","to help politely","to handle / process"],note:"Linked to dictionary card word-verb-046."},{kind:"guess",word:{ko:"도와드리다",romanization:"dowadeurida",en:"to help politely",pos:"verb",nuance:"도와드리다 is the humble form of 도와주다 ('help (as a favour)'), where 돕다 (to help) becomes 도와- by the ㅂ-irregular (돕 + 아 → 도와), and the helper-benefit 주다 is upgraded to its humble twin 드리다. So it literally means 'humbly do the favour of helping' — you lower yourself to help someone above you: a customer, elder, or guest. Contrast the three levels you must keep straight: 돕다 (bare dictionary 'help'), 도와주다 (help someone, neutral/friendly), 도와드리다 (help a superior, humble). English flattens all of these to 'help', so the pitfall is using 도와주다 with a customer (too casual for service) or, conversely, 도와드리다 with a buddy (oddly stiff). The phrase 무엇을 도와드릴까요? is the fixed, must-know service line. Conjugation follows 드리다: 도와드려요, 도와드렸어요."},sentence:{ko:"손님을 도와드리겠습니다.",en:"I will help the customer."},target:"도와드리",options:["to help politely","to check / confirm","to handle / process"],note:"Linked to dictionary card word-verb-265."},{kind:"guess",word:{ko:"참석하다",romanization:"chamseokhada",en:"to attend",pos:"verb",nuance:"참석하다 is Sino-Korean 參席 — 參 'take part' + 席 'seat' — literally 'take one's seat (and take part)', i.e. attend a formal event like a meeting, ceremony, or banquet. Its register is more formal than just 가다 'to go'; you 결혼식에 가요 casually but 결혼식에 참석합니다 in polite/written contexts. Distinguish it from its close cousin 참가하다 (參加, 'participate/enter'): 참석하다 emphasizes being PRESENT and seated at a gathering, while 참가하다 emphasizes actively TAKING PART (참가하다 fits a contest, race, or program — 대회에 참가하다). The big English-speaker pitfall is the particle: English 'attend THE meeting' (object) drives learners to 회의를 참석하다, but Korean uses 에 — 회의에 참석하다 — because you 'join INTO' the event. As a noun+하다 verb it conjugates on 하다 (참석해요, 참석했어요, formal 참석합니다); negative/impossible split the noun (참석 안 해요, 참석 못 해요)."},sentence:{ko:"죄송하지만 오늘은 참석하기 어렵겠습니다.",en:"I'm sorry, but it will be difficult for me to attend today."},target:"참석하",options:["to check / confirm","to attend","to handle / process"],note:"Linked to dictionary card word-verb-494."},{kind:"guess",word:{ko:"거절하다",romanization:"geojeolhada",en:"to refuse / decline",pos:"verb",nuance:"거절하다 (Sino-Korean 拒絶, 'block-and-sever') is the standard verb for declining a request, offer, or invitation, and the thing refused — 부탁, 제안, 초대 — takes 을/를. Compare it with the harsher 거부하다 (拒否, 'block-and-deny'): 거부하다 is a flat, often institutional rejection ('출석을 거부하다', 'refuse to comply'), while 거절하다 is the ordinary interpersonal 'no thanks'. Because directly refusing can feel rude in Korean social life, 거절하다 is habitually cushioned with 죄송하지만 ('sorry, but…'), 정중하게 ('politely'), or 어렵겠어요 ('that would be difficult'); the bare verb can sound cold. A frequent English-speaker slip is reaching for 거절하다 to mean 'reject a person' romantically — that is 차다 (dump) or 까이다 (get rejected), not 거절하다, which targets the request, not the human. Also do not confuse it with 사양하다, a humble 'I'll pass' used to politely decline an offer of food or a gift."},sentence:{ko:"정중하게 거절해야 할 때도 있어요.",en:"There are times when you have to decline politely."},target:"거절해",options:["to check / confirm","to handle / process","to refuse / decline"],note:"Linked to dictionary card word-verb-077."},{kind:"guess",word:{ko:"정중하다",romanization:"jeongjunghada",en:"courteous / respectful",pos:"adjective",nuance:"정중하다 (鄭重하다; the 重 carries 'weighty/grave,' so the word evokes treating someone with weighty respect) means courteous and respectful in a formal, dignified way — proper manners and respectful language. The near-synonym you must separate is 친절하다 (kind/friendly), and the dividing line is warmth vs. form: 친절하다 is personal warmth and helpfulness (a 친절한 점원 smiles and helps you happily), while 정중하다 is formal respect shown through correct manners and language (a 정중한 점원 is impeccably proper, not necessarily warm). For a careful apology, a polite refusal, or staff toward an important guest, you reach for 정중하다, where 친절하다 would feel too casual-warm. Also distinguish 겸손하다 (inner humility about oneself) from 정중하다 (outward courtesy toward others) — different directions. Register: 정중하다 is itself a formal-leaning word, at home in business Korean and written apologies (정중히 사과드립니다). The English-speaker pitfall is collapsing all 'polite' into one word: friendly-polite is 친절하다, formally-courteous is 정중하다. Stem note: 정중해요, not 정중하해요."},sentence:{ko:"어렵겠습니다는 정중한 거절에 자주 쓰여요.",en:"Eoryeopgesseumnida is often used in courteous refusals."},target:"정중한",options:["to be possible","to be tired","courteous / respectful"],note:"Linked to dictionary card word-ext-1792."},{kind:"payoff",line:{speaker:"직원",ko:"주문은 제가 바로 확인하겠습니다.",en:"I will check the order right away."},hl:"확인하"}],canDo:"State my own intention politely with V-겠습니다 / V-겠어요 (확인하겠습니다)",id:"chapter-58-b1",chapterId:"chapter-58",index:0},{kind:"pattern",title:"무늬 Pattern · V-겠어요 / V-겠습니다",cards:[{kind:"hunt",name:"V-겠어요 / V-겠습니다",sub:"stating your own intention",lines:[{tokens:[{pre:"제가",mid:"",post:"",hit:!1},{pre:"먼저",mid:"",post:"",hit:!1},{pre:"할게요.",mid:"",post:"",hit:!1},{pre:"제가",mid:"",post:"",hit:!1},{pre:"하",mid:"겠습니다",post:".",hit:!0}],ko:"제가 먼저 할게요. 제가 하겠습니다.",en:"Let me do it first. I'll do it.",romanization:"je-ga meon-jeo hal-ge-yo. je-ga ha-get-sseum-ni-da."},{tokens:[{pre:"오늘은",mid:"",post:"",hit:!1},{pre:"제가",mid:"",post:"",hit:!1},{pre:"살게요.",mid:"",post:"",hit:!1},{pre:"제가",mid:"",post:"",hit:!1},{pre:"사",mid:"겠습니다",post:".",hit:!0}],ko:"오늘은 제가 살게요. 제가 사겠습니다.",en:"Today it's on me — I'll pay.",romanization:"o-neu-reun je-ga sal-ge-yo. je-ga sa-get-sseum-ni-da."}],rule:{name:"V-겠어요 / V-겠습니다",rows:[{when:"Polite spoken intention",add:"verb stem + 겠어요",ex:"먹다 → 먹겠어요 (I'll eat / I'll have it)"},{when:"Formal commitment / announcement",add:"verb stem + 겠습니다",ex:"하다 → 하겠습니다 (I will do it)"},{when:"Set greeting phrases",add:"frozen 겠 forms",ex:"잘 먹겠습니다 / 처음 뵙겠습니다"}]},more:{func:"Attach 겠 to a verb stem to say what YOU are going to do, decided right now, as a will or promise. Because it carries the speaker's own will, it almost always has a first-person subject (저/제가). 겠어요 is polite-conversational; 겠습니다 is formal and sounds like a firm, clean promise — the kind you make to a boss, a teacher, or a customer.",keyPoint:{label:"겠어요 vs 겠습니다",body:"Same intention meaning, different register. 겠어요 is everyday polite ('제가 할게요'/'먹겠어요'); 겠습니다 is formal and weightier, so it's the default for promises, service speech, and announcements. Don't use either for someone ELSE's plan — for that you need -(으)ㄹ 거예요 (친구가 올 거예요)."},pronunciation:"겠 ends in a [ㄷ] sound, so before 습니다 the ㅅ tenses and the batchim drops in: 겠습니다 → [게씀니다]. 겠어요 links smoothly as [게써요]."}}],canDo:"State my own intention politely with V-겠습니다 / V-겠어요 (확인하겠습니다)",id:"chapter-58-b2",chapterId:"chapter-58",index:1},{kind:"words",title:"단어 Words 2 · 자료~",cards:[{kind:"guess",word:{ko:"자료",romanization:"jaryo",en:"data / materials / documents",pos:"noun",nuance:"자료 can mean data, but in daily work and study talk it often means the file, handout, or slide deck someone needs."},sentence:{ko:"자료를 보니 결과가 달라지겠네요.",en:"Looking at the data, it looks like the result will change."},target:"자료",options:["data / materials / documents","result / outcome","customer / guest"],note:"Linked to dictionary card word-ext-ch35-jaryo."},{kind:"guess",word:{ko:"결과",romanization:"gyeolgwa",en:"result / outcome",pos:"noun",nuance:"결과 (結果, literally '結 form/bear + 果 fruit', i.e. the fruit that an action bears) is the end outcome of an action or event, and it almost always pairs with 나오다 (come out) or 나타나다 (appear) rather than any verb of 'making'. Its built-in partner is 과정 (the process leading up to it) and its mirror image is 원인 (the cause behind it), so Koreans constantly say 과정도 중요하고 결과도 중요하다. Register is neutral — fine in a doctor's office (검사 결과), a classroom (시험 결과), or a news report. The big English-speaker trap is twofold: first, you do not 'get' a result with a transitive verb the way English does — the result 나오다 (comes out) on its own and takes 이/가, so 결과를 나오다 is wrong; second, do not confuse the outcome 결과 with the reason 원인/이유 — 결과 is what happened at the end, never why."},sentence:{ko:"결과가 달라지겠네요.",en:"It looks like the result will change."},target:"결과",options:["result / outcome","data / materials / documents","customer / guest"],note:"Linked to dictionary card word-ext-1672."},{kind:"guess",word:{ko:"손님",romanization:"sonnim",en:"customer / guest",pos:"noun",nuance:"손님 is native Korean — 손 'guest' + the honorific suffix -님 — so it builds 'guest' into a respectful form, and it covers BOTH a paying customer in a shop AND a guest visiting your home. That built-in 님 is why 손님 is inherently polite and why staff address you directly as 손님 (like English 'sir/ma'am'). Contrast it with the neutral 사람 'person' (too plain and even rude to call a customer) and with 고객, the more formal/corporate term banks, telecoms, and notices use (고객님, 고객 센터 customer center) — 손님 feels face-to-face and shop-floor, 고객 feels institutional. Because 손님 deserves respect, it's counted with the honorific 분 (손님 한 분, not 한 명) and described with honorific verbs (오시다 'come', 계시다 'be present', 기다리고 계세요). The English-speaker pitfall is reaching for 사람 ('a person came to the shop' → 사람이 왔어요 sounds cold); say 손님이 오셨어요. Collocations: 손님을 받다 (take/receive customers), 손님이 들다 (customers come in), 단골손님 (regular), 손님 접대 (hosting guests)."},sentence:{ko:"손님을 바로 도와드리겠습니다.",en:"I will help the customer right away."},target:"손님",options:["customer / guest","data / materials / documents","result / outcome"],note:"Linked to dictionary card word-ext-140."},{kind:"guess",word:{ko:"바로",romanization:"baro",en:"right away",pos:"adverb",nuance:"바로 carries two everyday senses split by context: 'right away / immediately' with actions (바로 가요, 바로 출발해요) and 'exactly / right (there)' with places and identifications (바로 여기, 바로 앞, 바로 그거예요). For the time sense, its near-synonym 곧 means 'soon / shortly' — a small gap remains — while 바로 means truly 'this instant, with zero delay', so 바로 가요 is more immediate than 곧 가요. For the location/identification sense, 바로 tightens 'next to/in front of' into 'directly, precisely' and has no single English twin; it behaves like 'right' in 'right next to'. It collocates tightly with position words (바로 옆/앞/뒤/위) and with emphatic confirmations (바로 그거, 바로 너 'you, exactly'). The English-speaker pitfall is assuming 바로 only means 'immediately' and missing its 'exactly/right-there' use, plus stranding it from the word it marks — keep 바로 hugging the verb or noun (바로 앞, not 앞 바로)."},sentence:{ko:"바로 확인하겠습니다.",en:"I will check right away."},target:"바로",options:["right away","a little / a bit","to check / confirm"],note:"Linked to dictionary card word-ext-1293."},{kind:"guess",word:{ko:"주문",romanization:"jumun",en:"order",pos:"noun",nuance:"주문 is the noun 'order', from 注文 (注 'pour/note down' + 文 'writing') — originally 'to write down a request', which fits ordering perfectly. The verb is 주문하다, and a key contrast is 주문하다 vs 시키다: both mean 'to order', but 시키다 is more casual and also means 'to make someone do something', so toward staff the cleaner, slightly more standard choice is 주문하다 (시키다 is fine among friends: '뭐 시킬까?'). Knowing the bare noun unlocks the phrases you hear constantly — '주문 도와드릴게요', '주문 들어갔어요', '주문 확인해 주세요' — where 주문 stands alone. Register is neutral and identical in casual and formal dining. It collocates with 하다, 들어가다 (go in), 받다 (take an order), 확인하다 (confirm), and 취소하다 (cancel)."},sentence:{ko:"주문은 제가 바로 확인하겠습니다.",en:"I will check the order right away."},target:"주문",options:["data / materials / documents","order","result / outcome"],note:"Linked to dictionary card word-ext-587."},{kind:"guess",word:{ko:"기다리다",romanization:"gidarida",en:"to wait",pos:"verb",nuance:"기다려 주세요 is one of the most useful service and classroom requests."},sentence:{ko:"그럼 조금 기다리겠습니다.",en:"Then I will wait a little."},target:"기다리",options:["to check / confirm","to handle / process","to wait"],note:"Linked to dictionary card word-verb-018."},{kind:"payoff",line:{speaker:"직원",ko:"주문은 제가 바로 확인하겠습니다.",en:"I will check the order right away."},hl:"바로"}],canDo:"Make a careful inference from evidence with A/V-겠네요 (바쁘겠네요)",id:"chapter-58-b3",chapterId:"chapter-58",index:2},{kind:"pattern",title:"무늬 Pattern · A/V-겠네요 / A/V-겠군요",cards:[{kind:"hunt",name:"A/V-겠네요 / A/V-겠군요",sub:"'that must be…' (inference from evidence)",lines:[{tokens:[{pre:"밖에",mid:"",post:"",hit:!1},{pre:"눈이",mid:"",post:"",hit:!1},{pre:"와요?",mid:"",post:"",hit:!1},{pre:"길이",mid:"",post:"",hit:!1},{pre:"막히",mid:"겠네요",post:".",hit:!0}],ko:"밖에 눈이 와요? 길이 막히겠네요.",en:"It's snowing outside? Then the roads must be jammed.",romanization:"ba-kke nu-ni wa-yo? gi-ri ma-ki-get-ne-yo."},{tokens:[{pre:"하루",mid:"",post:"",hit:!1},{pre:"종일",mid:"",post:"",hit:!1},{pre:"일했어요?",mid:"",post:"",hit:!1},{pre:"정말",mid:"",post:"",hit:!1},{pre:"피곤하",mid:"겠네요",post:".",hit:!0}],ko:"하루 종일 일했어요? 정말 피곤하겠네요.",en:"You worked all day? You must be really tired.",romanization:"ha-ru jong-il il-hae-sseo-yo? jeong-mal pi-gon-ha-get-ne-yo."}],rule:{name:"A/V-겠네요 / A/V-겠군요",rows:[{when:"Reacting to fresh evidence (spoken)",add:"stem + 겠네요",ex:"춥다 → 춥겠네요 (It must be cold!)"},{when:"Realization / 'I see, so…'",add:"stem + 겠군요",ex:"맛있다 → 맛있겠군요 (That must be tasty)"},{when:"Inferring about the past",add:"-았/었 + 겠네요",ex:"힘들었겠네요 (That must have been hard)"}]},more:{func:"This is the other big job of 겠: drawing a confident conclusion from what you can see, hear, or have just been told. Add 겠 to a verb or adjective stem, then 네요/군요 to react out loud. It means 'must be / I bet / I can tell.' 겠네요 is the everyday reaction; 겠군요 sounds a touch more reflective ('Ah, so it must be…').",keyPoint:{label:"The two faces of 겠: will vs guess",body:"With a first-person action verb, 겠 = intention (먹겠어요 = I'll eat). With an adjective, or a third-person situation plus 네요/군요, 겠 = inference (맛있겠네요 = that must be tasty). Adjectives can't 'intend' anything, so 춥겠어요 can only mean 'it must be cold,' never 'I will be cold.'"},pronunciation:"겠네요 → [겐네요] (the [ㄷ] of 겠 becomes ㄴ before ㄴ, by nasalization). 겠어요 links as [게써요], and 겠군요 → [겓꾼뇨] with the ㄱ tensing."}}],canDo:"Make a careful inference from evidence with A/V-겠네요 (바쁘겠네요)",id:"chapter-58-b4",chapterId:"chapter-58",index:3},{kind:"words",title:"단어 Words 3 · 회의~",cards:[{kind:"guess",word:{ko:"회의",romanization:"hoeui",en:"meeting",pos:"noun",nuance:"회의 (漢字 會議, 會 'gather' + 議 'discuss') is a formal, work-style meeting where people gather to discuss and decide something — a board meeting, a team sync, a planning session. The near-synonym learners reach for is 모임, but 모임 is a social get-together (a dinner, a club, friends meeting up) with no agenda, so calling drinks with friends a 회의 sounds robotic; conversely calling a budget review a 모임 sounds too loose. It pairs naturally with 회의를 하다 (hold), 회의에 들어가다 (go into), 회의가 길어지다 (run long). The English-speaker pitfall is the particle: you are *in* a meeting as a location, so the action takes 회의에서, but you *enter* a meeting with 회의에 들어가다 — and never confuse 회의 with the look-alike 회사 (company) or 회비 (membership fee)."},sentence:{ko:"오늘 회의에서는 설명이 좀 어렵겠습니다.",en:"In today's meeting, explaining it may be a bit difficult."},target:"회의",options:["meeting","data / materials / documents","result / outcome"],note:"Linked to dictionary card word-ext-121."},{kind:"guess",word:{ko:"설명",romanization:"seolmyeong",en:"explanation",pos:"noun",nuance:"설명(說明) is Sino-Korean — 說 'to tell/speak' + 明 'clear, bright' — literally 'to make clear by telling,' i.e. an explanation of how or why something works. Distinguish it from 설득(說得) 'persuasion' (talking someone INTO agreeing, sharing the 說 root) and from 묘사(描寫) 'description' (depicting what something looks/feels like); 설명 is about clarifying and informing, not convincing or portraying. As a noun it becomes the verb with 하다: 설명하다, very often softened to 설명해 주세요/주시겠어요 'please explain for me.' Collocations: 설명을 하다/듣다, 자세한 설명, 설명이 부족하다/이해가 안 되다, 설명서 'instruction manual.' The English-speaker pitfall: English 'explain to me' tempts learners to mark the listener with 를 (저를 설명하다 ✗, which would mean 'explain ME'); the listener takes 한테/에게 (저한테 설명해 주세요), and what you explain takes 을/를. Bare 설명 can't be the verb — use 설명하다. Don't confuse 설명 with the look-alike 설탕 'sugar.'"},sentence:{ko:"설명이 길어지면 이해하기 어렵겠네요.",en:"If the explanation gets long, it will be hard to understand."},target:"설명",options:["data / materials / documents","explanation","result / outcome"],note:"Linked to dictionary card word-ext-1461."},{kind:"guess",word:{ko:"조금",romanization:"jogeum",en:"a little / a bit",pos:"adverb",nuance:"조금 means 'a little / a bit / a few' and is the natural counterweight to 많이 for small amounts or mild degrees. Its closest relative is its own contracted form 좀: 조금 is the full, slightly more careful version you can write and say, while 좀 is the quick spoken reduction (조금만요 ↔ 좀만요 are the same idea). Compared with the noun-ish 약간 ('slightly', a touch more formal/written), 조금 is the warm conversational choice. It naturally collocates with quantities and gentle states — 조금 더 ('a little more'), 조금 있다가 ('in a little while') — and its softness makes it ideal for modest answers and polite requests. The English-speaker pitfall is hearing 좀 in speech and not realizing it is just 조금 reduced, and over-stacking it with big-amount words: 조금 많이 is self-contradictory because 조금 only ever points to a small degree."},sentence:{ko:"조금 기다리겠습니다.",en:"I will wait a little."},target:"조금",options:["a little / a bit","right away","to check / confirm"],note:"Linked to dictionary card word-ext-1286."},{kind:"guess",word:{ko:"가능하다",romanization:"ganeunghada",en:"to be possible",pos:"adjective",nuance:"가능하다 (可能, 可 'can/permissible' + 能 'ability') means 'possible / doable / available', and it is wonderfully practical for daily service questions — 예약 가능해요? ('Is a reservation possible?'), 카드 가능해요? ('Can I pay by card?'). In these, a noun sits directly before it and it neatly replaces a longer '-ㄹ 수 있다' clause, sounding crisp and businesslike. The softener 가능하면 ('if possible') makes requests polite, and the fixed frame 가능한 한 + adjective/adverb means 'as ~ as possible' (가능한 한 빨리 'as soon as possible') — note this is different from 가능한 N ('a possible N'). Its antonym is 불가능하다. One pitfall: while 가능하다 and '-ㄹ 수 있다' both render English 'can', '-ㄹ 수 있다' attaches to a verb stem describing an action you're able to do (갈 수 있어요 'I can go'), whereas 가능하다 attaches to a noun or stands alone judging feasibility — don't merge them into 갈 가능해요."},sentence:{ko:"이 방법이 가능할 것 같아요.",en:"I think this method might be possible."},target:"가능할",options:["to be possible","courteous / respectful","to be tired"],note:"Linked to dictionary card word-ext-1255."},{kind:"guess",word:{ko:"피곤하다",romanization:"pigonhada",en:"to be tired",pos:"adjective",nuance:"피곤하다 is physical/general tiredness — worn out, drained, exhausted — typically after work, study, travel, or poor sleep. It is Sino-Korean 疲困 (疲 weary + 困 exhausted), literally 'weary-exhausted', which is why it reads as bodily fatigue rather than sleepiness. Keep it apart from 졸리다 ('sleepy'): you can be 피곤하다 yet wide awake (drained but not nodding off), and 졸리다 is specifically wanting to sleep — don't swap them. It is also milder and more everyday than 지치다 ('to be worn out/burned out'), which implies you've reached your limit. As a regular 하다-adjective it is 피곤해요 (not 피곤하요). One common English-speaker slip: 피곤하다 normally describes a PERSON being tired; to call an activity 'tiring' you also use 피곤하다 (피곤한 일 = 'tiring work'), but to call a person 'tiresome/draining' Koreans say 피곤한 사람 — meaning 'a person who is exhausting to deal with', a nuance worth knowing so you don't misread it as 'a tired person.'"},sentence:{ko:"표정을 보니 많이 피곤하시겠네요.",en:"Seeing your expression, you must be very tired."},target:"피곤하",options:["to be tired","courteous / respectful","to be possible"],note:"Linked to dictionary card word-ext-257."},{kind:"guess",word:{ko:"어렵다",romanization:"eoryeopda",en:"to be difficult",pos:"adjective",nuance:"어렵다 is ㅂ irregular: 어려워요, 어려운. It is useful in classroom repair conversations because learners often need to say a sentence or lesson is difficult."},sentence:{ko:"오늘은 참석하기 어렵겠습니다.",en:"It will be difficult for me to attend today."},target:"어렵",options:["to be difficult","courteous / respectful","to be possible"],note:"Linked to dictionary card word-adjective-037."},{kind:"payoff",line:{speaker:"손님",ko:"감사합니다. 그럼 조금 기다리겠습니다.",en:"Thank you. Then I will wait a little."},hl:"조금"}],canDo:"Talk about a future plan with V-(으)ㄹ 거예요 (기다릴 거예요)",id:"chapter-58-b5",chapterId:"chapter-58",index:4},{kind:"pattern",title:"무늬 Pattern · V-(으)ㄹ 거예요",cards:[{kind:"hunt",name:"V-(으)ㄹ 거예요",sub:"talking about a future plan",lines:[{tokens:[{pre:"이번",mid:"",post:"",hit:!1},{pre:"주말에",mid:"",post:"",hit:!1},{pre:"부산에",mid:"",post:"",hit:!1},{pre:"갈",mid:"",post:"",hit:!1},{pre:"",mid:"거예요",post:".",hit:!0}],ko:"이번 주말에 부산에 갈 거예요.",en:"I'm going to Busan this weekend.",romanization:"i-beon ju-ma-re bu-sa-ne gal kkeo-ye-yo."},{tokens:[{pre:"민수",mid:"",post:"",hit:!1},{pre:"씨는",mid:"",post:"",hit:!1},{pre:"안",mid:"",post:"",hit:!1},{pre:"올",mid:"",post:"",hit:!1},{pre:"",mid:"거예요",post:".",hit:!0},{pre:"바쁘대요.",mid:"",post:"",hit:!1}],ko:"민수 씨는 안 올 거예요. 바쁘대요.",en:"Minsu isn't going to come. He says he's busy.",romanization:"min-su ssi-neun an ol kkeo-ye-yo. ba-ppeu-dae-yo."}],rule:{name:"V-(으)ㄹ 거예요",rows:[{when:"Stem ends in a vowel",add:"+ ㄹ 거예요",ex:"가다 → 갈 거예요 (I'm going to go)"},{when:"Stem ends in a consonant",add:"+ 을 거예요",ex:"먹다 → 먹을 거예요 (I'm going to eat)"},{when:"ㄹ-final stem",add:"+ 거예요 (ㄹ stays)",ex:"만들다 → 만들 거예요 (I'll make it)"}]},more:{func:"Use -(으)ㄹ 거예요 to state a plan or prediction about the future — yours OR someone else's. Unlike volitional 겠, it doesn't sound like an on-the-spot vow; it just reports what is going to happen. It's the everyday way to say 'I'm going to…' / 'X is going to…'.",keyPoint:{label:"거예요 vs 겠",body:"Both reach into the future, but the feel differs. -(으)ㄹ 거예요 = a settled plan or neutral prediction, and works for anyone (저도, 친구도). 겠 = a will/promise made right now, almost always first-person (제가 하겠습니다). So a server taking your order says 주문하시겠어요? (your intention), while you describe your trip with 갈 거예요 (it's planned)."},pronunciation:"Standard spelling is 거예요 (you'll also see 거에요, but 거예요 is correct). The ㄹ of the -(으)ㄹ form tenses the next sound: 갈 거예요 → [갈 꺼예요], 먹을 거예요 → [머글 꺼예요]."}}],canDo:"Talk about a future plan with V-(으)ㄹ 거예요 (기다릴 거예요)",id:"chapter-58-b6",chapterId:"chapter-58",index:5},{kind:"pattern",title:"무늬 Pattern · A/V-(으)ㄹ 것 같아요",cards:[{kind:"hunt",name:"A/V-(으)ㄹ 것 같아요",sub:"a soft, tentative guess",lines:[{tokens:[{pre:"오늘",mid:"",post:"",hit:!1},{pre:"비가",mid:"",post:"",hit:!1},{pre:"올",mid:"",post:"",hit:!1},{pre:"",mid:"것",post:"",hit:!0},{pre:"",mid:"같아요",post:".",hit:!0}],ko:"오늘 비가 올 것 같아요.",en:"I think it's going to rain today.",romanization:"o-neul bi-ga ol geot ga-ta-yo."},{tokens:[{pre:"이",mid:"",post:"",hit:!1},{pre:"옷은",mid:"",post:"",hit:!1},{pre:"저한테",mid:"",post:"",hit:!1},{pre:"좀",mid:"",post:"",hit:!1},{pre:"클",mid:"",post:"",hit:!1},{pre:"",mid:"것",post:"",hit:!0},{pre:"",mid:"같아요",post:".",hit:!0}],ko:"이 옷은 저한테 좀 클 것 같아요.",en:"I think this shirt will be a bit big on me.",romanization:"i o-seun jeo-han-te jom keul geot ga-ta-yo."}],rule:{name:"A/V-(으)ㄹ 것 같아요",rows:[{when:"Verb, future guess",add:"+ -(으)ㄹ 것 같아요",ex:"오다 → 올 것 같아요 (I think it'll come/rain)"},{when:"Adjective, present guess",add:"+ -(으)ㄹ 것 같아요",ex:"비싸다 → 비쌀 것 같아요 (It looks expensive)"},{when:"Past guess (already happened)",add:"-(으)ㄴ 것 같아요",ex:"가다 → 간 것 같아요 (Seems they left)"}]},more:{func:"-(으)ㄹ 것 같아요 means 'I think / it seems / probably.' It softens a statement into a guess about the future or about something uncertain, so it sounds modest and polite. It pairs with this 겠 chapter as the gentler cousin of inference: where 겠네요 is a confident 'must be,' -(으)ㄹ 것 같아요 is a hedged 'I think / probably.'",keyPoint:{label:"겠네요 vs (으)ㄹ 것 같아요",body:"Both are guesses, but the confidence differs. 겠네요 = a confident 'it must be…,' usually a quick reaction to evidence right there (춥겠네요). -(으)ㄹ 것 같아요 = a softer 'I think / probably' that leaves room for doubt (추울 것 같아요). When you want to sound modest or unsure, reach for -(으)ㄹ 것 같아요."},pronunciation:"것 같아요 → [걷 까타요]: the ㄱ of 같- tenses to [까] after the [ㄷ] of 것, and 같아요 links as [가타요]. The ㄹ form tenses too: 올 것 → [올 껃]."}}],canDo:"Soften a statement into a tentative guess with -(으)ㄹ 것 같아요 (끝날 것 같아요)",id:"chapter-58-b7",chapterId:"chapter-58",index:6},{kind:"dialogue",title:"대화 Dialogue · 진짜 한국어",cards:[{kind:"chat",setting:"A workplace chat moves through service commitment, evidence-based inference, and polite refusal.",lines:[{speaker:"직원",ko:"주문은 제가 바로 확인하겠습니다.",en:"I will check the order right away.",romanization:"jumuneun jega baro hwaginhagetseumnida."},{speaker:"손님",ko:"감사합니다. 그럼 조금 기다리겠습니다.",en:"Thank you. Then I will wait a little.",romanization:"gamsahamnida. geureom jogeum gidarigetseumnida."},{speaker:"연구원",ko:"자료를 보니 결과가 달라지겠네요.",en:"Looking at the data, it looks like the result will change.",romanization:"jaryoreul boni gyeolgwa-ga dallajigenneyo."},{speaker:"동료",ko:"그럼 오늘 회의에서는 설명이 좀 어렵겠습니다.",en:"Then in today's meeting, explaining it may be a bit difficult.",romanization:"geureom oneul hoeuieseo-neun seolmyeongi jom eoryeopgetseumnida."},{speaker:"민서",ko:"죄송하지만 오늘은 참석하기 어렵겠습니다.",en:"I'm sorry, but it will be difficult for me to attend today.",romanization:"joesonghajiman oneureun chamseokhagi eoryeopgetseumnida."},{speaker:"지훈",ko:"알겠습니다. 이 일은 제가 처리하겠습니다.",en:"Understood. I will handle this matter.",romanization:"algesseumnida. i ireun jega cheorihagetseumnida."}]},{kind:"order",prompt:"Build: 'I will help you right away.'",tokens:["바로","도와드리겠습니다"],correct:"바로 도와드리겠습니다",explanation:"도와드리겠습니다 is formal and respectful. 바로 adds the service promise “right away.”"}],canDo:"State my own intention politely with V-겠습니다 / V-겠어요 (확인하겠습니다)",id:"chapter-58-b8",chapterId:"chapter-58",index:7},{kind:"reading",title:"읽기 Reading · 겠의 세 가지 얼굴",cards:[{kind:"read",title:"겠의 세 가지 얼굴",chunks:["겠은 단순히 미래를 말하는 표현이 아니에요. 직원이 손님에게 주문을 확인하겠습니다라고 말하면, 그냥 미래 계획이 아니라 지금 책임지고 처리하겠다는 약속처럼 들려요. 반대로 자료를 보니 결과가 달라지겠네요는 자료라는 근거를 보고 내린 추론이에요.","또 죄송하지만 참석하기 어렵겠습니다처럼 말하면 못 가요보다 훨씬 정중하고 부드러운 거절이 돼요. 그래서 겠을 볼 때는 먼저 상황을 봐야 해요. 내가 하겠다는 약속인지, 근거를 보고 추측하는지, 아니면 말을 부드럽게 만드는지 구분해야 자연스럽게 쓸 수 있어요."],translation:"겠 is not simply a future marker. When a staff member says 'I will check the order,' it sounds like a responsible promise, not just a future plan. By contrast, 'Looking at the data, the result will change' is an inference from evidence. And saying 'I'm sorry, but it will be difficult for me to attend' is a much more courteous and softened refusal than simply saying 'I can't go.' So when you see 겠, look at the situation first. Is it a promise that I will do something, an inference from evidence, or a way to soften speech?",qas:[{q:"직원이 확인하겠습니다라고 말하면 어떤 느낌이에요?",a:"책임지고 처리하겠다는 약속처럼 들려요."},{q:"자료를 보니 결과가 달라지겠네요는 어떤 겠이에요?",a:"근거를 보고 내린 추론이에요."},{q:"참석하기 어렵겠습니다는 왜 써요?",a:"거절을 정중하고 부드럽게 말하기 위해 써요."}]}],canDo:"Make a careful inference from evidence with A/V-겠네요 (바쁘겠네요)",id:"chapter-58-b9",chapterId:"chapter-58",index:8},{kind:"boss",title:"보스 Boss bite · 다 걸어요",cards:[{kind:"drill",prompt:"Which sentence is a formal service commitment?",sentence:null,options:[{text:"주문은 제가 바로 확인하겠습니다.",ok:!0},{text:"주문은 제가 바로 확인할 것 같아요.",ok:!1},{text:"주문은 제가 바로 확인했겠네요.",ok:!1}],explanation:"-겠습니다 marks a formal commitment controlled by the speaker."},{kind:"drill",prompt:"Which sentence uses 겠 for inference from evidence?",sentence:null,options:[{text:"자료를 보니 결과가 달라지겠네요.",ok:!0},{text:"자료를 보니 제가 처리하겠습니다.",ok:!1},{text:"자료를 보니 참석하기 어렵겠습니다.",ok:!1}],explanation:"The data gives evidence for the speaker's inference."},{kind:"drill",prompt:"Which sentence is the most courteous formal refusal?",sentence:null,options:[{text:"죄송하지만 오늘은 참석하기 어렵겠습니다.",ok:!0},{text:"오늘 못 가요.",ok:!1},{text:"오늘 참석 안 할 거예요.",ok:!1}],explanation:"어렵겠습니다 softens the refusal in formal speech."},{kind:"drill",prompt:"자료___ 많겠네요. (The materials must be a lot.)",sentence:null,options:[{text:"가",ok:!0},{text:"를",ok:!1},{text:"에",ok:!1}],explanation:"많다 describes the amount of 자료, so 자료 takes 가. 겠네요 gives an inference from what you see or hear."},{kind:"order",prompt:"Build: 'I will help you right away.'",tokens:["바로","도와드리겠습니다"],correct:"바로 도와드리겠습니다",explanation:"도와드리겠습니다 is formal and respectful. 바로 adds the service promise “right away.”"},{kind:"drill",prompt:"Which sentence uses 겠 for inference, not a promise?",sentence:null,options:[{text:"자료가 많겠네요.",ok:!0},{text:"제가 처리하겠습니다.",ok:!1},{text:"제가 참석하겠습니다.",ok:!1}],explanation:"많겠네요 is an inference from evidence. 처리하겠습니다 and 참석하겠습니다 are formal commitments."}],canDo:"Talk about a future plan with V-(으)ㄹ 거예요 (기다릴 거예요)",id:"chapter-58-b10",chapterId:"chapter-58",index:9}]},{id:"chapter-59",number:59,title:"V-았/었으면 좋겠어요 · V-았/었으면 … -았/었을 텐데요",goal:"Build counterfactual sentences from a missed past condition.",biteCount:11,bites:[{kind:"words",title:"단어 Words 1 · 알다~",cards:[{kind:"guess",word:{ko:"알다",romanization:"alda",en:"to know",pos:"verb",nuance:"For a neutral ‘I don't know,’ Korean normally uses 모르다: 몰라요 or the softer 잘 모르겠어요. 안 알아요 is not universally wrong; context can give it ‘I don't recognize/know,’ ‘I won't find out,’ or a contrastive denial, so do not treat it as an impossible form."},sentence:{ko:"미리 알았으면 준비를 더 했을 텐데요.",en:"If I had known in advance, I would have prepared more."},target:"알았",options:["to know","to prepare","to arrive"],note:"알았으면 is one of the most common starting points for regret."},{kind:"guess",word:{ko:"미리",romanization:"miri",en:"in advance, beforehand",pos:"adverb",nuance:"미리 means doing something ahead of the relevant moment so you're ready when it arrives — its whole focus is the timing being early relative to a deadline or event. The classic English-speaker trap is confusing it with 우선 / 먼저 / 일단: 먼저 and 우선 mean 'first in a sequence or in priority' (do A before B), while 미리 means 'before the due time' (do it now so it's done early). 'I paid first' = 먼저 냈어요 (before others), but 'I paid in advance' = 미리 냈어요 (before the due date) — different ideas entirely. 미리 is native Korean, not Sino-Korean, and it glues onto preparation verbs: 미리 예약하다, 미리 준비하다, 미리 확인하다, 미리 알리다. Register is neutral and works in both polite and casual speech. Note the affectionate doubled 미리미리, which nags 'do it good and early.'"},sentence:{ko:"미리 말했더라면 문제가 커지지 않았을 거예요.",en:"If I had said it in advance, the problem would not have gotten bigger."},target:"미리",options:["in advance, beforehand","early","to know"],note:"미리 naturally pairs with 알다, 말하다, 준비하다, and 예약하다."},{kind:"guess",word:{ko:"준비하다",romanization:"junbihada",en:"to prepare",pos:"verb",nuance:"준비하다 comes from 한자 準備 (準 'standard, level' + 備 'provide, equip'), literally 'get equipped to standard' — to ready things or yourself beforehand. It naturally collocates with events and outcomes: 시험을 준비하다, 여행을 준비하다, 저녁을 준비하다, 마음의 준비. Compare 마련하다 ('arrange/procure' funds or a place — 집을 마련하다) and 챙기다 ('gather up, pack' your own belongings — 여권 챙겼어? = did you grab your passport?); 준비하다 is the broad 'prepare,' while 챙기다 zooms in on not forgetting items. The classic English-speaker pitfall is the particle: 'prepare FOR the exam' tempts 시험에 준비하다, but Korean treats the exam as a direct object — 시험을 준비하다. Also don't reach for 만들다 'make' when you only mean getting ready. As a 하다 verb, negate inside (준비 안 해요), and its passive 준비되다 ('be ready') is everywhere: 준비됐어요."},sentence:{ko:"서류를 미리 준비했더라면 접수를 놓치지 않았을 텐데요.",en:"If I had prepared the documents in advance, I would not have missed the application."},target:"준비했",options:["to know","to miss","to prepare"],note:"준비했더라면 turns a practical mistake into a counterfactual condition."},{kind:"guess",word:{ko:"시험",romanization:"siheom",en:"exam",pos:"noun",nuance:"시험 is Sino-Korean 試驗 — 試 'try/test' + 驗 'examine', literally 'a trial examination'. The collocation English speakers must memorize is 시험을 보다 — Koreans 'see' an exam, they do not 'do' it, so 시험을 하다 is wrong. Passing and failing are vivid metaphors with the particle 에: 시험에 붙다 (literally 'stick to the exam') = pass, 시험에 떨어지다 ('fall off the exam') = fail — note these take 에, not 을. Contrast 시험 with 퀴즈(quiz, a small in-class test) and with 검사(檢査, an inspection/medical test like 건강 검사): a graded school test is always 시험, never 퀴즈 unless it is a tiny informal one. The classic 직역 trap is 'take an exam' → 시험을 가지다/취하다 ✗ (English 'take' never transfers); and learners often write 시험을 통과하다, which is understandable but bookish — the everyday word is 붙다."},sentence:{ko:"조금만 일찍 도착했더라면 시험을 볼 수 있었을 거예요.",en:"If I had arrived just a little earlier, I could have taken the exam."},target:"시험",options:["exam","bus","regret"],note:"시험을 보다 is the fixed phrase for taking an exam."},{kind:"guess",word:{ko:"일찍",romanization:"iljjik",en:"early",pos:"adverb",nuance:"일찍 means 'early' in the sense of an EARLY POINT IN TIME — early hour of the day or ahead of a schedule — and is the natural opposite of 늦게(late). The classic confusion is 일찍 vs 빨리: 일찍 is about WHEN on the clock (일찍 일어나요 = 'wake up at an early hour'), while 빨리 is about SPEED/quickness (빨리 일어나요 = 'get up quick!'). So '일찍 오세요' invites someone to arrive at an early time, whereas '빨리 오세요' urges them to hurry. It pairs habitually with 자다, 일어나다, 출근하다, 도착하다, 출발하다. Register-neutral and polite-safe. The English-speaker pitfall is exactly this 일찍/빨리 mix-up, since English 'early' and 'fast/quick' feel adjacent but map to two different Korean adverbs; also remember 일찍 is an adverb already, so you never conjugate it like the adjective 이르다."},sentence:{ko:"조금만 일찍 나왔으면 버스를 놓치지 않았을 텐데요.",en:"If I had left just a little earlier, I would not have missed the bus."},target:"일찍",options:["in advance, beforehand","early","to know"],note:"조금만 일찍 is a very natural regret chunk."},{kind:"guess",word:{ko:"도착하다",romanization:"dochakada",en:"to arrive",pos:"verb",nuance:"도착하다 is Sino-Korean 到着(도착: 到 reach + 着 attach/touch down) plus 하다 — the moment of REACHING and touching a destination. Its mirror is 출발하다(depart), and the key is the particle: you arrive AT a place with 에 (호텔에 도착해요), whereas 출발하다 leaves FROM a place with 에서. Don't confuse it with 들어가다/들어오다(enter): 도착하다 is reaching the destination's threshold, not stepping inside a building. As a 하다 verb, 하 + 아 fuses to 해 (도착해요) and the short negative and inability split the noun off: 도착 안 해요, 도착 못 해요. The classic English-speaker error is copying 'arrive at' as 에서 — 'at' here is the static endpoint 에, so 공항에 도착해요, and 공항에서 도착해요 is wrong."},sentence:{ko:"제시간에 도착했더라면 면접을 볼 수 있었을 거예요.",en:"If I had arrived on time, I could have had the interview."},target:"도착했",options:["to know","to arrive","to miss"],note:"도착했더라면 is useful for exams, interviews, trains, and appointments."},{kind:"payoff",line:{speaker:"민서",ko:"어제 공지를 미리 알았으면 시험 준비를 더 했을 텐데.",en:"If I had known about the notice in advance yesterday, I would have prepared more for the exam."},hl:"알았"}],canDo:"Express a wish that things were different with V-았/었으면 좋겠어요 (일찍 일어났으면 좋겠어요)",id:"chapter-59-b1",chapterId:"chapter-59",index:0},{kind:"pattern",title:"무늬 Pattern · V-았/었으면 좋겠어요",cards:[{kind:"hunt",name:"V-았/었으면 좋겠어요",sub:'a wish ("I wish / I hope")',lines:[{tokens:[{pre:"주말에",mid:"",post:"",hit:!1},{pre:"날씨가",mid:"",post:"",hit:!1},{pre:"좋",mid:"았으면",post:"",hit:!0},{pre:"",mid:"좋겠어요",post:".",hit:!0}],ko:"주말에 날씨가 좋았으면 좋겠어요.",en:"I hope the weather is nice this weekend.",romanization:"jumare nalssiga joasseumyeon jokesseoyo."},{tokens:[{pre:"지금",mid:"",post:"",hit:!1},{pre:"친구가",mid:"",post:"",hit:!1},{pre:"옆에",mid:"",post:"",hit:!1},{pre:"있",mid:"었으면",post:"",hit:!0},{pre:"",mid:"좋겠어요",post:".",hit:!0}],ko:"지금 친구가 옆에 있었으면 좋겠어요.",en:"I wish a friend were here beside me right now.",romanization:"jigeum chinguga yeope isseosseumyeon jokesseoyo."}],rule:{name:"V-았/었으면 좋겠어요",rows:[{when:"Stem ends in ㅏ/ㅗ",add:"-았으면 좋겠어요",ex:"오다 → 봄이 왔으면 좋겠어요 (I wish spring would come)"},{when:"Stem ends in any other vowel",add:"-었으면 좋겠어요",ex:"있다 → 시간이 있었으면 좋겠어요 (I wish I had time)"},{when:"하다 verbs/adjectives",add:"-했으면 좋겠어요",ex:"건강하다 → 건강했으면 좋겠어요 (I hope you stay healthy)"},{when:"Casual register (반말)",add:"-(았/었)으면 좋겠다",ex:"비가 그쳤으면 좋겠다 (I wish the rain would stop)"}]},more:{func:'Expresses a wish that the present situation were different, or a hope for something to come true. The past-shaped -았/었- here is NOT real past tense; it sets the wish against current reality. English renders it as "I wish..." (reality is the opposite) or "I hope..." (still possible).',keyPoint:{label:"-았/었으면 좋겠어요 vs -(으)면 좋겠어요",body:"Both mean 'I wish/hope.' The -았/었- version is by far the more common, natural choice in everyday speech and leans toward wishing reality were currently otherwise. The plain -(으)면 좋겠어요 sounds a bit more like a neutral 'it would be good if...'. When in doubt, use -았/었으면 좋겠어요."},pronunciation:"좋겠어요 is pronounced [조케써요]: the ㅎ of 좋 and the ㄱ of 겠 fuse into aspirated [ㅋ], and 겠어요 links smoothly as [게써요]."}}],canDo:"Express a wish that things were different with V-았/었으면 좋겠어요 (일찍 일어났으면 좋겠어요)",id:"chapter-59-b2",chapterId:"chapter-59",index:1},{kind:"words",title:"단어 Words 2 · 놓치다~",cards:[{kind:"guess",word:{ko:"놓치다",romanization:"nochida",en:"to miss",pos:"verb",nuance:"놓치다 is for missing something you were actively trying to catch or hold — a bus, a train, a flight, a chance, or even the thread of a conversation (요점을 놓치다 = 'miss the point') — and it always takes a 을/를 object. Its make-up shows the meaning: 놓다 ('to let go/release') + 치다, so it literally pictures something slipping out of your grasp. The single biggest English-speaker pitfall is using it for missing a *person*: English 'I miss you' is NOT 놓치다 — that is 보고 싶다 ('want to see'), so 엄마가 보고 싶어요, never 엄마를 놓쳐요. Contrast 놓치다 ('fail to catch what was within reach') with 지나가다/지나치다 ('let pass / pass by'): you 놓치다 a bus you ran for, but a chance that quietly 지나가다 simply went by. It is a regular ㅣ-stem verb: 놓치 + 어 → 놓쳐요, and it frequently appears alongside 늦다 ('be late')."},sentence:{ko:"버스를 놓치지 않았더라면 늦지 않았을 텐데요.",en:"If I had not missed the bus, I would not have been late."},target:"놓치",options:["to know","to miss","to prepare"],note:"Use 놓치다 for transport, chances, deadlines, and timing."},{kind:"guess",word:{ko:"버스",romanization:"beoseu",en:"bus",pos:"noun",nuance:"버스 is useful with 타다, 기다리다, 내리다, and 로/으로 for transportation method."},sentence:{ko:"그 버스를 탔더라면 약속 시간에 맞췄을 거예요.",en:"If I had taken that bus, I would have made it on time for the appointment."},target:"버스",options:["exam","regret","bus"],note:"Transport words make counterfactuals concrete: take it, miss it, arrive late."},{kind:"guess",word:{ko:"후회하다",romanization:"huhoehada",en:"to regret",pos:"verb",nuance:"후회하다 is Sino-Korean — 後悔 literally stacks 後 'after' + 悔 'regret/remorse', i.e. the regret that comes AFTER the deed — and names the painful wish that you had chosen differently. It typically points backward (그 결정을 후회해요 'I regret that decision') and frequently pairs with a reason clause in -아서/어서 or with a past-action nominalizer -(으)ㄴ 걸: 그렇게 말한 걸 후회해. Distinguish it from 아쉽다, which is a milder 'it's a shame / I wish it were a bit different' about things often outside your control, whereas 후회하다 carries genuine self-reproach over your own past action. Also separate it from 미안하다 ('to be sorry' TO someone) — 후회하다 is regret felt inside, not an apology directed at another person. Pitfall: 'I regret to inform you' has no 후회하다 equivalent; that polite-letter formula becomes 안타깝게도 or 죄송하지만. Keep the object with 를, and remember the negative splits as 후회 안 해요."},sentence:{ko:"바로 사과했더라면 이렇게 후회하지 않았을 거예요.",en:"If I had apologized right away, I would not regret it like this."},target:"후회하",options:["to know","to regret","to prepare"],note:"후회하다 often appears in the result clause."},{kind:"guess",word:{ko:"후회",romanization:"huhoe",en:"regret",pos:"noun",nuance:"후회 is regret aimed squarely *backward* at a choice you already made, with a sting of self-blame. It is Sino-Korean 後悔 (後 'after/behind' + 悔 'to repent'), literally 'after-regret', the regret that comes *after* the deed. The verb 후회하다 is everyday, but the noun surfaces in lines like 후회예요 or 후회가 남아요, and the motto 후회 없이 (without regret) is hugely popular among 20-30s. The key synonym contrast is 후회 vs 아쉬움: 후회 blames *your own* decision ('I shouldn't have done that'), while 아쉬움 is a softer, fate-tinged 'aw, what a shame it didn't work out' with little self-blame. The English-speaker trap is mapping 'I regret it' straight to 후회해요 when you actually want the noun-predicate 후회예요 ('it's a regret'), and reaching for 후회 when the gentle 아쉬움 is what the situation calls for."},sentence:{ko:"그때 말하지 않은 게 아직도 후회예요.",en:"Not saying it back then is still a regret."},target:"후회",options:["exam","bus","regret"],note:"Noun form 후회 works when the regret itself is the topic."},{kind:"guess",word:{ko:"결과",romanization:"gyeolgwa",en:"result, outcome",pos:"noun",nuance:"결과 (結果, literally '結 form/bear + 果 fruit', i.e. the fruit that an action bears) is the end outcome of an action or event, and it almost always pairs with 나오다 (come out) or 나타나다 (appear) rather than any verb of 'making'. Its built-in partner is 과정 (the process leading up to it) and its mirror image is 원인 (the cause behind it), so Koreans constantly say 과정도 중요하고 결과도 중요하다. Register is neutral — fine in a doctor's office (검사 결과), a classroom (시험 결과), or a news report. The big English-speaker trap is twofold: first, you do not 'get' a result with a transitive verb the way English does — the result 나오다 (comes out) on its own and takes 이/가, so 결과를 나오다 is wrong; second, do not confuse the outcome 결과 with the reason 원인/이유 — 결과 is what happened at the end, never why."},sentence:{ko:"마지막까지 포기하지 않았더라면 결과가 달라졌을지도 몰라요.",en:"If I had not given up until the end, the result might have changed."},target:"결과",options:["exam","bus","result, outcome"],note:"결과가 달라지다 is the key outcome phrase."},{kind:"guess",word:{ko:"달라지다",romanization:"dallajida",en:"to change, to become different",pos:"verb",nuance:"달라지다 spotlights the before-and-after gap: something is now clearly unlike how it used to be, which makes it the everyday verb for noticing change in a person's looks, mood, or a situation. It's the inchoative of the adjective 다르다 (to be different) — 다르 + -아지다 'become' — and that origin is the #1 pitfall: 다르다 states a static difference between two things (A는 B와 달라요 = A is different from B), while 달라지다 is the dynamic act of becoming different over time (분위기가 달라졌어요 = the mood changed). It overlaps with 변하다 and 바뀌다, but the dividing line is focus: 달라지다 = 'the result looks different now,' 변하다 = 'the inner nature transformed,' 바뀌다 = 'one thing got swapped for another.' Both 달라지다 and the thing changing take 이/가; the form 달라져요 comes from -지다 verbs taking 어 in the 요-form (지+어 → 져)."},sentence:{ko:"그때 선택을 바꿨더라면 지금 상황이 달라졌을 거예요.",en:"If I had changed my choice then, the situation would be different now."},target:"달라졌",options:["to know","to change, to become different","to prepare"],note:"달라졌을 거예요 is a natural result clause for counterfactuals."},{kind:"payoff",line:{speaker:"민서",ko:"맞아. 결과가 조금은 달라졌을 것 같아.",en:"You're right. The result might have been a little different."},hl:"결과"}],canDo:"Regret a missed past with V-았/었으면 … -았/었을 텐데요 (도착했으면 … 봤을 텐데요)",id:"chapter-59-b3",chapterId:"chapter-59",index:2},{kind:"pattern",title:"무늬 Pattern · V-았/었으면 … -았/었을 텐데요",cards:[{kind:"hunt",name:"V-았/었으면 … -았/었을 텐데요",sub:"a past counterfactual with regret",lines:[{tokens:[{pre:"미리",mid:"",post:"",hit:!1},{pre:"공지를",mid:"",post:"",hit:!1},{pre:"알",mid:"았으면",post:"",hit:!0},{pre:"시험",mid:"",post:"",hit:!1},{pre:"준비를",mid:"",post:"",hit:!1},{pre:"더",mid:"",post:"",hit:!1},{pre:"했",mid:"을",post:"",hit:!0},{pre:"",mid:"텐데요",post:".",hit:!0}],ko:"미리 공지를 알았으면 시험 준비를 더 했을 텐데요.",en:"If I had known about the notice in advance, I would have prepared more for the exam.",romanization:"miri gongjireul arasseumyeon siheom junbireul deo haesseul tendeyo."},{tokens:[{pre:"조금만",mid:"",post:"",hit:!1},{pre:"더",mid:"",post:"",hit:!1},{pre:"일찍",mid:"",post:"",hit:!1},{pre:"일어났",mid:"으면",post:"",hit:!0},{pre:"버스를",mid:"",post:"",hit:!1},{pre:"탔",mid:"을",post:"",hit:!0},{pre:"",mid:"텐데요",post:".",hit:!0}],ko:"조금만 더 일찍 일어났으면 버스를 탔을 텐데요.",en:"If I had gotten up just a little earlier, I would have caught the bus.",romanization:"jogeumman deo iljjik ireonasseumyeon beoseureul tasseul tendeyo."}],rule:{name:"V-았/었으면 … -았/었을 텐데요",rows:[{when:"Condition: stem + 았/었 + 으면",add:"-았/었으면",ex:"알다 → 알았으면 (if I had known)"},{when:"Result: stem + 았/었 + 을 텐데요",add:"-았/었을 텐데요",ex:"가다 → 갔을 텐데요 (I would have gone)"},{when:"하다 verbs",add:"-했으면 / -했을 텐데요",ex:"공부했으면 합격했을 텐데요 (if I'd studied, I'd have passed)"},{when:"Whole frame",add:"A-았/었으면 B-았/었을 텐데요",ex:"일찍 출발했으면 안 늦었을 텐데요 (if I'd left early, I wouldn't have been late)"}]},more:{func:"States a counterfactual about the past: a condition that did NOT happen, and the result that therefore did NOT happen. -았/었으면 marks the unreal past condition; the result clause stays hypothetical with -았/었을 텐데요 ('would have...'). The 텐데 ending softens it into a wistful 'but it wasn't so.'",keyPoint:{label:"Keep the result clause hypothetical",body:"Whichever condition you use, the result must also be marked unreal: -았/었을 텐데요, -았/었을 거예요, or -았/었을지도 몰라요 ('might have'). Never finish a past counterfactual with a plain past or present verb — that cancels the 'would have' meaning. 텐데요 adds the softest, most wistful tone of the three."},pronunciation:"텐데요 is [텐데요], no special change. Note 갔을 텐데요 → [가쓸 텐데요]: 갔 closes as [갇] and links into 을 as [가쓸]."}}],canDo:"Regret a missed past with V-았/었으면 … -았/었을 텐데요 (도착했으면 … 봤을 텐데요)",id:"chapter-59-b4",chapterId:"chapter-59",index:3},{kind:"words",title:"단어 Words 3 · 기회~",cards:[{kind:"guess",word:{ko:"기회",romanization:"gihoe",en:"chance, opportunity",pos:"noun",nuance:"기회 (機會, 機 'opportune moment/device' + 會 'meeting') is a window of opportunity that may not come twice, so it carries a faint pressure to act. The key contrast is 기회 vs 기능: 기회 is a chance to do something, while 기능 is a 'function/feature.' Koreans treat 기회 as something you physically handle — 기회를 잡다 (seize), 기회를 놓치다 (miss), 기회를 주다/얻다 (give/get) — so the partner verb is concrete, never 기회를 하다. With existence it is 기회가 있다/없다, and 기회가 되면 is a gentle, non-committal 'if the chance comes up.' The English-speaker trap is twofold: don't say 기회를 하다 by mapping 'take a chance' word-for-word, and don't mark existence with 를 (기회를 있다 ✗ → 기회가 있다 ✓). Register is neutral, fine in both polite speech and writing."},sentence:{ko:"그 기회를 잡았더라면 다른 회사에 갔을지도 몰라요.",en:"If I had taken that opportunity, I might have gone to a different company."},target:"기회",options:["chance, opportunity","exam","bus"],note:"기회를 잡다 and 기회를 놓치다 are both useful in hindsight."},{kind:"guess",word:{ko:"말하다",romanization:"malhada",en:"to say, to speak",pos:"verb",nuance:"Use 로 for language: 한국어로 말해요, 영어로 말해요. 말하다 can mean both “speak” and “say,” so the object or quote decides the English translation."},sentence:{ko:"그때 솔직하게 말했더라면 오해가 풀렸을 거예요.",en:"If I had spoken honestly then, the misunderstanding would have cleared up."},target:"말했",options:["to know","to say, to speak","to prepare"],note:"말하다 becomes powerful in regret scenes because one sentence could have changed the relationship."},{kind:"guess",word:{ko:"사과하다",romanization:"sagwahada",en:"to apologize",pos:"verb",nuance:"사과하다 is 謝過(사과)하다, hanja 謝 'express thanks/apology' + 過 'fault/error', so it literally means to 'acknowledge one's fault' — you take responsibility for a mistake to the person you wronged, who is marked with 에게/한테 or honorific 께. The boundary against 미안하다 and 변명하다 is essential: 미안하다 is the adjective/feeling 'to be sorry' (an emotional state — 미안해요), while 사과하다 is the ACT of formally apologizing (you can 사과하다 even publicly or in writing); and 변명하다 is the opposite move, to 'make excuses.' So you might 사과하다 instead of merely feeling 미안하다. The cause of the apology attaches with -아서: 늦어서 사과했어요. A notorious trap is the homograph: 사과 also means 'apple' (native-Korean noun), so context disambiguates 사과를 했어요 'apologized' from 사과를 먹었어요 'ate an apple' — they share spelling but are unrelated words. English speakers also wrongly say '~에 대해 미안해요' as if 'sorry' were a verb taking objects; to apologize FOR something, use 사과하다 with -아서 or -에 대해. Regular 하다 verb: 사과 + 해요, negative 사과 안 해요."},sentence:{ko:"먼저 사과했더라면 아직 어색하지 않았을 텐데요.",en:"If I had apologized first, it would not still be awkward."},target:"사과했",options:["to know","to apologize","to prepare"],note:"사과했더라면 fits relationship repair after the fact."},{kind:"guess",word:{ko:"그때",romanization:"geuttae",en:"that time, back then",pos:"noun",nuance:"그때 is the demonstrative 그 ('that', the listener-known one) fused with 때 ('time, occasion'), so it points at a specific moment both speakers can already identify — looking back ('back then') or to a plan just arranged ('see you then'). Write it solid as 그때; the spaced 그 때 is non-standard. Mind the demonstrative trio that mirrors 이/그/저: 이때 = this moment / now in the flow of events, 그때 = that known moment, and the question 언제 = 'when?'. The key English-speaker pitfall is the 'that' default: because English freely says 'that time' for brand-new information, learners reach for 그때 even when the listener has no idea which moment is meant. But 그때 presupposes shared knowledge — if the time is new to your listener you must first establish it (give the date or event), and only then can 그때 refer back to it."},sentence:{ko:"그때 멈췄더라면 일이 이렇게 커지지 않았을 거예요.",en:"If I had stopped back then, this would not have gotten this big."},target:"그때",options:["exam","that time, back then","bus"],note:"그때 anchors the regret in a specific past moment."},{kind:"guess",word:{ko:"포기하다",romanization:"pogihada",en:"to give up",pos:"verb",nuance:"포기하다 = to give up, abandon, or relinquish a goal, plan, claim, or even a person. The hanja 抛棄 is vivid: 抛 'to throw/hurl away' + 棄 'to discard, abandon', so the image is hurling something aside and walking off — a decisive letting-go, not a gentle fade. Contrast 포기하다 (stop pursuing a goal entirely) with 그만두다 (stop/quit an ongoing activity — a job, a habit) and with 단념하다 (a more bookish 'resign oneself to abandoning hope'); in speech 포기하다 is the everyday choice. Grammar: it pairs with 을/를 (목표를 포기하다) or with 는 거 / 는 걸 (사는 걸 포기하다 = 'give up on buying'). Culturally the word is loaded: N포세대, the 'give-up generation', names young Koreans said to have surrendered dating, marriage, and kids to economic pressure. English-speaker pitfall: the negative is 포기 안 해 / 포기 못 해 (noun + 안/못 + 해), NOT 안 포기해."},sentence:{ko:"포기하지 않았더라면 합격했을지도 몰라요.",en:"If I had not given up, I might have passed."},target:"포기하",options:["to know","to prepare","to give up"],note:"포기하지 않았더라면 is a high-frequency negative counterfactual."},{kind:"guess",word:{ko:"합격하다",romanization:"hapgyeokada",en:"to pass an exam",pos:"verb",nuance:"합격하다 is Sino-Korean 合格 — 合 'meet/match' + 格 'standard' — literally 'meet the standard', i.e. clear a cut-off and pass a test, interview, or admissions screen. Its opposite is 불합격하다 (不合格) or, much more colloquially, 떨어지다 'to fall/drop' (시험에 떨어졌어요 = I failed/flunked). Don't confuse 합격하다 with 통과하다 'to pass through': 통과하다 is moving past a checkpoint or a bill passing, while 합격하다 specifically means meeting a qualifying standard. The headline English-speaker pitfall is the particle: English 'pass THE exam' (object) makes learners write 시험을 합격하다, but Korean uses 에 — 시험에 합격하다 — because you're 'matching up TO the standard'. Note also 합격하다 (verb) vs 합격 (the noun, 'a pass/acceptance'): the noun is what you put on banners — 합격 축하해! As a noun+하다 verb it conjugates on 하다 (합격해요, 합격했어요, formal 합격합니다); negative/impossible split the noun (합격 안 해요, 합격 못 해요)."},sentence:{ko:"마지막 문제를 풀었더라면 합격했을 거예요.",en:"If I had solved the last question, I would have passed."},target:"합격했",options:["to know","to pass an exam","to prepare"],note:"합격하다 belongs naturally in exam-regret counterfactuals."},{kind:"payoff",line:{speaker:"지훈",ko:"그래도 포기하지 않았더라면 마지막 문제는 풀 수 있었을지도 몰라.",en:"Still, if you had not given up, you might have been able to solve the last question."},hl:"포기하"}],canDo:"State a reflective counterfactual with V-았/었더라면 … -았/었을 거예요 (준비했더라면 … 놓치지 않았을 거예요)",id:"chapter-59-b5",chapterId:"chapter-59",index:4},{kind:"pattern",title:"무늬 Pattern · V-았/었더라면 … -았/었을 거예요",cards:[{kind:"hunt",name:"V-았/었더라면 … -았/었을 거예요",sub:"a stronger, more reflective counterfactual",lines:[{tokens:[{pre:"조금만",mid:"",post:"",hit:!1},{pre:"일찍",mid:"",post:"",hit:!1},{pre:"도착했",mid:"더라면",post:"",hit:!0},{pre:"시험을",mid:"",post:"",hit:!1},{pre:"볼",mid:"",post:"",hit:!1},{pre:"수",mid:"",post:"",hit:!1},{pre:"있",mid:"었을",post:"",hit:!0},{pre:"",mid:"거예요",post:".",hit:!0}],ko:"조금만 일찍 도착했더라면 시험을 볼 수 있었을 거예요.",en:"If I had arrived just a little earlier, I could have taken the exam.",romanization:"jogeumman iljjik dochakaetdeoramyeon siheomeul bol su isseosseul geoyeyo."},{tokens:[{pre:"그",mid:"",post:"",hit:!1},{pre:"소식을",mid:"",post:"",hit:!1},{pre:"들",mid:"었더라면",post:"",hit:!0},{pre:"바로",mid:"",post:"",hit:!1},{pre:"전화했",mid:"을",post:"",hit:!0},{pre:"",mid:"거예요",post:".",hit:!0}],ko:"그 소식을 들었더라면 바로 전화했을 거예요.",en:"If I had heard the news, I would have called right away.",romanization:"geu sosigeul deureotdeoramyeon baro jeonhwahaesseul geoyeyo."}],rule:{name:"V-았/었더라면 … -았/었을 거예요",rows:[{when:"Condition: stem + 았/었 + 더라면",add:"-았/었더라면",ex:"도착하다 → 도착했더라면 (if I had arrived)"},{when:"Result: stem + 았/었 + 을 거예요",add:"-았/었을 거예요",ex:"보다 → 봤을 거예요 (I would have seen it)"},{when:"하다 verbs",add:"-했더라면",ex:"공부했더라면 (if I had studied)"},{when:"Whole frame",add:"A-았/었더라면 B-았/었을 거예요",ex:"조금만 일찍 도착했더라면 시험을 봤을 거예요 (if I'd arrived a bit earlier, I'd have taken the exam)"}]},more:{func:"Replays a missed past from a reflective distance: 'if (only) it had happened, the result would have...'. -았/었더라면 marks the unreal past condition with a heavier, more regretful tone than -았/었으면; the result stays hypothetical with -았/었을 거예요 ('would have').",keyPoint:{label:"-았/었더라면 vs -았/었으면",body:"Both open a past counterfactual, but -았/었더라면 is heavier and more clearly regretful — it almost always implies 'and that's a shame, because it didn't happen.' -았/었으면 is more neutral and far more common in casual speech. In friendly chat 더라면 can sound dramatic, so friends often just use -았/었으면. The result clause stays hypothetical either way."},pronunciation:"봤더라면 → [봗떠라면]: the ㅆ of 봤 closes to [ㄷ] before a consonant, and ㄷ of 더 tenses to [떠]. 들었더라면 → [드럳떠라면] follows the same tensing."}}],canDo:"State a reflective counterfactual with V-았/었더라면 … -았/었을 거예요 (준비했더라면 … 놓치지 않았을 거예요)",id:"chapter-59-b6",chapterId:"chapter-59",index:5},{kind:"pattern",title:"무늬 Pattern · V-지 않았더라면",cards:[{kind:"hunt",name:"V-지 않았더라면",sub:`a negative counterfactual ("if … hadn't …")`,lines:[{tokens:[{pre:"버스를",mid:"",post:"",hit:!1},{pre:"놓치",mid:"지",post:"",hit:!0},{pre:"",mid:"않았더라면",post:"",hit:!0},{pre:"면접에",mid:"",post:"",hit:!1},{pre:"늦지",mid:"",post:"",hit:!1},{pre:"않았을",mid:"",post:"",hit:!1},{pre:"텐데요.",mid:"",post:"",hit:!1}],ko:"버스를 놓치지 않았더라면 면접에 늦지 않았을 텐데요.",en:"If I hadn't missed the bus, I wouldn't have been late for the interview.",romanization:"beoseureul nochiji anatdeoramyeon myeonjeobe neutji anasseul tendeyo."},{tokens:[{pre:"포기하",mid:"지",post:"",hit:!0},{pre:"",mid:"않았더라면",post:"",hit:!0},{pre:"합격했을지도",mid:"",post:"",hit:!1},{pre:"몰라요.",mid:"",post:"",hit:!1}],ko:"포기하지 않았더라면 합격했을지도 몰라요.",en:"If I hadn't given up, I might have passed.",romanization:"pogihaji anatdeoramyeon hapgyeokaesseuljido mollayo."}],rule:{name:"V-지 않았더라면",rows:[{when:"Long negation (standard)",add:"V-지 않았더라면",ex:"놓치다 → 놓치지 않았더라면 (if I hadn't missed it)"},{when:"Short negation 안",add:"안 + V-았/었더라면",ex:"안 갔더라면 (if I hadn't gone)"},{when:"Inability 못",add:"못 + V-았/었더라면",ex:"못 봤더라면 (if I hadn't been able to see it)"},{when:"Result clause",add:"-았/었을 거예요 / -았/었을 텐데요",ex:"포기하지 않았더라면 합격했을지도 몰라요 (if I hadn't given up, I might have passed)"}]},more:{func:"Forms the negative side of a past counterfactual: 'if (something) had NOT happened.' Because the event DID happen, a certain (often bad) result followed — and you imagine the opposite past. It pairs with a hypothetical result clause.",keyPoint:{label:"-지 않았더라면 vs -았/었더라면",body:"Use affirmative -았/었더라면 to imagine an action you wish HAD happened ('if I had studied'). Use -지 않았더라면 to imagine an action you wish had NOT happened ('if I hadn't missed it'). The result clause works identically for both; only the polarity of the condition changes."},pronunciation:"않았더라면 → [아낟떠라면]: the ㅎ of 않 is silent so 않았 reads [아낟] (the ㅆ closing to [ㄷ] before 더), and 더 tenses to [떠]."}}],canDo:"Tell an open condition (-(으)면) from a missed one (-았/었으면)",id:"chapter-59-b7",chapterId:"chapter-59",index:6},{kind:"pattern",title:"무늬 Pattern · -(으)면 vs -았/었으면",cards:[{kind:"hunt",name:"-(으)면 vs -았/었으면",sub:"open condition vs missed condition",lines:[{tokens:[{pre:"시간이",mid:"",post:"",hit:!1},{pre:"있",mid:"으면",post:"",hit:!0},{pre:"같이",mid:"",post:"",hit:!1},{pre:"확인해요.",mid:"",post:"",hit:!1}],ko:"시간이 있으면 같이 확인해요.",en:"If you have time, let's check it together.",romanization:"sigani isseumyeon gachi hwaginhaeyo."},{tokens:[{pre:"시간이",mid:"",post:"",hit:!1},{pre:"있",mid:"었으면",post:"",hit:!0},{pre:"같이",mid:"",post:"",hit:!1},{pre:"확인했을",mid:"",post:"",hit:!1},{pre:"텐데요.",mid:"",post:"",hit:!1}],ko:"시간이 있었으면 같이 확인했을 텐데요.",en:"If there had been time, we would have checked it together.",romanization:"sigani isseosseumyeon gachi hwaginhaesseul tendeyo."}],rule:{name:"-(으)면 vs -았/었으면",rows:[{when:"Open if/when condition",add:"V-(으)면",ex:"시간이 있으면 같이 확인해요 (if you have time, let's check together)"},{when:"Missed/unreal past condition",add:"V-았/었으면",ex:"시간이 있었으면 같이 확인했을 텐데요 (if there had been time, we'd have checked)"},{when:"하다 verbs",add:"-하면 / -했으면",ex:"준비하면 덜 불안해요 / 준비했으면 안 늦었을 텐데요"},{when:"Reusable rule (always V-(으)면)",add:"V-(으)면",ex:"미리 준비하면 덜 불안해요 (if you prepare ahead, you feel less anxious)"}]},more:{func:"Distinguishes a real, still-open condition from an unreal, already-missed one. Plain V-(으)면 leaves the door open ('if/when you have time'). Past-shaped V-았/었으면 usually looks backward at a condition that did NOT happen, setting up a counterfactual result.",keyPoint:{label:"Let context and the result decide the reading",body:"The past form alone doesn't always mean counterfactual — context and the result clause decide. A simple test: can the condition still happen? If yes, plain V-(으)면 with a real result is usually enough. If it's already too late, use V-았/었으면 and keep the result unreal (-았/었을 텐데요 / -았/었을 거예요)."},pronunciation:"있었으면 → [이써쓰면]: 있 closes as [읻] then links into 었 as [이써], and 었으면 connects as [쓰면]. 있으면 (open) stays lighter as [이쓰면]."}}],canDo:"Express a wish that things were different with V-았/었으면 좋겠어요 (일찍 일어났으면 좋겠어요)",id:"chapter-59-b8",chapterId:"chapter-59",index:7},{kind:"dialogue",title:"대화 Dialogue · 진짜 한국어",cards:[{kind:"chat",setting:"Two friends compare three regrets after a hard week: a missed notice, a missed bus, and a message that should have been sent sooner.",lines:[{speaker:"민서",ko:"어제 공지를 미리 알았으면 시험 준비를 더 했을 텐데.",en:"If I had known about the notice in advance yesterday, I would have prepared more for the exam.",romanization:"eoje gongjireul miri arasseumyeon siheom junbireul deo haesseul tende."},{speaker:"지훈",ko:"그래도 포기하지 않았더라면 마지막 문제는 풀 수 있었을지도 몰라.",en:"Still, if you had not given up, you might have been able to solve the last question.",romanization:"geuraedo pogihaji anatdeoramyeon majimak munjeneun pul su isseosseuljido molla."},{speaker:"민서",ko:"맞아. 결과가 조금은 달라졌을 것 같아.",en:"You're right. The result might have been a little different.",romanization:"maja. gyeolgwaga jogeumeun dallajyeosseul geot gata."},{speaker:"지훈",ko:"나는 버스를 놓치지 않았더라면 면접에 늦지 않았을 텐데.",en:"If I had not missed the bus, I would not have been late for the interview.",romanization:"naneun beoseureul notchiji anatdeoramyeon myeonjeobe neutji anatseul tende."},{speaker:"민서",ko:"그때 다른 길로 갔으면 도착 시간이 달라졌을지도 몰라.",en:"If you had taken a different route then, the arrival time might have changed.",romanization:"geuttae dareun gillo gasseumyeon dochak sigani dallajyeosseuljido molla."},{speaker:"지훈",ko:"그리고 친구한테 바로 사과했더라면 아직 이렇게 어색하지는 않았을 거야.",en:"And if I had apologized to my friend right away, it probably would not still be this awkward.",romanization:"geurigo chinguhante baro sagwahaetdeoramyeon ajik ireoke eosaekajineun anatseul geoya."}]},{kind:"order",prompt:"Build: 'If I had known in advance, I would have prepared.'",tokens:["미리 알았더라면","준비했을 거예요"],correct:"미리 알았더라면 준비했을 거예요",explanation:"The condition is a missed past condition, so 알았더라면 fits. The result stays hypothetical with 했을 거예요."}],canDo:"Express a wish that things were different with V-았/었으면 좋겠어요 (일찍 일어났으면 좋겠어요)",id:"chapter-59-b9",chapterId:"chapter-59",index:8},{kind:"reading",title:"읽기 Reading · 그때 알았더라면",cards:[{kind:"read",title:"그때 알았더라면",chunks:["민서는 시험 전날 공지가 바뀐 것을 늦게 알았다. 미리 알았으면 자료를 다시 확인했을 텐데, 그대로 시험장에 갔다. 지훈은 면접 날 버스를 놓쳤다. 조금만 일찍 나왔더라면 제시간에 도착했을 거라고 생각했다.",'두 사람은 나중에 서로의 이야기를 듣고 같은 말을 했다. "그때 바로 알았더라면 결과가 달라졌을지도 몰라." 하지만 마지막에는 후회만 반복하지 않기로 했다. 다음에는 중요한 공지를 미리 확인하고, 늦을 것 같으면 바로 연락하고, 마음에 걸리는 말은 빨리 사과하기로 했다.'],translation:`Minseo found out late that the notice had changed before the exam. If she had known in advance, she would have checked the materials again, but she went to the exam room as she was. Jihoon missed the bus on interview day. He thought that if he had left a little earlier, he would have arrived on time. Later, after hearing each other's stories, they said the same thing: "If we had known right away back then, the result might have changed." In the end, they decided not to repeat only regret. Next time they would check important notices in advance, contact people right away if they might be late, and apologize quickly for words that bothered them.`,qas:[{q:"민서는 무엇을 늦게 알았어요?",a:"시험 전날 공지가 바뀐 것을 늦게 알았어요."},{q:"지훈은 왜 면접에 늦을 뻔했어요?",a:"버스를 놓쳤기 때문이에요."},{q:"두 사람은 다음에 무엇을 하기로 했어요?",a:"중요한 공지를 미리 확인하고, 늦을 것 같으면 바로 연락하고, 마음에 걸리는 말은 빨리 사과하기로 했어요."}]}],canDo:"Regret a missed past with V-았/었으면 … -았/었을 텐데요 (도착했으면 … 봤을 텐데요)",id:"chapter-59-b10",chapterId:"chapter-59",index:9},{kind:"boss",title:"보스 Boss bite · 다 걸어요",cards:[{kind:"drill",prompt:"Which sentence correctly expresses regret about not knowing earlier?",sentence:null,options:[{text:"미리 알았으면 준비했을 텐데요.",ok:!0},{text:"미리 알면 준비했어요.",ok:!1},{text:"미리 알기로 준비했어요.",ok:!1}],explanation:"The condition is missed in the past, and the result is also hypothetical with -했을 텐데요."},{kind:"drill",prompt:"Choose the correct negative counterfactual.",sentence:null,options:[{text:"놓치지 않았더라면 늦지 않았을 거예요.",ok:!0},{text:"놓치지 않으면더라면 늦지 않았어요.",ok:!1},{text:"놓치지 않았으면 늦지 않아요.",ok:!1}],explanation:"The negative must be inside the past condition: -지 않았더라면."},{kind:"drill",prompt:"Which result clause stays hypothetical?",sentence:null,options:[{text:"결과가 달라졌을지도 몰라요.",ok:!0},{text:"결과가 달라져요.",ok:!1},{text:"결과가 달라지고 있어요.",ok:!1}],explanation:"-았/었을지도 몰라요 marks an imagined different result."},{kind:"drill",prompt:"버스___ 놓쳤더라면 늦었을 거예요. (If I had missed the bus...)",sentence:null,options:[{text:"를",ok:!0},{text:"가",ok:!1},{text:"에",ok:!1}],explanation:"놓치다 takes the thing missed as an object, so 버스를 fits. The counterfactual ending shows this did not actually happen."},{kind:"order",prompt:"Build: 'If I had known in advance, I would have prepared.'",tokens:["미리 알았더라면","준비했을 거예요"],correct:"미리 알았더라면 준비했을 거예요",explanation:"The condition is a missed past condition, so 알았더라면 fits. The result stays hypothetical with 했을 거예요."},{kind:"drill",prompt:"Which condition is clearly about a missed past chance?",sentence:null,options:[{text:"일찍 도착했더라면 만났을 거예요.",ok:!0},{text:"일찍 도착하면 만나요.",ok:!1},{text:"일찍 도착해서 만났어요.",ok:!1}],explanation:"-았/었더라면 points to a past condition that did not happen. The other choices are open condition or real past result."}],canDo:"State a reflective counterfactual with V-았/었더라면 … -았/었을 거예요 (준비했더라면 … 놓치지 않았을 거예요)",id:"chapter-59-b11",chapterId:"chapter-59",index:10}]},{id:"chapter-60",number:60,title:"V-기 · V-는 것/거",goal:"Choose -기 for activity labels, goals, and fixed frames such as 기로 했어요, 기 전에, 기 위해, and 기 시작하다.",biteCount:12,bites:[{kind:"words",title:"단어 Words 1 · 운동하다~",cards:[{kind:"guess",word:{ko:"운동하다",romanization:"undonghada",en:"to exercise",pos:"verb",nuance:"운동하다 = 한자 運動 (運 'move, transport' + 動 'move') + 하다, literally 'movement-movement,' i.e. to physically exercise. The same noun 운동 also means a sports movement or a social campaign, but with 하다 it's working out. A key feature for learners: Korean builds most sports the same way — noun + 하다 (축구하다 play soccer, 수영하다 swim), though racket sports take 치다 'hit' instead (테니스 치다). The contrast with 놀다 ('play, hang out, have fun') matters: 놀다 is unstructured fun, 운동하다 is purposeful physical activity, so don't say 놀다 when you mean training. Natural collocations: 헬스장에서 운동하다, 건강을 위해 운동하다, 운동 부족. As a 하다 verb the negatives split — 운동 안 해요, 운동 못 해요 — and you can swap in 운동을 안 하다 with the object marker for a touch more emphasis."},sentence:{ko:"운동하기는 어렵지만 건강에 좋아요.",en:"Exercising is hard, but it is good for your health."},target:"운동하",options:["to exercise","to walk","to memorize"],note:"Use -기 when 운동하다 becomes an activity label."},{kind:"guess",word:{ko:"운동",romanization:"undong",en:"exercise",pos:"noun",nuance:"운동 is Sino-Korean, 運動 ('move-motion'), and is the umbrella word for physical exercise; it normally appears as 운동하다 (운동을 해요). Crucially it is NOT counted or pluralized like English 'a workout' — you don't say 운동들 for several sessions; you say 운동을 자주 해요. The nearest relative is 스포츠 (a borrowed word for organized sports as a category, e.g. watching 스포츠 on TV), whereas 운동 is the act of exercising your own body, so '운동선수' = athlete but '스포츠 경기' = a sports match. The very same 運動 also means a social 'movement/campaign' (민주화 운동 the democracy movement), so context decides. The English-speaker pitfall is reaching for 만들다 ('make') by analogy with 'make exercise' — Korean uses the light verb 하다; and remember the desire ending goes on the verb (운동하고 싶어요), never on the bare noun."},sentence:{ko:"운동을 시작하기 전에 목표를 정했어요.",en:"Before starting exercise, I set a goal."},target:"운동",options:["study, studying","exercise","habit"],note:"운동 is already a noun, so it can take 을 before 시작하다."},{kind:"guess",word:{ko:"공부하다",romanization:"gongbuhada",en:"to study",pos:"verb",nuance:"공부하다 is noun + 하다, so the short negative is often 공부 안 해요."},sentence:{ko:"공부하기 전에 오늘 목표를 먼저 써요.",en:"Before studying, I write today's goal first."},target:"공부하",options:["to study","to exercise","to walk"],note:"기 전에 is the natural before-doing frame."},{kind:"guess",word:{ko:"공부",romanization:"gongbu",en:"study, studying",pos:"noun",nuance:"공부(工夫)는 한자 그대로 '공을 들여 애씀'이라는 뜻으로, 지식이나 기술을 배우고 익히는 모든 활동을 가리키는 가장 기본적인 단어예요. 비슷한 말 '학습'은 교과서나 보고서에 어울리는 딱딱한 한자어라 일상 대화에서는 거의 안 쓰고, '연습'은 이미 배운 것을 몸에 익히려 반복하는 것이라 '머리로 새로 익히는' 공부와는 결이 달라요. 영어 study처럼 목적어를 바로 붙여 '공부 Korean'이라고 하면 안 되고, 반드시 '한국어를 공부하다'처럼 -을/를을 쓰거나 '한국어 공부를 하다'로 명사화해야 해요. 동사로 쓸 때 '공부를 하다'와 한 단어 '공부하다'가 둘 다 자연스럽고, '열심히/같이/매일'과 잘 어울려요."},sentence:{ko:"공부를 시작하기 전에 책상을 정리해요.",en:"Before starting my studying, I clear my desk."},target:"공부",options:["exercise","habit","study, studying"],note:"공부 is a noun; 공부를 시작하다 is different from 공부하기 시작하다 but both are useful."},{kind:"guess",word:{ko:"걷다",romanization:"geotda",en:"to walk",pos:"verb",nuance:"걷다 means to walk on foot and is a ㄷ irregular verb: before a vowel ending the final ㄷ softens to ㄹ, so the 요-form is 걸어요 (not 걷어요) and the past is 걸었어요. Before a consonant ending the ㄷ stays put, so the formal form remains 걷습니다 and you say 걷지 마세요, 걷고 싶어요. The nearest relative is 산책하다 ('take a stroll'): 걷다 is the raw act of walking anywhere, while 산책하다 implies a leisurely walk for pleasure, so 'I walk to work' is 걸어서 출근해요, never 산책해서 출근해요. The trap for English speakers is that 걷다 doesn't take an object the way 'walk the dog' does — Korean uses 산책시키다 for that, and the path you walk takes 을/를 (공원을 걸어요), so don't reach for 에. Also remember 걸어서 ('on foot') is one fixed chunk for describing how you travel."},sentence:{ko:"저는 먼저 걷기부터 시작하기로 했어요.",en:"I decided to start with walking first."},target:"걷기",options:["to walk","to exercise","to study"],note:"걷기 names the activity; 시작하기로 했어요 reports the decision."},{kind:"guess",word:{ko:"듣다",romanization:"deutda",en:"to listen",pos:"verb",nuance:"듣다 is ㄷ irregular: 듣다 becomes 들어요 in polite speech."},sentence:{ko:"예문을 듣는 게 단어 외우기에 도움이 돼요.",en:"Listening to example sentences helps with memorizing words."},target:"듣는",options:["to exercise","to study","to listen"],note:"듣는 게 presents listening as the concrete helpful action."},{kind:"guess",word:{ko:"읽다",romanization:"ikda",en:"to read",pos:"verb",nuance:"읽다 has pronunciation changes, but beginners can first memorize 읽어요 as the practical polite form."},sentence:{ko:"책을 읽기 시작하면 휴대폰을 덜 보게 돼요.",en:"Once I start reading a book, I end up looking at my phone less."},target:"읽기",options:["to read","to exercise","to study"],note:"읽기 시작하다 is the fixed start-doing frame."},{kind:"payoff",line:{speaker:"튜터",ko:"매일 운동하기는 어렵지만 건강을 위해 필요해요.",en:"Exercising every day is hard, but it is necessary for health."},hl:"운동하"}],canDo:"Name an action as a noun with V-기 (운동하기) and V-는 것 (운동하는 것)",id:"chapter-60-b1",chapterId:"chapter-60",index:0},{kind:"pattern",title:"무늬 Pattern · V-기",cards:[{kind:"teach",name:"V-기",sub:"turning a verb into a noun",rows:[{when:"Any verb stem (vowel or consonant)",add:"stem + 기",ex:"먹다 → 먹기, 읽다 → 읽기"},{when:"Stem ends in ㄹ (ㄹ stays before 기)",add:"stem + 기",ex:"살다 → 살기, 만들다 → 만들기"},{when:"As the object of 좋아하다/싫어하다 etc.",add:"V-기 + 를/을",ex:"운동하기를 좋아해요"},{when:"As the subject of 어렵다/쉽다/힘들다",add:"V-기 + 가",ex:"말하기가 어려워요"}],examples:[{ko:"저는 책 읽기를 좋아해요.",en:"I like reading books.",romanization:"jeo-neun chaek ilg-gi-reul jo-a-hae-yo.",note:"읽기 names the action so it can be the object of 좋아하다."},{ko:"오늘 숙제는 일기 쓰기예요.",en:"Today's homework is writing a diary.",romanization:"o-neul suk-je-neun il-gi sseu-gi-ye-yo.",note:"쓰기 is a plain noun (a task/title) here, right after 은."}],more:{func:"Add 기 to a verb stem to name the action as a thing. The 기-noun can be a task, a goal, or the object of verbs like 좋아하다, 싫어하다, 시작하다, and it is the natural subject of difficulty/ease adjectives like 어렵다, 쉽다, 힘들다.",keyPoint:{label:"When to reach for V-기",body:"Use V-기 to label an action as a thing — especially as the subject of 어렵다/쉽다/좋다/힘들다, or the object of 좋아하다/싫어하다/시작하다. It sounds abstract and title-like, which is exactly why textbook section headings are 듣기, 읽기, 쓰기, 말하기."},pronunciation:"After a stem ending in a plain consonant, the 기 tenses: 읽기 [일끼], 먹기 [먹끼], 닦기 [닥끼]. Vowel stems stay soft: 가기 [가기], 자기 [자기]."}}],canDo:"Name an action as a noun with V-기 (운동하기) and V-는 것 (운동하는 것)",id:"chapter-60-b2",chapterId:"chapter-60",index:1},{kind:"words",title:"단어 Words 2 · 외우다~",cards:[{kind:"guess",word:{ko:"외우다",romanization:"oeuda",en:"to memorize",pos:"verb",nuance:"외우다 is a NATIVE Korean verb (no hanja), meaning to commit something to memory deliberately — to get it 'by heart' through effort. Contrast it sharply with 기억하다 (記憶, 'remember/recall'): 외우다 is the act of putting info IN ('I'll memorize these words tonight'), while 기억하다 is having or pulling it back OUT ('Do you remember my number?'). Mixing them is the #1 English-speaker error, because English 'remember' blurs both. A near-synonym 암기하다 (暗記) means the same as 외우다 but sounds more bookish/formal. Crucially, because 외우다 is native (not noun+하다), its conjugation differs from every other verb on this list: the stem 외우- meets 어요 and the 우 + 어 fuse to 워 → 외워요, past 외웠어요; the negative is the simple 안 외워요 and impossible 못 외워요 — there is NO noun to split off. Common collocations: 단어를 외우다, 통째로 외우다, 줄줄 외우다."},sentence:{ko:"단어를 외우기 전에 예문을 들어요.",en:"Before memorizing words, I listen to example sentences."},target:"외우",options:["to exercise","to study","to memorize"],note:"외우기 전에 is more natural than trying to attach 전에 to 외우는 것."},{kind:"guess",word:{ko:"배우다",romanization:"baeuda",en:"to learn",pos:"verb",nuance:"배우다 means 'to learn / acquire a skill or subject' and takes the object marker 을/를: 한국어를 배워요. It is a regular verb, but the stem ends in the vowel 우, so when 어요 attaches the two vowels contract into 워 — 배우 + 어요 → 배워요 (not 배우어요), past 배웠어요. The natural partner verb is 가르치다 ('to teach'), the giving side of the same act; and the person you learn from takes 한테/에게서 (사람) — 선생님한테 배워요 — never the place particle 에서 for the source. Contrast 배우다 with 공부하다 (工夫하다, 'to study'): 공부하다 is the effort of studying (sitting down, reviewing, hitting the books), while 배우다 is the result of acquiring a skill or being taught it, often from someone. So you 공부하다 for an exam at your desk but 배우다 the piano from a teacher. The English-speaker pitfall is writing the uncontracted 배우어요, and saying 학원에서 배우다 to mean 'learn from the academy' — 에서 marks where, while the human source must take 한테/에게서."},sentence:{ko:"한국어를 배우기 시작한 지 6개월 됐어요.",en:"It has been six months since I started learning Korean."},target:"배우",options:["to exercise","to walk","to learn"],note:"배우기 시작하다 marks the beginning of the learning action."},{kind:"guess",word:{ko:"시작하다",romanization:"sijakada",en:"to start",pos:"verb",nuance:"시작하다 means 'to start / begin' and is a Sino-Korean 하다 verb — 시작 (始作, literally 始 'begin' + 作 'make/do', i.e. 'set in motion') plus 하다. As a 하다 verb it conjugates regularly with 하다 → 해요: 시작해요 / 시작합니다 / 시작했어요. A point that trips learners is that 시작하다 works both transitively and intransitively: with a doer it takes an object (저는 일을 시작해요 'I start work', 을/를), and with no doer the thing simply begins and takes the subject marker (수업이 시작해요 'class starts', 이/가). Contrast it with the pure intransitive 시작되다 (始作되다, 'to be started/begin'), which is more formal and never takes an object — 회의가 시작됐어요 'the meeting began'. Its natural opposite is 끝나다 ('to end'). The English-speaker pitfalls are (1) conjugating the 하다 wrongly as 시작하요 instead of 시작해요, and (2) forcing an object onto the no-doer case (수업을 시작해요 when you simply mean class begins) — when nothing actively starts it, use 수업이 시작해요 or the passive 시작돼요."},sentence:{ko:"걷기부터 시작했어요.",en:"I started with walking."},target:"시작했",options:["to start","to study","to walk"],note:"A noun or -기 activity can come before 시작하다."},{kind:"guess",word:{ko:"알다",romanization:"alda",en:"to know",pos:"verb",nuance:"For a neutral ‘I don't know,’ Korean normally uses 모르다: 몰라요 or the softer 잘 모르겠어요. 안 알아요 is not universally wrong; context can give it ‘I don't recognize/know,’ ‘I won't find out,’ or a contrastive denial, so do not treat it as an impossible form."},sentence:{ko:"친구가 매일 운동하는 것을 알고 있어요.",en:"I know that my friend exercises every day."},target:"알고",options:["to know","to exercise","to study"],note:"알다 often takes a concrete proposition with -는 것."},{kind:"guess",word:{ko:"보다",romanization:"boda",en:"to see, to watch",pos:"verb",nuance:"보다 covers seeing, watching, and looking at something. Context tells which English verb fits."},sentence:{ko:"친구가 걷는 것을 보고 저도 시작했어요.",en:"After seeing my friend walk, I started too."},target:"보고",options:["to see, to watch","to exercise","to study"],note:"보다 makes the action concrete and observable, so -는 것 fits."},{kind:"guess",word:{ko:"느끼다",romanization:"neukkida",en:"to feel",pos:"verb",nuance:"느끼다 (a native verb, no 한자) means to become aware of something through the senses or the heart — an emotion (행복을 느끼다), a physical sensation (통증을 느끼다 = feel pain), or an abstract impression (차이·분위기를 느끼다). The contrast with 생각하다 is sharp: 느끼다 is what your body and heart register, 생각하다 is what your mind concludes. The big English-speaker pitfall is over-using it for states: 'I feel cold/sick/tired' in natural Korean is usually the plain adjective — 추워요, 아파요, 피곤해요 — not 추움을 느껴요. Reserve 느끼다 for when you're consciously naming the sensation as an object (감동을 느끼다, 책임감을 느끼다). Conjugation: the stem 느끼 + -어 contracts to 느껴 (느껴요, 느꼈어요), never the spelled-out 느끼어요."},sentence:{ko:"매일 듣는 것이 발음에 도움이 된다고 느껴요.",en:"I feel that listening every day helps pronunciation."},target:"느껴",options:["to exercise","to feel","to study"],note:"느끼다 can take a proposition treated as a concrete fact."},{kind:"guess",word:{ko:"자다",romanization:"jada",en:"to sleep",pos:"verb",nuance:"자다 becomes 잘 before some future or ability forms: 잘 거예요, 잘 수 있어요."},sentence:{ko:"자기 전에 휴대폰 보는 것을 줄이기로 했어요.",en:"I decided to reduce looking at my phone before sleeping."},target:"자기",options:["to study","to sleep","to walk"],note:"자기 전에 is the fixed before-sleeping frame."},{kind:"payoff",line:{speaker:"민서",ko:"그래서 저는 걷기부터 시작하기로 했어요.",en:"So I decided to start with walking."},hl:"시작하"}],canDo:"Express a decision or plan with V-기로 했어요 (운동하기로 했어요)",id:"chapter-60-b3",chapterId:"chapter-60",index:2},{kind:"pattern",title:"무늬 Pattern · V-는 것/거",cards:[{kind:"hunt",name:"V-는 것/거",sub:"an action or fact as a noun",lines:[{tokens:[{pre:"저는",mid:"",post:"",hit:!1},{pre:"영화",mid:"",post:"",hit:!1},{pre:"보",mid:"는",post:"",hit:!0},{pre:"",mid:"것",post:"을",hit:!0},{pre:"좋아해요.",mid:"",post:"",hit:!1}],ko:"저는 영화 보는 것을 좋아해요.",en:"I like watching movies.",romanization:"jeo-neun yeong-hwa bo-neun geos-eul jo-a-hae-yo."},{tokens:[{pre:"매일",mid:"",post:"",hit:!1},{pre:"운동하",mid:"는",post:"",hit:!0},{pre:"",mid:"것",post:"이",hit:!0},{pre:"중요해요.",mid:"",post:"",hit:!1}],ko:"매일 운동하는 것이 중요해요.",en:"Exercising every day is important.",romanization:"mae-il un-dong-ha-neun geos-i jung-yo-hae-yo."}],rule:{name:"V-는 것/거",rows:[{when:"Verb (present action/habit)",add:"stem + 는 것/거",ex:"먹다 → 먹는 것, 보다 → 보는 것"},{when:"Stem ends in ㄹ (ㄹ drops before 는)",add:"stem(-ㄹ) + 는 것",ex:"살다 → 사는 것, 만들다 → 만드는 것"},{when:"Subject, casual speech (것이 → 게)",add:"는 게",ex:"보는 게 좋아요"},{when:"Object, casual speech (것을 → 걸)",add:"는 걸",ex:"보는 걸 좋아해요"}]},more:{func:"Add 는 것 (casual 는 거) to a verb to name an action, a habit, or something you saw or know — as a noun. It points at the real, ongoing act, and it is the everyday default after 좋아하다 and as a sentence subject.",keyPoint:{label:"기 vs 는 것",body:"Both make a verb into a noun. V-기 is abstract and title-like — good for skills, tasks, and subjects of 어렵다/쉽다 (말하기가 어려워요). V-는 것 points at the real act or a habit, and is the default after 좋아하다 and as a subject (영화 보는 게 좋아요). When you are talking and unsure, 는 거 is the safer choice."},pronunciation:"것 links its final ㅅ into a following vowel: 것을 [거슬], 것이 [거시]. In casual speech learn the contractions early — 것이 → 게 [게], 것을 → 걸 [걸], 것은 → 건 [건] — they are everywhere."}}],canDo:"Express a decision or plan with V-기로 했어요 (운동하기로 했어요)",id:"chapter-60-b4",chapterId:"chapter-60",index:3},{kind:"words",title:"단어 Words 3 · 먹다~",cards:[{kind:"guess",word:{ko:"먹다",romanization:"meokda",en:"to eat",pos:"verb",nuance:"먹다 is used for meals and food. For medicine, Korean often uses 약을 먹어요, literally “eat medicine,” which means “take medicine.”"},sentence:{ko:"밤에 늦게 먹는 것을 줄이려고 해요.",en:"I am trying to reduce eating late at night."},target:"먹는",options:["to exercise","to study","to eat"],note:"먹는 것 is the habit being reduced."},{kind:"guess",word:{ko:"쉬다",romanization:"swida",en:"to rest",pos:"verb",nuance:"쉬다 is used for taking a break, resting, or being off work/school."},sentence:{ko:"쉬는 것도 공부 계획에 넣어야 해요.",en:"Resting should also be included in the study plan."},target:"쉬는",options:["to rest","to walk","to listen"],note:"쉬는 것 points to resting as a concrete part of the plan."},{kind:"guess",word:{ko:"습관",romanization:"seupgwan",en:"habit",pos:"noun",nuance:"습관 (習慣, 習 'to practice/learn' + 慣 'to grow accustomed') frames a habit as something drilled in until it feels natural, and it leans slightly formal and neutral. The key contrast is 습관 vs 버릇: 습관 is a broad, often deliberate routine (early rising, daily exercise, good study habits), while 버릇 is colloquial and usually a quirky or annoying unconscious tic — nail-biting, leg-shaking, a child's bad manners. Crucially, scolding a child you say 버릇없다 ('has no manners / is rude'), never 습관없다. Both pair with 고치다 ('fix') for breaking them and 들이다/생기다 for forming them (습관을 들이다 = cultivate a habit; 습관이 생기다 = a habit forms). To say you have one, use 습관이 있다. Pitfall: English 'I have a habit of doing X' must use the verb's -는 present-modifier form before 습관: 일찍 자는 습관 (the habit of sleeping early), not 일찍 자기 습관. Also do not use 가지다 here — habits 있다/되다/생기다, they are not 'had' with 가지다."},sentence:{ko:"매일 듣는 습관을 만들고 있어요.",en:"I am building a habit of listening every day."},target:"습관",options:["exercise","habit","study, studying"],note:"-는 습관 naturally describes repeated behavior."},{kind:"guess",word:{ko:"목표",romanization:"mokpyo",en:"goal, target",pos:"noun",nuance:"목표 (目標, 目 'eye' + 標 'mark/sign' — literally the mark the eye fixes on) is a concrete, measurable goal or target you aim at, and it travels with a tight verb family: 세우다 or 정하다 to set it, 이루다 or 달성하다 to achieve it. The synonym line is 목표 vs 꿈: 목표 is specific and outcome-focused (pass TOPIK 3, save 1,000,000 won, run 5km), while 꿈 is broader, emotional, and aspirational (become a doctor, a better world), so use 목표 for things you can tick off and 꿈 for the life vision behind them. Note also 목표 vs 목적(目的): 목표 is the concrete TARGET, 목적 is the underlying PURPOSE/reason. The English-speaker pitfall is forming a verb directly: 'to goal' tempts learners into 목표하다, which is unnatural in writing — say 목표를 세우다 or 목표로 하다 instead."},sentence:{ko:"오늘 목표는 예문 다섯 개를 외우는 거예요.",en:"Today's goal is memorizing five example sentences."},target:"목표",options:["exercise","study, studying","goal, target"],note:"Spoken 거예요 makes the action into the goal."},{kind:"guess",word:{ko:"건강",romanization:"geongang",en:"health",pos:"noun",nuance:"건강 is Sino-Korean 健康, where 健 means 'sturdy/robust' and 康 means 'peaceful/well,' together the sound, robust state of body and mind. It splits into a noun and an adjective: the noun 건강 ('health') pairs with 좋다/나쁘다 (good/bad) — never 높다/낮다 (high/low), which is the typical English-influenced slip from 'high level of health' — and you actively mind it with 챙기다 (건강을 챙기다, 'look after your health'); the adjective 건강하다 means 'to be healthy' (저는 건강해요 = 'I'm healthy'). Its honorific imperative 건강하세요 is a beloved set phrase, a warm farewell/blessing meaning 'stay healthy,' especially said to elders and at New Year. A near-synonym is 컨디션 (a loanword from 'condition') — but 컨디션 is your day-to-day fitness/energy level (오늘 컨디션이 안 좋아 = 'I'm not feeling great today'), whereas 건강 is your overall, long-term state of wellness; don't swap them."},sentence:{ko:"건강을 위해 매일 걷기로 했어요.",en:"For my health, I decided to walk every day."},target:"건강",options:["exercise","study, studying","health"],note:"Noun + 을 위해 is the noun version of V-기 위해."},{kind:"guess",word:{ko:"꾸준히",romanization:"kkujunhi",en:"steadily, consistently",pos:"adverb",nuance:"꾸준히 means doing something *steadily and consistently over time, without quitting* — it is the warm praise-word Koreans reach for to describe sustainable, unglamorous, day-after-day effort. The contrast you must internalize is 꾸준히 vs 열심히: 열심히 means 'hard, with intensity/diligence' and can describe a single burst (오늘 열심히 공부했어요 = I studied hard today), whereas 꾸준히 is inherently about *continuity* across time — you cannot be 꾸준히 for one day, because the word means you kept it up. So an all-nighter is 열심히, never 꾸준히; daily practice for a year is 꾸준히. In a self-improvement context it is the natural opposite of cramming (벼락치기) or giving up. The grammar pitfall for English speakers is part of speech: 꾸준히 is an *adverb* that modifies verbs (꾸준히 공부하다), so you cannot use it to describe a noun directly — for that you need the adjective 꾸준하다 (e.g. 꾸준한 노력 'steady effort'). Habitual partners: 꾸준히 공부하다, 꾸준히 연습하다, 꾸준히 노력하다, 꾸준히 늘다."},sentence:{ko:"꾸준히 듣는 게 말하기에도 도움이 돼요.",en:"Listening consistently helps speaking too."},target:"꾸준히",options:["to exercise","steadily, consistently","exercise"],note:"꾸준히 works well with repeated -는 것 habits."},{kind:"guess",word:{ko:"줄이다",romanization:"jurida",en:"to reduce, to cut down on",pos:"verb",nuance:"줄이다 is transitive: you reduce something. 줄다 is intransitive: something decreases by itself."},sentence:{ko:"휴대폰 보는 것을 줄이기로 했어요.",en:"I decided to cut down on looking at my phone."},target:"줄이",options:["to exercise","to reduce, to cut down on","to study"],note:"The thing reduced is a concrete habit, so 보는 것을 is natural."},{kind:"payoff",line:{speaker:"튜터",ko:"매일 운동하기는 어렵지만 건강을 위해 필요해요.",en:"Exercising every day is hard, but it is necessary for health."},hl:"건강"}],canDo:"Give the purpose of an action with V-기 위해(서) (건강해지기 위해서)",id:"chapter-60-b5",chapterId:"chapter-60",index:4},{kind:"pattern",title:"무늬 Pattern · V-기로 했어요",cards:[{kind:"hunt",name:"V-기로 했어요",sub:"decided to do",lines:[{tokens:[{pre:"내일부터",mid:"",post:"",hit:!1},{pre:"일찍",mid:"",post:"",hit:!1},{pre:"일어나",mid:"기로",post:"",hit:!0},{pre:"",mid:"했어요",post:".",hit:!0}],ko:"내일부터 일찍 일어나기로 했어요.",en:"I've decided to get up early from tomorrow.",romanization:"nae-il-bu-teo il-jjik il-eo-na-gi-ro haess-eo-yo."},{tokens:[{pre:"우리",mid:"",post:"",hit:!1},{pre:"주말에",mid:"",post:"",hit:!1},{pre:"같이",mid:"",post:"",hit:!1},{pre:"등산하",mid:"기로",post:"",hit:!0},{pre:"",mid:"했어요",post:".",hit:!0}],ko:"우리 주말에 같이 등산하기로 했어요.",en:"We decided to go hiking together on the weekend.",romanization:"u-ri ju-mal-e ga-chi deung-san-ha-gi-ro haess-eo-yo."}],rule:{name:"V-기로 했어요",rows:[{when:"State a decision (most common)",add:"stem + 기로 했어요",ex:"운동하다 → 운동하기로 했어요"},{when:"Deciding right now / promise",add:"stem + 기로 해요 / 할게요",ex:"담배를 끊기로 할게요"},{when:"Mutual agreement (we agreed)",add:"stem + 기로 했어요 (with 같이/우리)",ex:"같이 가기로 했어요"},{when:"Decide NOT to do",add:"안 + V / V-지 않 + 기로 했어요",ex:"야식을 안 먹기로 했어요"}]},more:{func:"Use V-기로 하다 for a decision, plan, or agreement to do something. The 기-noun takes 로 ('settle on') plus 하다. It is almost always said in the past — 했어요 — because the decision is already made by the time you mention it.",keyPoint:{label:"했어요 vs 해요",body:"The decision is usually reported in the past: V-기로 했어요 ('I (have) decided'), because the decision already exists by the time you say it. Use the present V-기로 해요 / 할게요 only when you are making the resolution at the very moment of speaking ('okay, I'll do X from now on')."},pronunciation:"기로 is read smoothly [기로], with no special change. A tensing stem still tenses the 기: 먹기로 [먹끼로]; and ㅎ + ㄱ aspirates: 끊기로 [끈키로]."}}],canDo:"Give the purpose of an action with V-기 위해(서) (건강해지기 위해서)",id:"chapter-60-b6",chapterId:"chapter-60",index:5},{kind:"pattern",title:"무늬 Pattern · V-기 위해(서)",cards:[{kind:"hunt",name:"V-기 위해(서)",sub:"in order to do",lines:[{tokens:[{pre:"건강해지",mid:"기",post:"",hit:!0},{pre:"",mid:"위해서",post:"",hit:!0},{pre:"매일",mid:"",post:"",hit:!1},{pre:"운동해요.",mid:"",post:"",hit:!1}],ko:"건강해지기 위해서 매일 운동해요.",en:"I exercise every day in order to get healthy.",romanization:"geon-gang-hae-ji-gi wi-hae-seo mae-il un-dong-hae-yo."},{tokens:[{pre:"한국에서",mid:"",post:"",hit:!1},{pre:"일하",mid:"기",post:"",hit:!0},{pre:"",mid:"위해",post:"",hit:!0},{pre:"한국어를",mid:"",post:"",hit:!1},{pre:"배워요.",mid:"",post:"",hit:!1}],ko:"한국에서 일하기 위해 한국어를 배워요.",en:"I'm learning Korean in order to work in Korea.",romanization:"han-gug-e-seo il-ha-gi wi-hae han-gug-eo-reul bae-wo-yo."}],rule:{name:"V-기 위해(서)",rows:[{when:"Verb purpose",add:"stem + 기 위해(서)",ex:"합격하다 → 합격하기 위해서"},{when:"Noun purpose",add:"N + 을/를 위해(서)",ex:"건강을 위해서"},{when:"Drop 서 (a touch more formal)",add:"stem + 기 위해",ex:"살을 빼기 위해 운동해요"},{when:"Written/formal style",add:"stem + 기 위하여",ex:"성공하기 위하여 노력합니다"}]},more:{func:"Use V-기 위해(서) to give the purpose of an action: 'in order to V'. The verb is nominalised with 기, then 위해(서) ('for the sake of') marks it as the goal. For a noun goal, use N을/를 위해(서) with no 기.",keyPoint:{label:"V-기 위해서 vs V-(으)려고",body:"Both mean 'in order to'. 기 위해서 states a deliberate, often weighty goal and works in writing and speech (시험에 합격하기 위해서 공부해요). V-(으)려고 is lighter and conversational. For a noun goal there is no 기 — you must use N을/를 위해서 (건강을 위해서)."},pronunciation:"위해서 [위해서]; the formal 위하여 [위하여]. The 기 still tenses after a plain-consonant stem: 먹기 위해 [먹끼 위해]."}}],canDo:"Say something happens before another action (V-기 전에) and that you start it (V-기 시작하다)",id:"chapter-60-b7",chapterId:"chapter-60",index:6},{kind:"pattern",title:"무늬 Pattern · V-기 전에",cards:[{kind:"hunt",name:"V-기 전에",sub:"before doing",lines:[{tokens:[{pre:"자",mid:"기",post:"",hit:!0},{pre:"",mid:"전에",post:"",hit:!0},{pre:"휴대폰",mid:"",post:"",hit:!1},{pre:"보는",mid:"",post:"",hit:!1},{pre:"것을",mid:"",post:"",hit:!1},{pre:"줄이기로",mid:"",post:"",hit:!1},{pre:"했어요.",mid:"",post:"",hit:!1}],ko:"자기 전에 휴대폰 보는 것을 줄이기로 했어요.",en:"I decided to cut down on looking at my phone before sleeping.",romanization:"ja-gi jeon-e hyu-dae-pon bo-neun geos-eul ju-ri-gi-ro haess-eo-yo."},{tokens:[{pre:"밥을",mid:"",post:"",hit:!1},{pre:"먹",mid:"기",post:"",hit:!0},{pre:"",mid:"전에",post:"",hit:!0},{pre:"손을",mid:"",post:"",hit:!1},{pre:"씻어요.",mid:"",post:"",hit:!1}],ko:"밥을 먹기 전에 손을 씻어요.",en:"I wash my hands before eating.",romanization:"bab-eul meog-gi jeon-e son-eul ssis-eo-yo."}],rule:{name:"V-기 전에",rows:[{when:"Verb (before doing)",add:"stem + 기 전에",ex:"자다 → 자기 전에, 먹다 → 먹기 전에"},{when:"Noun (before a thing/event)",add:"N + 전에 (no 기)",ex:"수업 전에, 점심 전에"},{when:"Tense stays on the main verb",add:"...기 전에 + past/present/future main verb",ex:"먹기 전에 손을 씻었어요"}]},more:{func:"Use V-기 전에 to say one action happens before another: 'before V-ing'. The verb takes 기, then 전에 ('before') follows. The tense lives only in the main clause, never on the verb before 전에.",keyPoint:{label:"기 전에 vs N 전에",body:"Before a verb, you need 기: 먹기 전에, 자기 전에. Before a plain noun, there is no 기 — just add 전에: 수업 전에, 점심 전에, 운동 전에. And the opposite of 전에 is 후에 / -(으)ㄴ 후에 (after doing): 먹은 후에."},pronunciation:"전에 [저네] in fast speech, as the ㄴ links to the next vowel. The 기 still tenses after a plain-consonant stem: 먹기 전에 [먹끼 저네]."}}],canDo:"Name an action as a noun with V-기 (운동하기) and V-는 것 (운동하는 것)",id:"chapter-60-b8",chapterId:"chapter-60",index:7},{kind:"pattern",title:"무늬 Pattern · V-기 시작하다",cards:[{kind:"hunt",name:"V-기 시작하다",sub:"start doing",lines:[{tokens:[{pre:"한국어",mid:"",post:"",hit:!1},{pre:"뉴스를",mid:"",post:"",hit:!1},{pre:"조금씩",mid:"",post:"",hit:!1},{pre:"듣",mid:"기",post:"",hit:!0},{pre:"",mid:"시작",post:"했어요.",hit:!0}],ko:"한국어 뉴스를 조금씩 듣기 시작했어요.",en:"I started listening to Korean news little by little.",romanization:"han-gug-eo nyu-seu-reul jo-geum-ssik deud-gi si-jak-haess-eo-yo."},{tokens:[{pre:"아침에",mid:"",post:"",hit:!1},{pre:"걷",mid:"기",post:"",hit:!0},{pre:"",mid:"시작",post:"하니까",hit:!0},{pre:"잠이",mid:"",post:"",hit:!1},{pre:"덜",mid:"",post:"",hit:!1},{pre:"와요.",mid:"",post:"",hit:!1}],ko:"아침에 걷기 시작하니까 잠이 덜 와요.",en:"Since I started walking in the morning, I feel less sleepy.",romanization:"a-chim-e geod-gi si-jak-ha-ni-kka jam-i deol wa-yo."}],rule:{name:"V-기 시작하다",rows:[{when:"Start a verb action",add:"stem + 기 시작하다",ex:"듣다 → 듣기 시작하다, 읽다 → 읽기 시작하다"},{when:"Tense lives on 시작하다",add:"...기 시작했어요 / 시작해요 / 시작할 거예요",ex:"걷기 시작했어요"},{when:"Start a noun (no 기)",add:"N을/를 시작하다",ex:"운동을 시작했어요"}]},more:{func:"Use V-기 시작하다 to say you start an action. 시작하다 ('start') can take a plain noun object (운동을 시작하다), but when the thing you start is a verb, you nominalise it with 기 first. The tense goes on 시작하다.",keyPoint:{label:"기 시작하다 vs N 시작하다",body:"If you start a verb action, nominalise it: 걷기 시작하다, 듣기 시작하다, 읽기 시작하다. If you start a thing that is already a noun, just add 을/를: 운동을 시작하다, 공부를 시작하다. So '운동하다' becomes 운동하기 시작하다 OR 운동을 시작하다 — but never 운동기 시작하다."},pronunciation:"The 기 tenses after a plain-consonant stem: 듣기 [듣끼], 읽기 [일끼], 걷기 [걷끼]. 시작하다 is [시자카다], with ㄱ + ㅎ blending into an aspirated sound."}}],canDo:"Express a decision or plan with V-기로 했어요 (운동하기로 했어요)",id:"chapter-60-b9",chapterId:"chapter-60",index:8},{kind:"dialogue",title:"대화 Dialogue · 진짜 한국어",cards:[{kind:"chat",setting:"A tutor helps a learner turn vague goals into Korean sentences using -기, -는 것, and fixed nominalized frames.",lines:[{speaker:"튜터",ko:"매일 운동하기는 어렵지만 건강을 위해 필요해요.",en:"Exercising every day is hard, but it is necessary for health.",romanization:"maeil undonghagineun eoryeopjiman geongangeul wihae piryohaeyo."},{speaker:"민서",ko:"그래서 저는 걷기부터 시작하기로 했어요.",en:"So I decided to start with walking.",romanization:"geuraeseo jeoneun geotgibuteo sijakagiro haesseoyo."},{speaker:"튜터",ko:"좋아요. 친구가 매일 걷는 것을 보고 따라 해 보기로 한 거죠?",en:"Good. You saw your friend walking every day and decided to try following along, right?",romanization:"joayo. chinguga maeil geonneun geoseul bogo ttara hae bogiro han geojyo?"},{speaker:"민서",ko:"네. 그리고 자기 전에 휴대폰 보는 것을 줄이기로 했어요.",en:"Yes. And I decided to reduce looking at my phone before sleeping.",romanization:"ne. geurigo jagi jeone hyudaepon boneun geoseul jurigiro haesseoyo."},{speaker:"튜터",ko:"단어를 외우기 전에 예문을 듣는 것도 좋아요.",en:"Listening to example sentences before memorizing words is also good.",romanization:"daneoreul oeugi jeone yemuneul deunneun geotdo joayo."},{speaker:"민서",ko:"그럼 오늘 목표는 예문을 먼저 듣고 단어를 외우는 거예요.",en:"Then today's goal is listening to the examples first and memorizing the words.",romanization:"geureom oneul mokpyoneun yemuneul meonjeo deutgo daneoreul oeuneun geoyeyo."}]},{kind:"order",prompt:"Build: 'I decided to memorize words.'",tokens:["단어를","외우기로 했어요"],correct:"단어를 외우기로 했어요",explanation:"-기로 했어요 is the fixed decision frame. 외우다 becomes 외우기로 before 했어요."}],canDo:"Name an action as a noun with V-기 (운동하기) and V-는 것 (운동하는 것)",id:"chapter-60-b10",chapterId:"chapter-60",index:9},{kind:"reading",title:"읽기 Reading · -기와 -는 것을 고르는 법",cards:[{kind:"read",title:"-기와 -는 것을 고르는 법",chunks:["민서는 건강을 위해 운동을 시작하고 싶었지만, 매일 운동하기는 부담스러웠다. 그래서 걷기부터 시작하기로 했다. 친구가 아침마다 걷는 것을 보고 따라 해 보기로 한 것이다. 한국어 공부도 같은 방식으로 바꿨다.",'단어를 외우기 전에 예문을 먼저 듣고, 자기 전에 휴대폰 보는 것을 줄이기로 했다. 이렇게 말하면 -기는 목표나 순서를 만들고, -는 것은 실제로 보고 줄이고 반복하는 행동을 가리킨다. 민서는 이제 "공부하기"와 "공부하는 것"을 같은 말로 외우지 않고, 문장 안에서 어떤 역할을 하는지 먼저 본다.'],translation:"Minseo wanted to start exercising for her health, but exercising every day felt burdensome. So she decided to start with walking. She saw her friend walking every morning and decided to try following along. She changed her Korean study the same way. Before memorizing words, she listens to examples first, and she decided to reduce looking at her phone before sleeping. In these sentences, -기 makes goals and sequences, while -는 것 points to actions that are seen, reduced, or repeated. Minseo no longer memorizes 공부하기 and 공부하는 것 as the same thing; she first checks what job the action has inside the sentence.",qas:[{q:"민서는 왜 걷기부터 시작하기로 했어요?",a:"매일 운동하기는 부담스러웠기 때문이에요."},{q:"단어를 외우기 전에 무엇을 먼저 해요?",a:"예문을 먼저 들어요."},{q:"-는 것은 어떤 행동을 가리킨다고 했어요?",a:"실제로 보고 줄이고 반복하는 행동을 가리킨다고 했어요."}]}],canDo:"Express a decision or plan with V-기로 했어요 (운동하기로 했어요)",id:"chapter-60-b11",chapterId:"chapter-60",index:10},{kind:"boss",title:"보스 Boss bite · 다 걸어요",cards:[{kind:"drill",prompt:"Which sentence uses -기 as an activity label?",sentence:null,options:[{text:"매일 운동하기는 어려워요.",ok:!0},{text:"매일 운동하는 것을 봤어요.",ok:!1},{text:"매일 운동한 사람을 만났어요.",ok:!1}],explanation:"운동하기 names the activity as a general task."},{kind:"drill",prompt:"Which sentence uses -는 것 for a concrete habit being reduced?",sentence:null,options:[{text:"휴대폰 보는 것을 줄이기로 했어요.",ok:!0},{text:"휴대폰 보기 전에 줄였어요.",ok:!1},{text:"휴대폰 보기를 봤어요.",ok:!1}],explanation:"The habit being reduced is the concrete action 휴대폰 보는 것."},{kind:"drill",prompt:"Choose the correct fixed decision frame.",sentence:null,options:[{text:"매일 걷기로 했어요.",ok:!0},{text:"매일 걷는 것으로 했어요.",ok:!1},{text:"매일 걸어서 했어요.",ok:!1}],explanation:"기로 했어요 is the standard chunk for a settled decision."},{kind:"drill",prompt:"운동___ 시작했어요. (I started exercising.)",sentence:null,options:[{text:"을",ok:!0},{text:"이",ok:!1},{text:"에",ok:!1}],explanation:"시작하다 can take the activity noun as an object, so 운동을 fits. 이 would make exercise the subject."},{kind:"order",prompt:"Build: 'I decided to memorize words.'",tokens:["단어를","외우기로 했어요"],correct:"단어를 외우기로 했어요",explanation:"-기로 했어요 is the fixed decision frame. 외우다 becomes 외우기로 before 했어요."},{kind:"drill",prompt:"Which sentence treats walking as an activity label?",sentence:null,options:[{text:"걷기는 건강에 좋아요.",ok:!0},{text:"걷는 것을 어제 봤어요.",ok:!1},{text:"걷다 건강이에요.",ok:!1}],explanation:"-기 can turn the activity into a topic label. 걷기는 means walking as an activity."}],canDo:"Give the purpose of an action with V-기 위해(서) (건강해지기 위해서)",id:"chapter-60-b12",chapterId:"chapter-60",index:11}]},{id:"chapter-61",number:61,title:`A/V-네요: realizing or noticing something right now · A/V-군요 / -구나: "I see, so that's how it is"`,goal:"Use -네요 for fresh realization from what you just noticed.",biteCount:11,bites:[{kind:"words",title:"단어 Words 1 · 재미있다~",cards:[{kind:"guess",word:{ko:"재미있다",romanization:"jaemiitda",en:"to be fun, interesting",pos:"adjective",nuance:"재미있다 is literally 재미 (fun, enjoyment) + 있다 (to exist) — 'fun exists [in it]' — which is exactly why it conjugates like 있다 and gives 재미있어요, and why the noun-modifying form is the 있다-style 재미있는 N (재미있는 영화), never 재미있은. It spans both English 'fun' and 'interesting': a party, a game, or a class can all be 재미있어요, so let context choose the English. The near-synonym to separate is 재미있다 vs 흥미롭다: 재미있다 is the warm, everyday 'enjoyable/entertaining' you say about a movie or a friend, while 흥미롭다 is a cooler, more bookish 'intriguing/of interest' you might use for a research finding or a phenomenon — calling a thrilling roller coaster 흥미로워요 sounds oddly academic. Its direct opposite is the single word 재미없다 (재미 + 없다, 'fun does not exist') = boring; do not say 안 재미있다 as your default negative — 재미없어요 is the natural 'it's boring', and 안 재미있어요 reads more like 'it's not [particularly] fun'. The big English-speaker pitfall is the conjugation: because the headword ends in 있다, learners over-apply -하다 or vowel rules and produce 재미있다요 or 재미있아요; the only correct polite form is 재미있어요, with past 재미있었어요."},sentence:{ko:"한국어가 생각보다 재미있네요.",en:"Korean is more fun than I expected."},target:"재미있",options:["to be difficult","to be certain, sure","to be fun, interesting"],note:"Fresh realization with -네요."},{kind:"guess",word:{ko:"생각보다",romanization:"saenggakboda",en:"more/less than expected",pos:"adverb",nuance:"생각보다 naturally pairs with 더라고요 because both talk about what you found after experience."},sentence:{ko:"생각보다 어렵지 않네요.",en:"It is not as hard as I thought."},target:"생각보다",options:["more/less than expected","already","together"],note:"This word naturally triggers realization endings because expectation changed."},{kind:"guess",word:{ko:"어렵다",romanization:"eoryeopda",en:"to be difficult",pos:"adjective",nuance:"어렵다 is ㅂ irregular: 어려워요, 어려운. It is useful in classroom repair conversations because learners often need to say a sentence or lesson is difficult."},sentence:{ko:"처음에는 어려울 줄 알았는데 생각보다 괜찮군요.",en:"I thought it would be hard at first, but it is better than expected."},target:null,options:["to be difficult","to be fun, interesting","to be certain, sure"],note:"어려울 줄 알았다 sets the old expectation."},{kind:"guess",word:{ko:"벌써",romanization:"beolsseo",en:"already",pos:"adverb",nuance:"벌써 means 'already', but its core flavor is SURPRISE that something happened sooner than you expected — 'wow, already?'. Compare its near-twin 이미: 이미 is the neutral 'already / by now' that simply reports a completed fact (이미 끝났어요 'it's already finished', stating it), whereas 벌써 adds the emotional jolt (벌써 끝났어요? 'it's done already?!'). So a flat report prefers 이미; an astonished reaction prefers 벌써. It naturally rides with past tense and with 다('all'), and often co-occurs with the exclamatory endings -네요/-군요. Register-neutral. The English-speaker pitfall: don't pair 벌써 with the future — English 'already' can sit oddly with plans, but 벌써 is about something that has ALREADY occurred, so it takes past/completed verbs (벌써 갔어요), not 벌써 갈 거예요. Use 곧/이미 곧 logic for 'soon' instead."},sentence:{ko:"벌써 도착하셨군요.",en:"Oh, they have already arrived."},target:"벌써",options:["already","more/less than expected","together"],note:"벌써 pairs well with surprise or realization."},{kind:"guess",word:{ko:"도착하다",romanization:"dochakada",en:"to arrive",pos:"verb",nuance:"도착하다 is Sino-Korean 到着(도착: 到 reach + 着 attach/touch down) plus 하다 — the moment of REACHING and touching a destination. Its mirror is 출발하다(depart), and the key is the particle: you arrive AT a place with 에 (호텔에 도착해요), whereas 출발하다 leaves FROM a place with 에서. Don't confuse it with 들어가다/들어오다(enter): 도착하다 is reaching the destination's threshold, not stepping inside a building. As a 하다 verb, 하 + 아 fuses to 해 (도착해요) and the short negative and inability split the noun off: 도착 안 해요, 도착 못 해요. The classic English-speaker error is copying 'arrive at' as 에서 — 'at' here is the static endpoint 에, so 공항에 도착해요, and 공항에서 도착해요 is wrong."},sentence:{ko:"그분은 벌써 도착하셨군요.",en:"Oh, they have already arrived."},target:"도착하셨",options:["to be late","to arrive","to expect"],note:"Past honorific 도착하셨군요 fits polite acknowledgement."},{kind:"guess",word:{ko:"늦다",romanization:"neutda",en:"to be late",pos:"verb",nuance:"늦다 is a descriptive verb, so it behaves like an adjective in Korean. Use 늦게 for the adverb 'late': 늦게 왔어요."},sentence:{ko:"지금 출발하면 조금 늦을걸요.",en:"If you leave now, you will probably be a little late."},target:"늦을",options:["to be late","to arrive","to expect"],note:"늦을걸요 is a softened prediction."},{kind:"payoff",line:{speaker:"민서",ko:"한국어가 생각보다 재미있네요.",en:"Korean is more fun than I expected."},hl:"재미있"}],canDo:"React to something noticed right now with A/V-네요 (벌써 도착했네요)",id:"chapter-61-b1",chapterId:"chapter-61",index:0},{kind:"pattern",title:"무늬 Pattern · A/V-네요: realizing or noticing something right now",cards:[{kind:"hunt",name:"A/V-네요: realizing or noticing something right now",sub:"",lines:[{tokens:[{pre:"밖에",mid:"",post:"",hit:!1},{pre:"비가",mid:"",post:"",hit:!1},{pre:"오",mid:"네요",post:".",hit:!0}],ko:"밖에 비가 오네요.",en:"Oh, it's raining outside.",romanization:"bakke biga oneyo."},{tokens:[{pre:"이",mid:"",post:"",hit:!1},{pre:"김치찌개",mid:"",post:"",hit:!1},{pre:"정말",mid:"",post:"",hit:!1},{pre:"맛있",mid:"네요",post:"!",hit:!0}],ko:"이 김치찌개 정말 맛있네요!",en:"Wow, this kimchi stew is really delicious!",romanization:"i gimchijjigae jeongmal masinneyo!"}],rule:{name:"A/V-네요: realizing or noticing something right now",rows:[{when:"Verb stem (present)",add:"-네요",ex:"오다 -> 오네요 (Oh, it's coming/raining)"},{when:"Adjective stem",add:"-네요",ex:"맛있다 -> 맛있네요 (Wow, this is tasty)"},{when:"Past tense",add:"-았/었네요",ex:"끝나다 -> 끝났네요 (Oh, it's already over)"},{when:"ㄹ-stem (drop ㄹ)",add:"-네요",ex:"멀다 -> 머네요 (It's far, isn't it)"},{when:"Noun + 이다",add:"(이)네요",ex:"학생이네요 / 가수네요 (Oh, you're a student/singer)"}]},more:{func:`-네요 is the on-the-spot reaction ending. You attach it when you discover, see, hear, taste, or otherwise newly notice something at the moment of speaking. It carries a light feeling of mild surprise or fresh awareness: "Oh, it's ...!" Use it when the information just hit you, not when you are reporting a fact you already knew.`,keyPoint:{label:"-네요 = reacting to NEW information",body:"The core trigger is newness to the speaker. If you already knew the fact and are just stating it, use plain -아/어요. The moment of fresh noticing is what makes -네요 the right choice."},pronunciation:"Past tense -았네요/-었네요 has the ㅅ assimilate to ㄴ: 끝났네요 sounds like [끈난네요], 갔네요 like [간네요]. Learners who pronounce a clear [ㅅ] here sound non-native."}}],canDo:"React to something noticed right now with A/V-네요 (벌써 도착했네요)",id:"chapter-61-b2",chapterId:"chapter-61",index:1},{kind:"words",title:"단어 Words 2 · 시간~",cards:[{kind:"guess",word:{ko:"시간",romanization:"sigan",en:"time",pos:"noun",nuance:"시간 works with 있어요/없어요 and is essential for scheduling."},sentence:{ko:"시간이 있었으면 같이 갔을 텐데요.",en:"If I had had time, I would have gone with you."},target:"시간",options:["time","to be fun, interesting","more/less than expected"],note:"시간이 있었으면 creates the missed condition."},{kind:"guess",word:{ko:"같이",romanization:"gachi",en:"together",pos:"adverb",nuance:"같이 can mean together or like/as in other contexts; here it means together."},sentence:{ko:"같이 갔을 텐데요.",en:"I would have gone together with you."},target:"같이",options:["more/less than expected","together","already"],note:"같이 makes the regret relational, not just logistical."},{kind:"guess",word:{ko:"이미",romanization:"imi",en:"already",pos:"adverb",nuance:"이미 means 'already,' emphasizing that an action or state is completed and now fixed — often colored by 'and there's no changing it now.' The sharp contrast every learner needs is 이미 vs 벌써. Both translate as 'already,' but 이미 is neutral and factual ('it is already done, that's just the situation'), while 벌써 adds emotional surprise that it happened so fast or so soon ('already?! that quick?'). 이미 끝났어요 = a calm statement of fact; 벌써 끝났어요?! = 'it's over already?!' with raised eyebrows. So choose 이미 when calmly noting that the moment/deadline has passed, and 벌써 when reacting to unexpected speed. 이미 is native Korean and is also future-blind: it only describes things already done, never things about to happen. It pairs naturally with completed clauses and with -더라고요, -았/었- past forms."},sentence:{ko:"그분은 이미 알고 있을걸요.",en:"They probably already know."},target:"이미",options:["already","more/less than expected","together"],note:"이미 often appears in hedged assertions."},{kind:"guess",word:{ko:"예상하다",romanization:"yesanghada",en:"to expect",pos:"verb",nuance:"예상하다 (Sino-Korean 豫想, 'beforehand' + 'think' — to think ahead) means to anticipate or predict an outcome from reasoning: what you calculate will happen. It is emotionally neutral, which is exactly where it splits from 기대하다 (期待, to look forward to / hope for): you can 예상하다 a bad result, but you would never 기대하다 one, because 기대 carries positive hope. It also differs from 예측하다 (豫測, to forecast), which is more technical/measured (weather, data, trends), whereas 예상하다 is the everyday 'I figured this would happen.' It collocates with -(으)ㄹ 거라고 예상하다, 예상보다, and 예상이 빗나가다. The English-speaker pitfall is that English 'expect' covers both neutral prediction AND hopeful looking-forward; in Korean those split, so 'I'm expecting good news (hoping)' is 기대하고 있어요, while 'I expect it'll rain (forecast)' is 비가 올 거라고 예상해요. Picking the wrong one makes you sound oddly hopeful about bad outcomes."},sentence:{ko:"예상보다 사람이 많네요.",en:"There are more people than expected."},target:"예상",options:["to arrive","to expect","to be late"],note:"A changed expectation naturally takes -네요."},{kind:"guess",word:{ko:"확실하다",romanization:"hwaksilhada",en:"to be certain, sure",pos:"adjective",nuance:"확실하다 (確實, 確 'firm/sure' + 實 'real/true') expresses certainty and confidence — you're sure something is true, settled, or reliable. The adverb 확실히 ('certainly, definitely, for sure') is very common when answering or confirming (확실히 그래요 'that's definitely so'). The sharp contrast is with 분명하다: 확실하다 centres on the speaker's subjective confidence ('I'm sure of it'), while 분명하다 centres on a thing being objectively obvious/unambiguous — so 나는 확실해 ('I'm certain') but 증거가 분명해 ('the evidence is clear-cut'). It also brushes against 틀림없다 ('there's no mistake / definitely'), which is even more emphatic. Crucially, 확실하다 is for certainty, not possibility: to say 'maybe' you need 아마 ('probably') or '-ㄹ지도 몰라요' ('might'), not 확실하다. The natural adverb is 확실히 in everyday speech (확실하게 is a touch stiffer)."},sentence:{ko:"아직 확실하지는 않을걸요.",en:"It probably is not certain yet."},target:"확실하",options:["to be fun, interesting","to be difficult","to be certain, sure"],note:"-ㄹ걸요 softens a cautious assertion."},{kind:"guess",word:{ko:"분명히",romanization:"bunmyeonghi",en:"clearly, definitely",pos:"adverb",nuance:"분명히 has two jobs: it can describe saying something clearly (분명히 말하다) or strengthen certainty (‘definitely’). In the certainty use it overlaps heavily with 확실히, so context and collocation are more reliable than a rigid subjective-versus-objective split."},sentence:{ko:"분명히 말했으면 오해가 없었을 텐데요.",en:"If I had said it clearly, there would have been no misunderstanding."},target:"분명히",options:["more/less than expected","clearly, definitely","already"],note:"분명히 sharpens the missed action in a regret sentence."},{kind:"payoff",line:{speaker:"민서",ko:"어제 시간이 있었으면 같이 갔을 텐데요.",en:"If I had had time yesterday, I would have gone with you."},hl:"시간"}],canDo:"Acknowledge newly understood information with A/V-군요 / -구나 (안 막혔군요)",id:"chapter-61-b3",chapterId:"chapter-61",index:2},{kind:"pattern",title:`무늬 Pattern · A/V-군요 / -구나: "I see, so that's how it is"`,cards:[{kind:"hunt",name:`A/V-군요 / -구나: "I see, so that's how it is"`,sub:"",lines:[{tokens:[{pre:"아,",mid:"",post:"",hit:!1},{pre:"그래서",mid:"",post:"",hit:!1},{pre:"어제",mid:"",post:"",hit:!1},{pre:"못",mid:"",post:"",hit:!1},{pre:"왔",mid:"군요",post:".",hit:!0}],ko:"아, 그래서 어제 못 왔군요.",en:"Ah, so that's why you couldn't come yesterday.",romanization:"a, geuraeseo eoje mot watgunyo."},{tokens:[{pre:"벌써",mid:"",post:"",hit:!1},{pre:"졸업했",mid:"구나",post:".",hit:!0},{pre:"시간",mid:"",post:"",hit:!1},{pre:"진짜",mid:"",post:"",hit:!1},{pre:"빠르다.",mid:"",post:"",hit:!1}],ko:"벌써 졸업했구나. 시간 진짜 빠르다.",en:"Oh, you already graduated. Time really flies.",romanization:"beolsseo joreophaetguna. sigan jinjja ppareuda."}],rule:{name:`A/V-군요 / -구나: "I see, so that's how it is"`,rows:[{when:"Adjective stem",add:"-군요 / -구나",ex:"춥다 -> 춥군요 / 춥구나 (Ah, it's cold)"},{when:"Verb stem (present)",add:"-는군요 / -는구나",ex:"가다 -> 가는군요 / 가는구나 (I see, you're going)"},{when:"Past tense (verb & adj)",add:"-았/었군요 / -았/었구나",ex:"아프다 -> 아팠군요 / 아팠구나 (Ah, you were sick)"},{when:"Noun + 이다",add:"(이)군요 / (이)구나",ex:"동생이군요 / 동생이구나 (Oh, it's your younger sibling)"}]},more:{func:`-군요 (polite) and -구나 (casual) express the moment of understanding: you take in new information and acknowledge it, often realizing the reason or background behind something. Where -네요 is a gut reaction to what you perceive, -군요/-구나 is the click of comprehension -- "Ah, so THAT'S why / so it's like that."`,keyPoint:{label:"Verbs need -는군요 in the present",body:"Adjectives and nouns attach -군요 directly (춥군요, 학생이군요), but present-tense verbs insert -는-: 가는군요, 먹는군요. Past tense is uniform for both: -았/었군요. -구나 is simply the casual (반말) version."},pronunciation:'-는군요 links the final ㄴ into the 요 in fast speech, sounding like [는군뇨]. The casual -구나 is often drawn out for feeling: 그렇구나~, signaling a thoughtful "ahh, I see."'}},{kind:"drill",prompt:"So THIS is that famous restaurant.",sentence:"이게 그 유명한 식당이___.",options:[{text:"군요",ok:!0},{text:"구나",ok:!1}],explanation:"You connect what you heard before with what you now see -- a moment of recognition, not just surprise."}],canDo:"Acknowledge newly understood information with A/V-군요 / -구나 (안 막혔군요)",id:"chapter-61-b4",chapterId:"chapter-61",index:3},{kind:"words",title:"단어 Words 3 · 당연하다~",cards:[{kind:"guess",word:{ko:"당연하다",romanization:"dangyeonhada",en:"to be natural, obvious, no wonder",pos:"adjective",nuance:"당연하다 can sound dismissive if used carelessly. 당연하네요 is softer than 당연해요 because it frames the comment as realization."},sentence:{ko:"연습을 많이 했으니까 잘하는 게 당연하네요.",en:"Since you practiced a lot, no wonder you are good."},target:"당연하",options:["to be fun, interesting","to be natural, obvious, no wonder","to be difficult"],note:"-네요 makes the comment a realization, not a dismissive judgment."},{kind:"guess",word:{ko:"힘들다",romanization:"himdeulda",en:"to be hard, tiring, tough",pos:"adjective",nuance:"힘들다 literally takes 힘 (strength) + 들다 ('to take/cost'), i.e. 'it costs strength', and covers anything physically OR emotionally hard, tiring, or tough — a grueling shift, single-handed childcare, a rough stretch of life. With the -기 nominalizer it labels a hard task: 공부하기 힘들어요, 참기 힘들어요 ('studying/enduring is hard'). It is a ㄹ-stem word, so the ㄹ drops before endings beginning with ㄴ/ㅅ/ㅂ: honorific 힘드세요?, attributive 힘든 일, 힘듭니다 — not 힘들세요/힘들은. The crucial contrast is with 어렵다: 어렵다 is 'difficult to understand or solve' (a hard math problem, a tricky concept), whereas 힘들다 is 'taxing — tiring or emotionally draining'. A problem can be 어렵다 without being 힘들다, and a job can be 힘들다 (exhausting) yet not 어렵다 (intellectually hard). English-speaker pitfall: English 'hard' blurs both, so learners say 어렵다 for an exhausting day — if it drains your energy or spirit, it's 힘들어요, not 어려워요."},sentence:{ko:"많이 힘들었군요.",en:"That must have been really hard for you."},target:"힘들었",options:["to be fun, interesting","to be hard, tiring, tough","to be difficult"],note:"-군요 can acknowledge someone else's experience with empathy."},{kind:"guess",word:{ko:"알다",romanization:"alda",en:"to know",pos:"verb",nuance:"For a neutral ‘I don't know,’ Korean normally uses 모르다: 몰라요 or the softer 잘 모르겠어요. 안 알아요 is not universally wrong; context can give it ‘I don't recognize/know,’ ‘I won't find out,’ or a contrastive denial, so do not treat it as an impossible form."},sentence:{ko:"그분은 이미 알고 있을걸요.",en:"They probably already know."},target:"알고",options:["to know","to arrive","to be late"],note:"알고 있을걸요 is a common hedged assertion."},{kind:"guess",word:{ko:"모르다",romanization:"moreuda",en:"to not know",pos:"verb",nuance:"모르다 is the standalone verb 'to not know / be unaware of', the lexical opposite of 알다, and it likewise takes the object marker 을/를: 길을 몰라요. It is a 르-irregular: when an 아/어 ending attaches, the 르 stem doubles the ㄹ and the vowel drops, so 모르 + 아요 → 몰라요 (never 모르아요) and the past is 몰랐어요. The crucial register tool is 겠: 잘 모르겠어요 ('I'm not quite sure') is markedly softer and more natural than a blunt 몰라요, which can sound curt or even dismissive depending on tone, so Koreans lean on the 겠 form constantly when admitting ignorance politely. Compare 모르다 with 헷갈리다 ('to be confused / mix things up'): 모르다 is having no information at all, while 헷갈리다 is having information but getting it tangled. The English-speaker pitfall is the conjugation — applying a regular pattern to get 모르아요 instead of the irregular 몰라요 — and forgetting that the smooth, courteous version is 잘 모르겠어요."},sentence:{ko:"그렇군요. 제가 모르고 있었네요.",en:"I see. I did not know that."},target:"모르",options:["to arrive","to be late","to not know"],note:"군요 accepts the fact; 네요 marks the speaker's realization."},{kind:"payoff",line:{speaker:"지훈",ko:"처음에는 어려울 줄 알았는데 생각보다 괜찮군요.",en:"I thought it would be hard at first, but it is better than expected."},hl:"알았"}],canDo:"Offer a soft, reasoned guess with V/A-(으)ㄹ걸요 (안 늦을걸요)",id:"chapter-61-b5",chapterId:"chapter-61",index:4},{kind:"pattern",title:'무늬 Pattern · V/A-(으)ㄹ걸요: "probably," a soft guess',cards:[{kind:"teach",name:'V/A-(으)ㄹ걸요: "probably," a soft guess',sub:"",rows:[{when:"Verb stem ending in vowel",add:"-ㄹ걸요",ex:"오다 -> 올걸요 (They'll probably come)"},{when:"Verb stem ending in consonant",add:"-을걸요",ex:"먹다 -> 먹을걸요 (He probably ate)"},{when:"Past tense (guessing about the past)",add:"-았/었을걸요",ex:"가다 -> 갔을걸요 (They probably already left)"},{when:"Adjective stem",add:"-(으)ㄹ걸요",ex:"비싸다 -> 비쌀걸요 / 좋다 -> 좋을걸요 (probably expensive/good)"},{when:"ㄹ-stem (drop ㄹ, add -걸요)",add:"-ㄹ걸요",ex:"멀다 -> 멀걸요 (It's probably far)"}],examples:[{ko:"지금 가게 문 닫았을걸요.",en:"The shop is probably closed now.",romanization:"jigeum gage mun dadasseulgeoryo.",note:"A soft prediction about a present situation; -았을걸요 guesses the door is already in a closed state."},{ko:"민지 씨는 매운 거 잘 먹을걸요.",en:"Minji can probably handle spicy food well.",romanization:"minji ssineun maeun geo jal meogeulgeoryo.",note:"You're guessing from what you know of her -- not stating a fact, just a confident-but-soft hunch."}],more:{func:`-(으)ㄹ걸요 offers a tentative guess based on your own reasoning or hunch, softened so it doesn't sound too sure. It means "I think probably ..." or "it's likely that ...," and is common when answering someone gently without claiming certainty. (Written the same, -(으)ㄹ걸 그랬다 with a sighing tone means regret, "I should have ...," but here we focus on the guessing use.)`,keyPoint:{label:"-(으)ㄹ걸요 = your guess, not shared knowledge",body:`Use -(으)ㄹ걸요 when the conclusion comes from your own inference and you want to stay humble about it. Compare -(으)ㄹ 거예요, which sounds more confident/declarative. -걸요 always softens, as if to say "I'm fairly sure, but don't quote me."`},pronunciation:"The 걸 is tensed to [껄]: 올걸요 sounds like [올껄요], 먹을걸요 like [머글껄요]. The sentence also rises slightly at the end, giving it its tentative, musing feel."}}],canDo:"Offer a soft, reasoned guess with V/A-(으)ㄹ걸요 (안 늦을걸요)",id:"chapter-61-b6",chapterId:"chapter-61",index:5},{kind:"pattern",title:'무늬 Pattern · V-았/었을 텐데(요): "it would have ..., but"',cards:[{kind:"hunt",name:'V-았/었을 텐데(요): "it would have ..., but"',sub:"",lines:[{tokens:[{pre:"어제",mid:"",post:"",hit:!1},{pre:"시간이",mid:"",post:"",hit:!1},{pre:"있었으면",mid:"",post:"",hit:!1},{pre:"같이",mid:"",post:"",hit:!1},{pre:"갔",mid:"을",post:"",hit:!0},{pre:"",mid:"텐데요",post:".",hit:!0}],ko:"어제 시간이 있었으면 같이 갔을 텐데요.",en:"If I'd had time yesterday, I would have gone with you.",romanization:"eoje sigani isseosseumyeon gachi gasseul tendeyo."},{tokens:[{pre:"조금만",mid:"",post:"",hit:!1},{pre:"일찍",mid:"",post:"",hit:!1},{pre:"왔으면",mid:"",post:"",hit:!1},{pre:"표를",mid:"",post:"",hit:!1},{pre:"살",mid:"",post:"",hit:!1},{pre:"수",mid:"",post:"",hit:!1},{pre:"있",mid:"었을",post:"",hit:!0},{pre:"",mid:"텐데요",post:".",hit:!0}],ko:"조금만 일찍 왔으면 표를 살 수 있었을 텐데요.",en:"If you'd come just a bit earlier, you could have bought a ticket.",romanization:"jogeumman iljjik wasseumyeon pyoreul sal su isseosseul tendeyo."}],rule:{name:'V-았/었을 텐데(요): "it would have ..., but"',rows:[{when:"Verb, past supposition",add:"-았/었을 텐데(요)",ex:"오다 -> 왔을 텐데요 (They would have come)"},{when:"Often after an unreal condition -았/었으면",add:"-았/었으면 ... -았/었을 텐데요",ex:"시간이 있었으면 갔을 텐데요 (If I'd had time, I'd have gone)"},{when:"Adjective, past supposition",add:"-았/었을 텐데(요)",ex:"쉽다 -> 쉬웠을 텐데요 (It would have been easy)"},{when:"Present/future concern (contrast)",add:"-(으)ㄹ 텐데(요)",ex:"바쁘다 -> 바쁠 텐데요 (They must be busy, though)"}]},more:{func:`-았/었을 텐데(요) expresses a confident guess about an unrealized past -- what surely would have happened -- usually paired with a contrasting reality, regret, or concern. It looks back and supposes: "It would have been ... (but it wasn't / but something got in the way)." The 텐데 leaves the thought hanging, inviting sympathy or a soft follow-up rather than a blunt complaint.`,keyPoint:{label:"Past -았/었을 텐데 = unreal past; present -(으)ㄹ 텐데 = current concern",body:`Add the past -았/었- when you're supposing about something that did NOT happen (regret): 갔을 텐데요. Drop it for a present/future worry or contrast: 지금 바쁠 텐데요 ("they must be busy right now, though"). Mixing these changes the meaning from regret to ongoing concern.`},pronunciation:"텐데 is [텐데] with a clear, even tone, but the sentence-final 요 trails off and drops in pitch -- that falling, unfinished melody is what signals the lingering 'but...' feeling. Don't end it sharply."}}],canDo:"Suppose about an unrealized past with V-았/었을 텐데(요) (늦었을 텐데요)",id:"chapter-61-b7",chapterId:"chapter-61",index:6},{kind:"pattern",title:"무늬 Pattern · -군요 vs -네요: both react, but not the same way",cards:[{kind:"hunt",name:"-군요 vs -네요: both react, but not the same way",sub:"",lines:[{tokens:[{pre:"어,",mid:"",post:"",hit:!1},{pre:"눈이",mid:"",post:"",hit:!1},{pre:"오",mid:"네요",post:"!",hit:!0}],ko:"어, 눈이 오네요!",en:"Oh, it's snowing!",romanization:"eo, nuni oneyo!"},{tokens:[{pre:"아,",mid:"",post:"",hit:!1},{pre:"그래서",mid:"",post:"",hit:!1},{pre:"늦으셨",mid:"군요",post:".",hit:!0}],ko:"아, 그래서 늦으셨군요.",en:"Ah, so that's why you were late.",romanization:"a, geuraeseo neujeusyeotgunyo."}],rule:{name:"-군요 vs -네요: both react, but not the same way",rows:[{when:"Fresh, direct noticing (see/hear/feel now)",add:"-네요",ex:"비가 오네요 (Oh, it's raining)"},{when:"Acknowledging a fact/explanation you just learned",add:"-군요 / -구나",ex:"아, 그렇군요 (Ah, I see)"},{when:"Verb present: -네요 (no 는) vs -는군요 (needs 는)",add:"-네요 / -는군요",ex:"가네요 / 가는군요"},{when:"Reacting to a reason (그래서 ...)",add:"often -군요",ex:"그래서 못 왔군요 (So that's why you couldn't come)"}]},more:{func:`-네요 and -군요 both respond to new information, but with a different feel. -네요 is an immediate, conversational gut reaction to what you directly perceive right now ("oh, look at that"). -군요 is a slightly more composed acknowledgement -- you take in a fact or explanation and register it ("I see, so that's the case"). Knowing which one to reach for keeps your reactions sounding natural.`,keyPoint:{label:"Perceiving now -> -네요; registering a fact -> -군요",body:"If you're reacting to something you directly sense at this moment (taste, weather, someone's arrival), -네요 sounds warm and natural. If you're acknowledging information or a reason that just clicked, -군요 fits. -군요 can sound stiff for simple sensory reactions, and -네요 can sound under-reactive for absorbing a full explanation."},pronunciation:"그렇군요 is pronounced [그러쿠뇨] (ㅎ + ㄱ tenses/aspirates to ㅋ), and 그렇네요 is [그런네요] (ㅎ assimilates to ㄴ before ㄴ). Both are extremely common backchannels -- saying them clearly helps you sound like an engaged listener."}}],canDo:"React to something noticed right now with A/V-네요 (벌써 도착했네요)",id:"chapter-61-b8",chapterId:"chapter-61",index:7},{kind:"dialogue",title:"대화 Dialogue · 진짜 한국어",cards:[{kind:"chat",setting:"Friends react to a class, a late schedule, and a missed chance while choosing endings that match their stance.",lines:[{speaker:"민서",ko:"한국어가 생각보다 재미있네요.",en:"Korean is more fun than I expected.",romanization:"hangugeoga saenggakboda jaemiinneyo."},{speaker:"지훈",ko:"처음에는 어려울 줄 알았는데 생각보다 괜찮군요.",en:"I thought it would be hard at first, but it is better than expected.",romanization:"cheoeumeneun eoryeoul jul aranneunde saenggakboda gwaenchanhgunyo."},{speaker:"민서",ko:"선생님은 벌써 도착하셨네요.",en:"Oh, the teacher has already arrived.",romanization:"seonsaengnimeun beolsseo dochakhasyeonneyo."},{speaker:"지훈",ko:"지금 출발하면 우리는 조금 늦을걸요.",en:"If we leave now, we will probably be a little late.",romanization:"jigeum chulbalhamyeon urineun jogeum neujeulgeoryo."},{speaker:"민서",ko:"어제 시간이 있었으면 같이 갔을 텐데요.",en:"If I had had time yesterday, I would have gone with you.",romanization:"eoje sigani isseosseumyeon gachi gasseul tendeyo."},{speaker:"지훈",ko:"연습을 많이 했으니까 잘하는 게 당연하네요.",en:"Since you practiced a lot, no wonder you are good.",romanization:"yeonseubeul mani haesseunikka jalhaneun ge dangyeonhaneyo."}]},{kind:"order",prompt:"Build: 'Oh, they already arrived.'",tokens:["아,","벌써 도착했군요"],correct:"아, 벌써 도착했군요",explanation:"-군요 acknowledges or takes in information with a stronger “I see” feeling. 벌써 adds the surprise that it already happened."}],canDo:"React to something noticed right now with A/V-네요 (벌써 도착했네요)",id:"chapter-61-b9",chapterId:"chapter-61",index:8},{kind:"reading",title:"읽기 Reading · 끝 어미가 태도를 바꾼다",cards:[{kind:"read",title:"끝 어미가 태도를 바꾼다",chunks:['민서는 첫 수업을 듣고 "생각보다 재미있네요"라고 말했다. 방금 느낀 놀라움이라서 -네요가 자연스러웠다. 지훈은 설명을 듣고 "그렇군요"라고 했다. 새 정보를 받아들이는 조금 더 차분한 반응이었다.','수업이 끝난 뒤 선생님이 이미 도착한 것을 보고 민서는 "벌써 도착하셨네요"라고 했고, 지훈은 시간을 보더니 "지금 출발하면 늦을걸요"라고 했다. 나중에 민서는 약속에 가지 못한 일을 떠올리며 "시간이 있었으면 같이 갔을 텐데요"라고 말했다. 같은 사실도 끝 어미가 달라지면 놀람, 인정, 예측, 아쉬움이 서로 다르게 들린다.'],translation:'After the first class, Minseo said, "It is more fun than I expected." Because it was a surprise she had just felt, -네요 was natural. Jihoon listened to an explanation and said, "I see." That was a calmer acknowledgement of new information. After class, Minseo saw that the teacher had already arrived and said, "Oh, the teacher has already arrived." Jihoon looked at the time and said, "If we leave now, we will probably be late." Later, Minseo remembered not being able to go to an appointment and said, "If I had had time, I would have gone with you." Even with the same facts, the final ending changes whether the sentence sounds like surprise, acknowledgement, prediction, or regret.',qas:[{q:"민서는 첫 수업 뒤에 어떤 어미를 사용했어요?",a:"-네요를 사용했어요."},{q:'지훈이 "늦을걸요"라고 한 이유는 무엇이에요?',a:"지금 출발하면 늦을 것 같다고 부드럽게 예측했기 때문이에요."},{q:"-았/었을 텐데요는 어떤 느낌을 나타냈어요?",a:"과거에 이루어지지 않은 일에 대한 아쉬움이나 후회를 나타냈어요."}]}],canDo:"Acknowledge newly understood information with A/V-군요 / -구나 (안 막혔군요)",id:"chapter-61-b10",chapterId:"chapter-61",index:9},{kind:"boss",title:"보스 Boss bite · 다 걸어요",cards:[{kind:"drill",prompt:"Which ending fits a fresh realization after trying Korean class?",sentence:null,options:[{text:"생각보다 재미있네요.",ok:!0},{text:"생각보다 재미있기로 했어요.",ok:!1},{text:"생각보다 재미있을 수밖에 없었어요.",ok:!1}],explanation:"-네요 marks fresh realization."},{kind:"drill",prompt:"Which sentence is a softened prediction?",sentence:null,options:[{text:"지금 출발하면 조금 늦을걸요.",ok:!0},{text:"지금 출발하면 조금 늦었군요.",ok:!1},{text:"지금 출발하면 조금 늦었을 텐데요.",ok:!1}],explanation:"-ㄹ걸요 gives a hedged assertion or prediction."},{kind:"drill",prompt:"Which sentence expresses regret about a missed past condition?",sentence:null,options:[{text:"시간이 있었으면 같이 갔을 텐데요.",ok:!0},{text:"시간이 있으면 같이 가네요.",ok:!1},{text:"시간이 있어서 같이 갈걸요.",ok:!1}],explanation:"-았/었으면 ... -았/었을 텐데요 frames an unreal past."},{kind:"drill",prompt:"생각___ 더 재미있네요. (It is more fun than I expected.)",sentence:null,options:[{text:"보다",ok:!0},{text:"에",ok:!1},{text:"를",ok:!1}],explanation:"생각보다 means compared with what I thought or expected. -네요 then reacts to the fresh realization."},{kind:"order",prompt:"Build: 'Oh, they already arrived.'",tokens:["아,","벌써 도착했군요"],correct:"아, 벌써 도착했군요",explanation:"-군요 acknowledges or takes in information with a stronger “I see” feeling. 벌써 adds the surprise that it already happened."},{kind:"drill",prompt:"You just tried the class and are surprised it is fun. Which fits?",sentence:null,options:[{text:"생각보다 재미있네요.",ok:!0},{text:"생각보다 재미있을걸요.",ok:!1},{text:"생각보다 재미있었을 텐데요.",ok:!1}],explanation:"-네요 fits fresh realization from direct experience. -ㄹ걸요 is a guess, and -었을 텐데요 is regret/hypothetical."}],canDo:"Offer a soft, reasoned guess with V/A-(으)ㄹ걸요 (안 늦을걸요)",id:"chapter-61-b11",chapterId:"chapter-61",index:10}]},{id:"chapter-62",number:62,title:"이/가 · 은/는",goal:"Use 이/가 for new information, focused answers, and existence predicates.",biteCount:11,bites:[{kind:"words",title:"단어 Words 1 · 친구~",cards:[{kind:"guess",word:{ko:"친구",romanization:"chingu",en:"friend",pos:"noun",nuance:"친구 can mean friend or same-age peer depending on context."},sentence:{ko:"친구가 전화했어요. 그 친구는 자주 전화하지 않아요.",en:"A friend called. That friend does not call often."},target:"친구",options:["phone call","contact, getting in touch","friend"],note:"First mention uses 가; continued topic uses 는."},{kind:"guess",word:{ko:"전화",romanization:"jeonhwa",en:"phone call",pos:"noun",nuance:"전화 is a noun, but 전화하다 is the verb “to call.”"},sentence:{ko:"메시지는 보내지만 전화는 잘 안 해요.",en:"I send messages, but I do not call much."},target:"전화",options:["phone call","friend","contact, getting in touch"],note:"전화는 contrasts calls with messages."},{kind:"guess",word:{ko:"연락",romanization:"yeollak",en:"contact, getting in touch",pos:"noun",nuance:"연락(連絡) is Sino-Korean — 連 'connect/link' + 絡 'tie, network' — literally 'to link up,' and it covers ANY channel of reaching a person: a call, a text, a message, an email. The near-synonym to contrast is 소식: 연락 is the ACT/CHANNEL of getting in touch ('drop me a line'), while 소식 is the CONTENT/word about how someone is. Compare 통화(通話) 'a phone call (specifically)' — narrower than 연락. The crucial grammar quirk for English speakers: 연락 flips between particles. When YOU reach out it's 연락을 하다 / 연락하다 (object 를), but when contact COMES to you it's 연락이 오다 and reachability is 연락이 되다 (subject 이/가) — saying 연락을 오다 is a classic error. Also, English 'contact someone' has a direct object, so learners drop the person-marking 한테/에게: it should be 친구한테 연락하다, and incoming contact is 친구한테서/에게서 연락이 오다. 연락처 (with 처) means your number/details, not the verb."},sentence:{ko:"누가 먼저 연락했어요? 제가 먼저 연락했어요.",en:"Who contacted first? I contacted first."},target:"연락",options:["contact, getting in touch","friend","phone call"],note:"제가 answers 누가 with focus."},{kind:"guess",word:{ko:"메시지",romanization:"mesiji",en:"message",pos:"noun",nuance:"메시지 is the loanword from English 'message' and covers chat/app messages broadly (a KakaoTalk message, a DM); the everyday near-synonym 문자 (literally 文字 'letters/characters') specifically means an SMS text, so '문자 보내' = 'text me' while '메시지' is the wider term. There's also 카톡, the verb-able brand shorthand for a KakaoTalk message, used constantly in real life (카톡 보낼게 'I'll Kakao you'). The English-speaker pitfall is twofold: first, the recipient is marked with 한테/에게 ('to a person'), not the English bare object — 친구한테 메시지를 보내다, where 친구한테 = 'to my friend' and 메시지를 is the thing sent; second, the message arriving uses intransitive 오다 with 이/가 (메시지가 오다), but you sending it uses 보내다 with 을/를 (메시지를 보내다). Don't carry the English 'send him a message' double-object pattern straight over."},sentence:{ko:"메시지는 자주 보내지만 전화는 잘 안 해요.",en:"I send messages often, but I do not call much."},target:"메시지",options:["friend","message","phone call"],note:"은/는 makes the contrast visible."},{kind:"guess",word:{ko:"문자",romanization:"munja",en:"text message",pos:"noun",nuance:"문자 (文字, 'written character/letter') in daily speech is the everyday word for an SMS text message — short for 문자 메시지. The pitfall is its double life: literally 문자 means written characters/letters (e.g. 한글은 한국의 문자예요, 'Hangul is Korea's writing system'), so context decides. Crucially, 문자 is NOT a paper letter in the mail — that is 편지 (便紙). The near-synonym 카톡 (a KakaoTalk message) is what most people actually send now; 문자 specifically implies the carrier SMS (often bank/official notices), while a casual chat is 카톡 or 메시지. Register is neutral. Habitual collocations: 문자를 보내다/받다, 문자가 오다, 문자를 확인하다, 문자로 연락하다, and the source pattern 은행/회사에서 문자가 오다. Particle traps: 'by text' is 문자로 (means); the sender/source is marked 에서 for organizations (은행에서) or 한테서/에게서 for people. English speakers often want 'text' as a verb — Korean splits it into 문자를 보내다 (send a text)."},sentence:{ko:"문자는 왔는데 전화는 안 왔어요.",en:"A text came, but no phone call came."},target:"문자",options:["friend","phone call","text message"],note:"문자는 and 전화는 contrast two channels."},{kind:"guess",word:{ko:"누구",romanization:"nugu",en:"who",pos:"questionWord",nuance:"누구 changes naturally with particles: 누구를, 누구한테, 누구하고."},sentence:{ko:"누가 먼저 연락했어요?",en:"Who contacted first?"},target:null,options:["friend","phone call","who"],note:"누구 + 가 contracts to 누가."},{kind:"guess",word:{ko:"먼저",romanization:"meonjeo",en:"first",pos:"adverb",nuance:"먼저 means 'first / beforehand / ahead (of others)' — it ranks one action or person EARLIER in a sequence or in time. The key contrast is 먼저 vs 처음: 먼저 is relative ('before the other thing/person', e.g. 먼저 가요 'go ahead of you'), while 처음 means 'the first time ever / the beginning' (처음 만나요 'meeting for the first time'). So 먼저 봤어요 = 'I saw it first (before you)', but 처음 봤어요 = 'I saw it for the first time'. 먼저 is also a courtesy word: 먼저 가세요 / 먼저 하세요 ('go ahead, you first') is everyday politeness, and 먼저 갈게요 / 먼저 들어가겠습니다 softens leaving before others. Register-neutral. The English-speaker pitfall is mapping every 'first' to one word — choose 먼저 for order-relative 'first/ahead', but 처음 for 'first-ever/at first', and keep 먼저 before the verb."},sentence:{ko:"오늘은 제가 먼저 연락했어요.",en:"Today, I contacted first."},target:"먼저",options:["often","first","friend"],note:"오늘은 contrasts today; 제가 identifies the actor."},{kind:"guess",word:{ko:"자주",romanization:"jaju",en:"often",pos:"adverb",nuance:"자주 means 'often / frequently' and describes how many TIMES an action repeats over a period — it answers 얼마나 자주 ('how often'), never how fast or how well. The frequency scale runs 항상(always) > 자주(often) > 가끔(sometimes) > 거의 안(hardly), and 자주 sits high but short of 'always'. Its natural opposite is 가끔; learners confuse 자주 with 빨리(quickly), but 자주 is about count of occurrences while 빨리 is about speed of one action — 빨리 먹어요 means 'eats fast', 자주 먹어요 means 'eats often'. Register-neutral, fine for everyone. The big English-speaker pitfall is word order: English lets you say 'I go there often' with the adverb last, but Korean glues 자주 immediately before the verb (자주 가요), and even before 안/못 in negatives (자주 안 가요)."},sentence:{ko:"그 친구는 자주 전화해요?",en:"Does that friend call often?"},target:"자주",options:["first","often","friend"],note:"은/는 keeps the friend as the topic while asking about habit."},{kind:"payoff",line:{speaker:"민서",ko:"어제 친구가 전화했어요.",en:"A friend called yesterday."},hl:"친구"}],canDo:"Spotlight a new or focused subject with 이/가 (친구가 보냈어요)",id:"chapter-62-b1",chapterId:"chapter-62",index:0},{kind:"pattern",title:"무늬 Pattern · 이/가",cards:[{kind:"hunt",name:"이/가",sub:"a new or focused subject (new information)",lines:[{tokens:[{pre:"비",mid:"가",post:"",hit:!0},{pre:"와요.",mid:"",post:"",hit:!1}],ko:"비가 와요.",en:"It's raining.",romanization:"biga wayo."},{tokens:[{pre:"누",mid:"가",post:"",hit:!0},{pre:"한국어를",mid:"",post:"",hit:!1},{pre:"가르쳐요?",mid:"",post:"",hit:!1}],ko:"누가 한국어를 가르쳐요?",en:"Who teaches Korean?",romanization:"nuga hangugeoreul gareuchyeoyo?"}],rule:{name:"이/가",rows:[{when:"subject noun ends in a consonant",add:"+ 이",ex:"선생님 → 선생님이"},{when:"subject noun ends in a vowel",add:"+ 가",ex:"친구 → 친구가"},{when:"answering 누가/뭐가 (who/what)",add:"marked noun = the answer",ex:"누가 왔어요? → 동생이 왔어요."}]},more:{func:"The subject marker 이/가 spotlights WHO or WHAT does or is something. Use it when the subject is new to the conversation, when it answers a 'who?'/'what?' question, or when you want the listener's attention on that exact element. It introduces; it does not assume.",keyPoint:{label:"이/가 = new and in focus",body:"Compare 누가 왔어요? — 친구가 왔어요 (NEW: 가) with 친구는 언제 와요? (already-known friend: 는). 이/가 answers 'who/what'; 은/는 talks ABOUT a known thing."},pronunciation:"이 after a consonant links smoothly: 선생님이 sounds like 선생니미; 책이 like 채기. The final consonant slides onto 이."}}],canDo:"Spotlight a new or focused subject with 이/가 (친구가 보냈어요)",id:"chapter-62-b2",chapterId:"chapter-62",index:1},{kind:"words",title:"단어 Words 2 · 평소~",cards:[{kind:"guess",word:{ko:"평소",romanization:"pyeongso",en:"usually, normally",pos:"noun",nuance:"평소 is a Sino-Korean noun, 平素 'level-plain / ordinary times', meaning your normal, everyday baseline — the way things usually are when nothing special is going on. Because it's fundamentally a noun, it leans on particles: in conversation it's overwhelmingly 평소에 'usually', or comparative 평소보다 'than usual', or 평소처럼 'as usual'. Its job is to set a default against which you contrast today (평소보다 많아요 'more than usual'). The near-synonym 보통 普通 also means 'usually/ordinarily' and overlaps heavily; the subtle feel is that 평소 points to 'one's ordinary times/baseline' while 보통 states 'as a general rule', so 평소에 운동해요 and 보통 운동해요 are both fine. The English-speaker trap is treating 평소 like a bare adverb such as 항상 and dropping the particle — 'I usually...' wants 평소에, not lonely 평소. It's also not a verb, so never conjugate it; pair it with 에, 보다, 처럼, and attributive nouns (실력, 생활)."},sentence:{ko:"평소에는 메시지를 보내는데 오늘은 전화했어요.",en:"Usually they send messages, but today they called."},target:"평소",options:["friend","usually, normally","phone call"],note:"평소에는 contrasts the usual pattern with today."},{kind:"guess",word:{ko:"오늘",romanization:"oneul",en:"today",pos:"noun",nuance:"오늘 usually does not need 에. 오늘에 sounds unnatural for ordinary “today.”"},sentence:{ko:"오늘은 제가 먼저 연락했어요.",en:"Today, I contacted first."},target:"오늘",options:["friend","today","phone call"],note:"오늘은 contrasts today with other days."},{kind:"guess",word:{ko:"보내다",romanization:"bonaeda",en:"to send",pos:"verb",nuance:"보내다 means to send something or someone away from you toward another place or person — a message, a parcel, even a child to school — and it also carries the everyday idiom 시간을 보내다, 'to spend/pass time'. The sharp contrast is 보내다 vs 주다: 주다 (to give) is a face-to-face hand-over where giver and receiver are together, while 보내다 implies distance — the thing travels to reach the other person. So you 줘요 a gift you hand over now, but 보내요 a gift you mail; using 주다 for a text or parcel sounds like you are physically handing it across. The recipient particle is 에게/한테 (and honorific 께): 부모님께 보내다. For the 'spend time' sense, English speakers wrongly reach for 쓰다 (to use/spend money) — but time is 보내다, not 쓰다: 좋은 시간 보내세요! is the standard 'have a good time'. It is a plain native verb, regular (stem 보내- + 어 contracts to 보내, past 보냈어요), neutral register. The means/channel takes 으로 (이메일로, 택배로). Common collocations: 문자·이메일을 보내다, 소포·택배를 보내다, 시간·세월을 보내다, 사람을 보내다."},sentence:{ko:"메시지는 자주 보내지만 전화는 잘 안 해요.",en:"I send messages often, but I do not call much."},target:"보내",options:["friend","to send","phone call"],note:"The object 메시지 takes 를; the contrast uses 는."},{kind:"guess",word:{ko:"질문",romanization:"jilmun",en:"question",pos:"noun",nuance:"질문 is Sino-Korean 質問 — 質 'substance/inquire into' + 問 'ask', literally 'to inquire and ask', i.e. a question put to someone. The set verb is 질문을 하다 (or the single verb 질문하다); the person you ask takes 에게/한테 (or honorific 께 for a teacher): 선생님께 질문을 하다. Its natural partner is 대답/답(答) — a 질문 is answered by a 대답. The big redundancy trap for English speakers is 질문을 물어보다 ✗: 물어보다 already means 'to ask', so this literally says 'ask a question-asking' — say either 질문을 하다 or just 물어보다, never both. Distinguish 질문 (a question seeking information/an answer) from 문제(問題, a 'problem' or exam item) — '3 questions on the test' are 문제 세 개, but 'I have a question for you' is 질문이 있어요. Note answering takes 에: 질문에 답하다, not 질문을 답하다."},sentence:{ko:"질문은 쉬웠는데 대답이 어려웠어요.",en:"The question was easy, but the answer was difficult."},target:"질문",options:["friend","question","phone call"],note:"질문은 is the contrastive topic."},{kind:"guess",word:{ko:"대답",romanization:"daedap",en:"answer, reply",pos:"noun",nuance:"대답 is Sino-Korean 對答 — 對 'face/respond-to' + 答 'reply', literally 'a facing reply', i.e. the spoken/written response to a question or call. It is the natural partner of 질문(質問): a 질문 is met by a 대답, and the verb is 대답을 하다 / 대답하다. The sharp contrast to master is 대답 vs 정답(正答, 正 'correct' + 答): 대답 is simply 'a/the response someone gives' (it can be right or wrong), while 정답 is specifically 'the correct answer' to a problem — so on a quiz '정답은 3번이에요' = 'the correct answer is number 3', but 그 학생의 대답 = 'that student's response'. Also note 답 alone is a shorter everyday form of both. The particle pitfall mirrors 질문: you answer a question with 에 — 질문에 대답하다 / 질문에 답하다, NOT 질문을 대답하다. English 'answer the phone/door' does not use 대답 either — that is 전화를 받다 / 문을 열다."},sentence:{ko:"대답이 어려웠어요.",en:"The answer was difficult."},target:"대답",options:["answer, reply","friend","phone call"],note:"대답이 introduces the part that was difficult."},{kind:"guess",word:{ko:"의견",romanization:"uigyeon",en:"opinion",pos:"noun",nuance:"의견 is Sino-Korean (意見, 意 'mind/intention' + 見 'view/seeing'), literally 'how your mind sees something' — a considered position or judgment you can defend, usually about a topic, plan, or issue. The crucial contrast is with 생각: 생각 is the broad word for any 'thought' that crosses your mind, while 의견 is specifically a stance offered for discussion or evaluation, so a meeting asks for 의견 (positions), not just 생각 (musings). It is register-neutral and very common in school and workplace settings; the polite request 의견을 여쭤봐도 될까요? raises it a notch. Natural collocations: 의견을 말하다/내다/제시하다 (state/put forward), 의견이 다르다/같다 (disagree/agree), 의견을 모으다 (gather opinions), 반대 의견 (an opposing view). The English-speaker pitfall is reaching for 의견 every time you'd say 'I think' — 'I think it's good' is 좋은 것 같아요 or 좋다고 생각해요, NOT 좋은 의견이에요; 의견 is the opinion itself as a thing, not the act of thinking. Also don't say 의견하다 — there is no such verb; you 의견을 말하다."},sentence:{ko:"제 의견은 생각이 조금 달라요.",en:"As for my opinion, the thinking is a little different."},target:"의견",options:["opinion","friend","phone call"],note:"의견은 frames the topic; 생각이 states what differs."},{kind:"guess",word:{ko:"생각",romanization:"saenggak",en:"thought, idea",pos:"noun",nuance:"생각 is the native Korean catch-all noun for a 'thought', 'idea', or 'opinion' — anything that happens in the mind: memories, intentions, plans, beliefs, judgments. It is far broader and softer than Sino-Korean 의견 (a defined stance for discussion): 좋은 생각이에요 praises an idea, whereas 의견 frames it as a formal position. It also overlaps with 마음 ('heart/mind' as feeling/will), but 생각 is the cognitive 'thinking' side while 마음 is the emotional/volitional side — 생각이 바뀌다 = I changed my mind (reasoning), 마음이 바뀌다 = my heart changed (feelings). Register-neutral and one of the highest-frequency nouns in the language. Key collocations: 생각이 나다 (come to mind/remember), 생각이 들다 (a thought arises), 생각해 보다 (think it over), ~라고 생각하다 (to think that ~). The big English-speaker pitfall is the verb pattern: 'I think that it's true' is 사실이라고 생각해요 with the quotative ~라고, not 사실 생각해요; and 'I remember' is most naturally 생각나요, not a literal translation. Don't confuse 생각나다 (it comes to mind, intransitive) with 생각하다 (to actively think, transitive)."},sentence:{ko:"그 생각은 좋은데 이유가 부족해요.",en:"That idea is good, but the reason is lacking."},target:"생각",options:["thought, idea","friend","phone call"],note:"생각은 frames the idea; 이유가 introduces the problem."},{kind:"guess",word:{ko:"문제",romanization:"munje",en:"problem, issue",pos:"noun",nuance:"문제(問題, 'ask + topic') has two everyday senses English keeps apart: a trouble or difficulty ('we have a problem') AND a question on a test or exercise ('problem 3'). Crucially, both are solved with the same verb 풀다 (literally 'to untie/loosen') — 문제를 풀다 works for a math item and for a real-life difficulty alike, where English would switch to 'answer' vs 'solve.' Other key partners: 문제가 생기다 (a problem arises), 문제가 되다 (to become an issue), and the handy one-word 문제없어요 ('no problem'). Contrast 문제 with 질문 (a question you ASK someone to get information) — a test 문제 is a problem to solve, but raising your hand to ask is 질문하다, not 문제하다. The English-speaker pitfall is the subject/object split: existence and arising take 이 (문제가 있다/생기다), but solving takes 를 (문제를 풀다) — learners often say 문제가 풀어요."},sentence:{ko:"이 문제는 이유가 제일 중요해요.",en:"For this issue, the reason is the most important thing."},target:"문제",options:["friend","problem, issue","phone call"],note:"문제는 sets the frame; 이유가 is the key subject."},{kind:"payoff",line:{speaker:"민서",ko:"아니요. 평소에는 메시지를 보내는데 오늘은 제가 먼저 연락했어요.",en:"No. Usually they send messages, but today I contacted them first."},hl:"평소"}],canDo:"Set up an already-known topic with 은/는 (저는 …, 그 친구는 …)",id:"chapter-62-b3",chapterId:"chapter-62",index:2},{kind:"pattern",title:"무늬 Pattern · 은/는",cards:[{kind:"hunt",name:"은/는",sub:"topic continuity (an already-known topic)",lines:[{tokens:[{pre:"저",mid:"는",post:"",hit:!0},{pre:"학생이에요.",mid:"",post:"",hit:!1}],ko:"저는 학생이에요.",en:"I'm a student.",romanization:"jeoneun haksaengieyo."},{tokens:[{pre:"오늘",mid:"은",post:"",hit:!0},{pre:"날씨가",mid:"",post:"",hit:!1},{pre:"좋아요.",mid:"",post:"",hit:!1}],ko:"오늘은 날씨가 좋아요.",en:"The weather is nice today.",romanization:"oneureun nalssiga joayo."}],rule:{name:"은/는",rows:[{when:"topic noun ends in a consonant",add:"+ 은",ex:"선생님 → 선생님은"},{when:"topic noun ends in a vowel",add:"+ 는",ex:"저 → 저는"},{when:"stating a general fact",add:"topic + comment",ex:"강아지는 귀여워요. (Puppies are cute.)"}]},more:{func:"The topic marker 은/는 sets up what the sentence is ABOUT. Use it for something already known, already mentioned, or generally assumed — the shared starting point. It says 'as for X…' and then comments on it. It carries old information, not new.",keyPoint:{label:"은/는 = old, 이/가 = new",body:"First mention introduces with 이/가; once it's on the table, you keep talking about it with 은/는. 옛날에 한 남자가 살았어요. 그 남자는… (A man lived… The man…)."},pronunciation:"은 after a consonant resyllabifies: 선생님은 → 선생니믄; 책은 → 채근. Keep 는 as a clear 'neun' with no vowel reduction."}},{kind:"drill",prompt:"That movie was really fun.",sentence:"그 영화___ 정말 재미있었어요.",options:[{text:"는",ok:!0},{text:"은",ok:!1}],explanation:"그 영화 is already known (we both know which movie), so 는 continues it as the topic."}],canDo:"Set up an already-known topic with 은/는 (저는 …, 그 친구는 …)",id:"chapter-62-b4",chapterId:"chapter-62",index:3},{kind:"words",title:"단어 Words 3 · 이유~",cards:[{kind:"guess",word:{ko:"이유",romanization:"iyu",en:"reason",pos:"noun",nuance:"이유 is Sino-Korean (理由, 理 'principle/logic' + 由 'cause/origin'), the 'reason' or grounds behind something — the answer to 'why?'. Its sharpest contrast is with 원인 (原因, 'cause'): 이유 is the justification or motive a person gives ('the reason I'm late'), often subjective and explainable, while 원인 is the objective, often impersonal cause of a result ('the cause of the fire', 화재의 원인). So you ask a friend 무슨 이유로 늦었어? but an investigator looks for the 원인 of an accident. Also distinguish 까닭, a more native, slightly literary synonym of 이유. Register-neutral and extremely common. Core collocations: 이유가 있다/없다, 이유를 묻다/대다/설명하다, 이유 없이 (for no reason), 그런 이유로 (for that reason), ~는 이유는 (the reason that ~ is). The English-speaker pitfall: don't bolt 이유 onto a 'because' clause redundantly — Korean already has 왜냐하면 ... 때문이에요 / ~기 때문에 to say 'because', so '왜냐하면 그 이유는...' is clunky; pick one. Also, 'the reason is because...' should be ~는 이유는 ... 때문이에요, where the sentence ends in 때문이다, not a second 이유."},sentence:{ko:"무엇이 중요해요? 이유가 중요해요.",en:"What is important? The reason is important."},target:"이유",options:["friend","phone call","reason"],note:"이유가 answers 무엇이."},{kind:"guess",word:{ko:"차이",romanization:"chai",en:"difference",pos:"noun",nuance:"차이 is Sino-Korean (差異, 差 'discrepancy/gap' + 異 'different'), the 'difference', 'gap', or 'disparity' between two or more things. It pairs with two key verbs: 차이가 있다 (a difference exists, more static) and 차이가 나다 (a difference shows up/emerges, more dynamic, often for a noticeable gap, e.g. 실력 차이가 나다 = a clear skill gap). The thing you compare with takes ~와/과 (A는 B와 차이가 있다), and the dimension of difference takes ~에(서) (의미에 차이가 있다 = a difference in meaning). Contrast 차이 with 다르다, the adjective 'to be different': 다르다 describes that two things are not the same (A와 B는 달라요), while 차이 is the noun naming the gap itself (A와 B는 차이가 있어요) — Koreans often use 다르다 for a qualitative 'different' and 차이 for a measurable/quantifiable gap (나이 차이 = age gap, 온도 차이 = temperature difference). Don't confuse 차이 with 차별 (差別, 'discrimination'), which is unfair treatment based on a difference. Register-neutral, very common. Collocations: 차이가 있다/없다/나다/크다, 차이를 느끼다 (feel a difference), 큰 차이, 별 차이 없다 (no real difference), 나이 차이/시차 (time difference). The English-speaker pitfall: 'A is different from B' is most naturally A는 B와 달라요 (using 다르다 + 와), not A는 B에서 차이예요; reach for the noun 차이 when you mean 'the difference between/in', and the verb 다르다 when you simply mean 'differs'."},sentence:{ko:"두 표현은 차이가 있어요.",en:"The two expressions have a difference."},target:"차이",options:["difference","friend","phone call"],note:"은/는 frames the two expressions; 차이가 states what exists."},{kind:"guess",word:{ko:"상황",romanization:"sanghwang",en:"situation",pos:"noun",nuance:"상황 (狀況, '狀 condition/form + 況 circumstances' — the configuration of circumstances) describes the overall set of conditions surrounding a moment or event, broader than a single 경우 (a specific case or instance — 이런 경우 = 'in this one case', vs 이런 상황 = 'in this whole situation'). The reflexive phrase 상황에 따라(서) 다르다 ('it depends on the situation') is one of the most useful hedges in Korean, and 이런/그런 상황에서 sets up advice or reactions. Register is neutral. Two pitfalls: keep 상황 (the circumstances around an event) distinct from 상태 (狀態, the state/condition of a single thing or body — 건강 상태 'health condition', 배터리 상태 'battery state'); you describe a person's mood with a 상태, but the events around them with a 상황. And use 에 따라 (not 으로) for 'depending on': 상황에 따라, never 상황으로."},sentence:{ko:"이런 상황에서는 제가 먼저 말해야 해요.",en:"In this kind of situation, I should speak first."},target:"상황",options:["friend","phone call","situation"],note:"상황에서는 frames the condition; 제가 identifies the actor."},{kind:"guess",word:{ko:"사실",romanization:"sasil",en:"fact, truth",pos:"noun",nuance:"사실 (事實, 事 'matter' + 實 'real/true') literally means 'the real state of a matter', so it covers both the noun 'fact' and the adverb 'actually/in fact'. Compare it with 진실: 사실 is a neutral, verifiable fact ('it rained yesterday'), while 진실 is the deeper moral 'truth' you uncover behind lies, so a courtroom seeks 진실, but a weather report states a 사실. Also distinguish 진짜, which is the casual spoken 'really/for real' and an intensifier ('진짜 맛있어!'), whereas 사실 introduces information. The phrase 사실은 / 사실 at the head of a sentence is enormously common in conversation as a gentle 'to tell the truth' before a correction or confession. The English-speaker pitfall: do not use 사실 to mean 'really' as an intensity word — '진짜 추워요' (it's really cold) is natural, but '사실 추워요' shifts the meaning to 'actually, it's cold (contrary to what you thought)'. Keep 사실 for facts and reveals, not for emphasis."},sentence:{ko:"사실은 제가 먼저 연락했어요.",en:"The truth is, I contacted first."},target:"사실",options:["friend","fact, truth","phone call"],note:"사실은 frames the correction."},{kind:"guess",word:{ko:"다르다",romanization:"dareuda",en:"to be different",pos:"adjective",nuance:"다르다 is the antonym of 같다 and conjugates as a 르-irregular: the stem 다르 + 아요 doubles the ㄹ and drops 으 to give 달라요 (never 다라요); past is 달랐어요. The pre-noun form 다른 is one of the most-used words in Korean and covers both 'different' and 'another' (다른 색 = 'a different/another colour'). The dangerous trap for English speakers is 틀리다, which means 'to be wrong / incorrect' — even native speakers loosely say 틀리다 for 'different' in speech, but in correct Korean 답이 틀리다 = 'the answer is wrong' while 답이 다르다 = 'the answer is different'. Mixing them can imply someone is mistaken when you only meant they differ, which can sound rude. Pair 다르다 with 하고/와 for the thing compared: 작년하고 달라요 ('it's different from last year')."},sentence:{ko:"두 사람은 의견이 달라요.",en:"As for the two people, their opinions are different."},target:"달라",options:["to be different","to be the same","to be easy"],note:"두 사람은 is the frame; 의견이 is the differing subject."},{kind:"guess",word:{ko:"같다",romanization:"gatda",en:"to be the same",pos:"adjective",nuance:"같다 says two or more things match or are identical — 'A and B are the same'. To compare, the yardstick noun takes 하고/와·과 and the matching trait takes 이/가: 저하고 키가 같아요 ('our height is the same as mine'). Watch the sharp split from 비슷하다 ('similar'): 같다 means literally no difference, while 비슷하다 allows a gap — friends who 'look alike but aren't twins' are 비슷하다, not 같다. A second trap is the homophone-feeling N 같다 ('seems like N', as in 학생 같아요 'seems to be a student'), which drops 하고 and shifts meaning entirely; 같이 (together / -like) shares the root but is an adverb. English speakers also over-apply 'the same as' with 처럼 — but 처럼 means 'like/as', not 'identical', so keep 같다 for true equality."},sentence:{ko:"뜻은 같지만 느낌이 달라요.",en:"The meaning is the same, but the feeling is different."},target:"같지",options:["to be different","to be the same","to be easy"],note:"은/는 contrasts meaning and feeling."},{kind:"guess",word:{ko:"쉽다",romanization:"swipda",en:"to be easy",pos:"adjective",nuance:"쉽다 is ㅂ irregular: 쉬워요, 쉬운. It helps learners talk about difficulty level, but the opposite 어렵다 is often needed in the same lesson."},sentence:{ko:"질문은 쉬웠는데 대답이 어려웠어요.",en:"The question was easy, but the answer was difficult."},target:"쉬웠",options:["to be easy","to be different","to be the same"],note:"쉬웠는데 sets up contrast."},{kind:"guess",word:{ko:"중요하다",romanization:"jungyohada",en:"to be important",pos:"adjective",nuance:"중요하다 means 'important, significant, crucial' — carrying weight, mattering a great deal. It is Sino-Korean 重要 (중/重 'heavy' + 요/要 'essential, vital'), a vivid literal image of 'heavy and essential', i.e. weighty and indispensable. The sharp contrast is with 필요하다 ('necessary/needed'): 중요하다 ranks how much something MATTERS in significance, while 필요하다 says something is REQUIRED to get a result — an exam can be 중요한 (it matters a lot) and a pencil 필요한 (you need it to take the test); they are not interchangeable. Also distinguish 소중하다 ('precious, dear'), which is emotional preciousness rather than functional weight. The collocation 중요하게 생각하다 / 중요하게 여기다 means 'to value, to prioritize'. It conjugates regularly (중요해요). English-speaker pitfall: learners blur 'important' and 'necessary' — for 'I need it' use 필요하다, reserving 중요하다 for 'it matters'; and never say 중요하요 (contract to 중요해요)."},sentence:{ko:"이 문제는 이유가 제일 중요해요.",en:"For this issue, the reason is most important."},target:"중요해",options:["to be different","to be important","to be the same"],note:"중요하다 often appears with the focused subject marked by 이/가."},{kind:"payoff",line:{speaker:"지훈",ko:"그럼 이 문제는 이유가 제일 중요하네요.",en:"Then for this issue, the reason is the most important thing."},hl:"이유"}],canDo:"Mark contrast or limited scope with 은/는 (평소에는 …)",id:"chapter-62-b5",chapterId:"chapter-62",index:4},{kind:"pattern",title:"무늬 Pattern · 은/는",cards:[{kind:"hunt",name:"은/는",sub:"contrast and limited scope",lines:[{tokens:[{pre:"형",mid:"은",post:"",hit:!0},{pre:"키가",mid:"",post:"",hit:!1},{pre:"커요.",mid:"",post:"",hit:!1},{pre:"저",mid:"는",post:"",hit:!0},{pre:"작아요.",mid:"",post:"",hit:!1}],ko:"형은 키가 커요. 저는 작아요.",en:"My older brother is tall. I'm short.",romanization:"hyeongeun kiga keoyo. jeoneun jagayo."},{tokens:[{pre:"커피",mid:"는",post:"",hit:!0},{pre:"좋아하는데",mid:"",post:"",hit:!1},{pre:"차",mid:"는",post:"",hit:!0},{pre:"안",mid:"",post:"",hit:!1},{pre:"좋아해요.",mid:"",post:"",hit:!1}],ko:"커피는 좋아하는데 차는 안 좋아해요.",en:"I like coffee but not tea.",romanization:"keopineun joahaneunde chaneun an joahaeyo."}],rule:{name:"은/는",rows:[{when:"contrasting two nouns",add:"both take 은/는",ex:"커피는 마셔요. 차는 안 마셔요."},{when:"attaching contrast to an object",add:"은/는 replaces 을/를",ex:"고기는 안 먹어요. (meat, at least, I don't eat)"},{when:"limiting / 'this one, at least' nuance",add:"noun + 는 with implied 'others differ'",ex:"이건 알아요. (this one I do know — others maybe not)"}]},more:{func:"Beyond topic-setting, 은/는 marks CONTRAST: 'X (but as for something else, it's different).' It quietly implies a comparison, even when the other side is unspoken. Use it to set one item against another, or to limit a statement to just that item.",keyPoint:{label:"는 over 가/를 = contrast is intended",body:"커피를 마셔요 = plain 'I drink coffee.' 커피는 마셔요 = 'Coffee I drink (but something else, no).' Swapping 를→는 (or 가→는) adds an unspoken 'unlike the rest.'"},pronunciation:"In the contrast reading, 는/은 often carries a slight emphatic stress: 저'는 작아요. That extra stress is what flags the contrast aloud."}},{kind:"drill",prompt:"Korean, at least, I can speak.",sentence:"한국어___ 할 수 있어요.",options:[{text:"은",ok:!1},{text:"는",ok:!0}],explanation:"는 here limits the claim to Korean, implying 'other languages, maybe not.'"}],canDo:"Mark contrast or limited scope with 은/는 (평소에는 …)",id:"chapter-62-b6",chapterId:"chapter-62",index:5},{kind:"pattern",title:"무늬 Pattern · 이/가",cards:[{kind:"hunt",name:"이/가",sub:"'this exact one' (exclusive identification)",lines:[{tokens:[{pre:"이",mid:"",post:"",hit:!1},{pre:"사람",mid:"이",post:"",hit:!0},{pre:"제",mid:"",post:"",hit:!1},{pre:"선생님이에요.",mid:"",post:"",hit:!1}],ko:"이 사람이 제 선생님이에요.",en:"THIS person is my teacher.",romanization:"i sarami je seonsaengnimieyo."},{tokens:[{pre:"누",mid:"가",post:"",hit:!0},{pre:"했어요?",mid:"",post:"",hit:!1},{pre:"—",mid:"",post:"",hit:!1},{pre:"제",mid:"가",post:"",hit:!0},{pre:"했어요.",mid:"",post:"",hit:!1}],ko:"누가 했어요? — 제가 했어요.",en:"Who did it? — I did.",romanization:"nuga haesseoyo? — jega haesseoyo."}],rule:{name:"이/가",rows:[{when:"answering with the exact identity",add:"answer + 이/가",ex:"누가 반장이에요? → 민수가 반장이에요."},{when:"'it is X' exclusive focus",add:"X + 이/가 + verb",ex:"이 책이 제일 좋아요. (THIS book is the best.)"},{when:"picking one out of several",add:"chosen item + 이/가",ex:"이게 제 거예요. (THIS one is mine.)"}]},more:{func:"When you single out ONE item as the answer — 'it is THIS one, not the others' — the identified subject takes 이/가. This exclusive-focus use is why 이/가 (not 은/는) appears in answers, in 'who/what' replies, and in 'it's X that…' sentences. It pins down the exact one.",keyPoint:{label:"이/가 identifies, 은/는 describes",body:"이 사람이 김 선생님이에요 = 'THIS (one) is Mr. Kim' (picks him out). 이 사람은 김 선생님이에요 = 'As for this person, he's Mr. Kim' (just tells you about him). Use 이/가 to single out the exact one."},pronunciation:"이것이 commonly contracts to 이게, 그것이 → 그게, 저것이 → 저게 in speech. Learn the contracted 이게/그게/저게 as the everyday spoken forms."}},{kind:"drill",prompt:"Which bag do you like?",sentence:"어느 가방___ 마음에 들어요?",options:[{text:"이",ok:!0},{text:"가",ok:!1}],explanation:"어느 (which) forces a one-out-of-many choice, so the subject takes 이."}],canDo:"Combine topic and inner subject in one sentence (N은/는 N이/가 …)",id:"chapter-62-b7",chapterId:"chapter-62",index:6},{kind:"pattern",title:"무늬 Pattern · N은/는 N이/가 …",cards:[{kind:"teach",name:"N은/는 N이/가 …",sub:"topic + inner subject in one sentence",rows:[{when:"describing a body part / trait",add:"Topic은/는 + part이/가 + adj",ex:"코끼리는 코가 길어요. (The elephant's nose is long.)"},{when:"saying what someone likes/has",add:"Person은/는 + thing이/가 + 좋다/있다",ex:"저는 강아지가 좋아요. (As for me, I like dogs.)"},{when:"stating an ability/condition",add:"Topic은/는 + thing이/가 + 어렵다/많다",ex:"한국어는 발음이 어려워요. (Korean — its pronunciation is hard.)"}],examples:[{ko:"코끼리는 코가 길어요.",en:"An elephant's nose is long.",romanization:"kokkiri-neun ko-ga gireoyo.",note:"코끼리 is the topic (은/는); 코 is the inner subject (이/가) that 길어요 actually describes."},{ko:"저는 시간이 없어요.",en:"I don't have time.",romanization:"jeoneun sigani eopseoyo.",note:"Literally 'As for me, time doesn't exist.' 저 = topic (는), 시간 = subject of 없다 (이)."}],more:{func:"Korean often uses BOTH markers in a single sentence: 은/는 names the big-picture topic, then 이/가 names the specific thing the comment is really about. Pattern: '[Topic]은/는 [inner subject]이/가 [adjective/verb].' This is the natural way to describe a part, trait, or condition of something — 'As for the elephant, its nose is long.'",keyPoint:{label:"One topic (은/는), one inner subject (이/가)",body:"Don't pile two 은/는 or two 이/가. The big thing you're talking about takes 은/는; the specific thing the predicate describes takes 이/가. 저는 머리가 아파요 = 'I have a headache' (me = topic, head = what hurts)."},pronunciation:"코가 = ko-ga (smooth, no stop); 키가 = ki-ga; 시간이 = sigani (final ㄴ links onto 이). Keep both syllables of 이/가 light — the stress sits on the predicate (길어요, 커요)."}}],canDo:"Spotlight a new or focused subject with 이/가 (친구가 보냈어요)",id:"chapter-62-b8",chapterId:"chapter-62",index:7},{kind:"dialogue",title:"대화 Dialogue · 진짜 한국어",cards:[{kind:"chat",setting:"Two friends analyze a call and a message while the particles track new information, topic, contrast, and focus.",lines:[{speaker:"민서",ko:"어제 친구가 전화했어요.",en:"A friend called yesterday.",romanization:"eoje chinguga jeonhwahaesseoyo."},{speaker:"지훈",ko:"그 친구는 자주 전화해요?",en:"Does that friend call often?",romanization:"geu chinguneun jaju jeonhwahaeyo?"},{speaker:"민서",ko:"아니요. 평소에는 메시지를 보내는데 오늘은 제가 먼저 연락했어요.",en:"No. Usually they send messages, but today I contacted them first.",romanization:"aniyo. pyeongsoeneun mesijireul bonaeneunde oneureun jega meonjeo yeollakaesseoyo."},{speaker:"지훈",ko:"누가 먼저 연락했어요?",en:"Who contacted first?",romanization:"nuga meonjeo yeollakaesseoyo?"},{speaker:"민서",ko:"제가 먼저 연락했어요. 질문은 쉬웠는데 대답이 어려웠어요.",en:"I contacted first. The question was easy, but the answer was difficult.",romanization:"jega meonjeo yeollakaesseoyo. jilmuneun swiwonneunde daedabi eoryeowosseoyo."},{speaker:"지훈",ko:"그럼 이 문제는 이유가 제일 중요하네요.",en:"Then for this issue, the reason is the most important thing.",romanization:"geureom i munjeneun iyuga jeil jungyohaneyo."}]},{kind:"order",prompt:"Build: 'My friend called first.'",tokens:["친구가","먼저 전화했어요"],correct:"친구가 먼저 전화했어요",explanation:"When answering 누가 first acted, the focused subject takes 가. 먼저 tells who acted first."}],canDo:"Spotlight a new or focused subject with 이/가 (친구가 보냈어요)",id:"chapter-62-b9",chapterId:"chapter-62",index:8},{kind:"reading",title:"읽기 Reading · ‘친구가’에서 ‘그 친구는’으로",cards:[{kind:"read",title:"‘친구가’에서 ‘그 친구는’으로",chunks:['어제 민서에게 친구가 전화했다. 처음 말할 때는 누가 전화했는지가 새 정보였기 때문에 ‘친구가’가 자연스러웠다. 그다음 지훈은 "그 친구는 자주 전화해?"라고 물었다. 이미 말한 친구를 다시 주제로 삼았기 때문에 ‘그 친구는’이 맞았다. 민서는 평소에는 메시지를 보내는데 오늘은 제가 먼저 연락했다고 설명했다.','여기서 ‘평소에는’과 ‘오늘은’은 서로 대비된다. 지훈이 "누가 먼저 연락했어?"라고 묻자 민서는 "제가 먼저 연락했어"라고 답했다. ‘제가’는 다른 사람이 아니라 바로 민서가 했다는 뜻이다. 마지막으로 "이 문제는 이유가 중요해"처럼 말하면, 문제는 이야기의 틀이고 이유가 그 안에서 중요한 새 정보가 된다.'],translation:'Yesterday, a friend called Minseo. On the first mention, who called was new information, so 친구가 was natural. Then Jihoon asked, "Does that friend call often?" Because the friend had already been mentioned and was now the topic, 그 친구는 was right. Minseo explained that usually the friend sends messages, but today she contacted first. Here 평소에는 and 오늘은 contrast with each other. When Jihoon asked, "Who contacted first?" Minseo answered, "I contacted first." 제가 means it was specifically Minseo, not someone else. Finally, in a sentence like "For this issue, the reason is important," 문제는 is the frame of the discussion and 이유가 is the important new information inside it.',qas:[{q:"처음에는 왜 친구가를 썼어요?",a:"누가 전화했는지가 새 정보였기 때문이에요."},{q:"‘평소에는’과 ‘오늘은’은 어떤 역할을 해요?",a:"평소와 오늘을 서로 대비해요."},{q:"이 문제는 이유가 중요해요에서 문제와 이유의 역할은 무엇이에요?",a:"문제는 이야기의 틀이고, 이유가 그 안에서 중요한 새 정보예요."}]}],canDo:"Set up an already-known topic with 은/는 (저는 …, 그 친구는 …)",id:"chapter-62-b10",chapterId:"chapter-62",index:9},{kind:"boss",title:"보스 Boss bite · 다 걸어요",cards:[{kind:"drill",prompt:"Which sentence introduces the caller as new information?",sentence:null,options:[{text:"친구가 전화했어요.",ok:!0},{text:"친구는 전화했어요.",ok:!1},{text:"친구에게 전화했어요.",ok:!1}],explanation:"친구가 answers who called."},{kind:"drill",prompt:"Which sentence contrasts messages and calls?",sentence:null,options:[{text:"메시지는 자주 보내지만 전화는 잘 안 해요.",ok:!0},{text:"메시지가 자주 보내지만 전화가 잘 안 해요.",ok:!1},{text:"메시지에게 자주 보내지만 전화에게 안 해요.",ok:!1}],explanation:"은/는 marks the two contrasted communication methods."},{kind:"drill",prompt:"Which answer fits 누가 먼저 연락했어요?",sentence:null,options:[{text:"제가 먼저 연락했어요.",ok:!0},{text:"저는 먼저 연락했어요.",ok:!1},{text:"저에게 먼저 연락했어요.",ok:!1}],explanation:"제가 gives the focused who-answer."},{kind:"drill",prompt:"Which particles complete the topic-plus-subject sentence: 이 문제____ 이유____ 중요해요?",sentence:null,options:[{text:"는 / 가",ok:!0},{text:"가 / 는",ok:!1},{text:"에게 / 를",ok:!1}],explanation:"이 문제는 sets the frame; 이유가 is the important subject inside it."},{kind:"drill",prompt:"이 문제___ 이유___ 중요해요. (As for this problem, the reason is important.)",sentence:null,options:[{text:"는 / 가",ok:!0},{text:"가 / 는",ok:!1},{text:"를 / 이",ok:!1}],explanation:"The outer topic is 이 문제는, and the inner subject is 이유가. This topic-plus-subject structure is common in Korean."},{kind:"order",prompt:"Build: 'My friend called first.'",tokens:["친구가","먼저 전화했어요"],correct:"친구가 먼저 전화했어요",explanation:"When answering 누가 first acted, the focused subject takes 가. 먼저 tells who acted first."},{kind:"drill",prompt:"Which sentence introduces the caller as new information?",sentence:null,options:[{text:"친구가 전화했어요.",ok:!0},{text:"친구는 전화했어요.",ok:!1},{text:"친구를 전화했어요.",ok:!1}],explanation:"New or focused subject information uses 이/가. 은/는 would frame or contrast the friend."}],canDo:"Mark contrast or limited scope with 은/는 (평소에는 …)",id:"chapter-62-b11",chapterId:"chapter-62",index:10}]},{id:"chapter-63",number:63,title:"따라서 / 그러므로 · 그러나 / 반면에 / 한편",goal:"Choose formal connectors according to sentence relationship, not English translation.",biteCount:10,bites:[{kind:"words",title:"단어 Words 1 · 근거~",cards:[{kind:"guess",word:{ko:"근거",romanization:"geungeo",en:"evidence; grounds; basis",pos:"noun",nuance:"근거 is broader than 증거; 증거 often means proof/evidence, while 근거 can mean the basis for reasoning."},sentence:{ko:"주장을 뒷받침할 근거를 제시해야 한다.",en:"Evidence that supports the claim must be presented."},target:"근거",options:["conclusion","core; key point","evidence; grounds; basis"],note:"Use 근거 when a claim needs support, not merely a reason."},{kind:"guess",word:{ko:"결론",romanization:"gyeollon",en:"conclusion",pos:"noun",nuance:"결론 is the end point of reasoning, not simply the ending of a story."},sentence:{ko:"근거가 약하면 결론도 설득력을 잃는다.",en:"If the evidence is weak, the conclusion also loses persuasiveness."},target:"결론",options:["conclusion","evidence; grounds; basis","core; key point"],note:"결론 is the endpoint of reasoning, not a story ending."},{kind:"guess",word:{ko:"핵심",romanization:"haeksim",en:"core; key point",pos:"noun",nuance:"핵심 is more formal and analytical than 중요한 부분."},sentence:{ko:"이 글의 핵심은 비용 문제가 아니라 안전 문제이다.",en:"The key point of this piece is not cost but safety."},target:"핵심",options:["evidence; grounds; basis","conclusion","core; key point"],note:"핵심 narrows attention to the central issue."},{kind:"guess",word:{ko:"논리",romanization:"nolli",en:"logic; reasoning",pos:"noun",nuance:"논리 is the structure of reasoning, not simply an opinion."},sentence:{ko:"주장은 분명하지만 논리에 비약이 있다.",en:"The claim is clear, but there is a leap in the reasoning."},target:"논리",options:["logic; reasoning","evidence; grounds; basis","conclusion"],note:"Say 논리에 비약이 있다, not 논리가 비약하다."},{kind:"guess",word:{ko:"사례",romanization:"sarye",en:"case; example",pos:"noun",nuance:"사례 is more formal than 예 and often implies a real case or representative example."},sentence:{ko:"주장을 뒷받침하려면 구체적인 사례를 제시해야 한다.",en:"To support a claim, concrete cases must be presented."},target:"사례",options:["case; example","evidence; grounds; basis","conclusion"],note:"사례 is more formal and analytical than 예."},{kind:"guess",word:{ko:"반론",romanization:"ballon",en:"counterargument; objection",pos:"noun",nuance:"반론 is an argument against a claim; 반대 is broader opposition."},sentence:{ko:"그러나 예상되는 반론도 검토해야 한다.",en:"However, expected counterarguments must also be reviewed."},target:"반론",options:["evidence; grounds; basis","counterargument; objection","conclusion"],note:"A strong formal paragraph anticipates objections."},{kind:"payoff",line:{speaker:"민서",ko:"이 보고서는 근거가 부족합니다.",en:"This report lacks evidence."},hl:"근거"}],canDo:"Draw a conclusion in formal writing with 따라서 / 그러므로 (따라서 …다)",id:"chapter-63-b1",chapterId:"chapter-63",index:0},{kind:"pattern",title:"무늬 Pattern · 따라서 / 그러므로",cards:[{kind:"hunt",name:"따라서 / 그러므로",sub:"Therefore (evidence to conclusion)",lines:[{tokens:[{pre:"이",mid:"",post:"",hit:!1},{pre:"보고서는",mid:"",post:"",hit:!1},{pre:"근거가",mid:"",post:"",hit:!1},{pre:"부족하다.",mid:"",post:"",hit:!1},{pre:"",mid:"따라서",post:"",hit:!0},{pre:"결론을",mid:"",post:"",hit:!1},{pre:"다시",mid:"",post:"",hit:!1},{pre:"검토해야",mid:"",post:"",hit:!1},{pre:"한다.",mid:"",post:"",hit:!1}],ko:"이 보고서는 근거가 부족하다. 따라서 결론을 다시 검토해야 한다.",en:"This report lacks evidence. Therefore the conclusion must be reviewed again.",romanization:"i bogoseoneun geungeoga bujokhada. ttaraseo gyeolloneul dasi geomtohaeya handa."},{tokens:[{pre:"자료의",mid:"",post:"",hit:!1},{pre:"출처가",mid:"",post:"",hit:!1},{pre:"분명하지",mid:"",post:"",hit:!1},{pre:"않다.",mid:"",post:"",hit:!1},{pre:"",mid:"그러므로",post:"",hit:!0},{pre:"핵심",mid:"",post:"",hit:!1},{pre:"근거로",mid:"",post:"",hit:!1},{pre:"쓰기",mid:"",post:"",hit:!1},{pre:"어렵다.",mid:"",post:"",hit:!1}],ko:"자료의 출처가 분명하지 않다. 그러므로 핵심 근거로 쓰기 어렵다.",en:"The source of the material is unclear. Thus it is hard to use as key evidence.",romanization:"jaryoui chulcheoga bunmyeonghaji anta. geureomeuro haeksim geungeoro sseugi eoryeopda."}],rule:{name:"따라서 / 그러므로",rows:[{when:"Evidence stated, you give the result (most neutral, the everyday choice in reports and essays)",add:"따라서",ex:"근거가 부족하다. 따라서 결론을 다시 검토해야 한다."},{when:"A more deductive 'thus, it follows that'; slightly weightier, common in arguments",add:"그러므로",ex:"누구나 실수를 한다. 그러므로 검토가 필요하다."},{when:"The casual spoken version you REPLACE in formal writing (shown for contrast)",add:"그래서 (avoid in essays)",ex:"비가 와서 안 갔어 → 비가 왔다. 따라서 가지 않았다."}]},more:{func:"These are the written-register connectors for drawing a logical conclusion from what you just said. They mark the jump from a reason or premise to its result, the way English uses 'therefore.' In conversation Koreans say 그래서, but in essays, reports, and articles they switch to 따라서 or 그러므로. Both open a new sentence.",keyPoint:{label:"따라서 vs 그러므로",body:"Both mean 'therefore' and both are formal. 따라서 is the everyday workhorse of reports and essays — neutral and safe. 그러므로 feels a notch more deductive ('it necessarily follows'), so it shines in arguments and reasoning. In ordinary expository writing, default to 따라서; reach for 그러므로 when you want the logic to feel airtight."},pronunciation:"따라서 starts with a tense ㄸ: [tta-ra-seo]. 그러므로 is four light, even syllables [geu-reo-meu-ro] with no tense consonants — don't stress it like English 'therefore.'"}}],canDo:"Draw a conclusion in formal writing with 따라서 / 그러므로 (따라서 …다)",id:"chapter-63-b2",chapterId:"chapter-63",index:1},{kind:"words",title:"단어 Words 2 · 따라서~",cards:[{kind:"guess",word:{ko:"따라서",romanization:"ttaraseo",en:"therefore; accordingly",pos:"adverb",nuance:"따라서 means 'therefore / accordingly / thus' and is the formal, logical 'so' of reports, public notices, instructions, contracts, and academic writing. It states a conclusion that follows STRICTLY and objectively from the prior statement, with a more official, impersonal tone than either 그래서 (plain spoken 'so') or 그러니까 (reasoning/urging 'so'). The dividing line: 그래서 and 그러니까 belong to everyday speech and can carry personal feeling or persuasion, whereas 따라서 is detached and rule-like, so in casual conversation it sounds like you're reading a press release. It pairs naturally with the formal -ㅂ니다 ending and with 다음과 같이 ('as follows'). The classic English-speaker trap is mixing this connector up with the homograph verb form 따라서 from 따르다 ('to follow') — as in 규칙을 따라서 ('following the rule'). The connector stands ALONE at the head of a sentence with no object; the verb form has something being followed in front of it."},sentence:{ko:"자료의 출처가 분명하지 않다. 따라서 핵심 근거로 사용하기 어렵다.",en:"The source of the material is unclear. Therefore, it is difficult to use as key evidence."},target:"따라서",options:["however; but","therefore; accordingly","by contrast; whereas"],note:"따라서 connects evidence to a formal consequence."},{kind:"guess",word:{ko:"그러나",romanization:"geureona",en:"however; but",pos:"adverb",nuance:"그러나 means 'however' and is the formal, written-register cousin of 하지만 and 그렇지만. Its dividing line from those: 하지만 is the neutral all-purpose 'but' that works in speech and writing, while 그러나 feels distinctly literary and shows up in news articles, reports, essays, editorials, and official notices; in casual chat it sounds stiff, where 근데 or 하지만 fit far better. A second crucial point for English speakers: 그러나 almost always STARTS a fresh sentence and does not glue two clauses together inside one sentence. English 'but' can sit mid-sentence ('I tried, but I failed'), so learners wrongly write 시도했어요 그러나 실패했어요; correct Korean either puts 그러나 after a full stop or uses the clause-internal ending -지만 (시도했지만 실패했어요). Treat 그러나 as a heading-level pivot, not an inline conjunction."},sentence:{ko:"핵심 주장은 분명하다. 그러나 근거가 부족하다.",en:"The main claim is clear. However, the evidence is insufficient."},target:"그러나",options:["however; but","therefore; accordingly","by contrast; whereas"],note:"그러나 gives a direct formal contrast."},{kind:"guess",word:{ko:"반면에",romanization:"banmyeone",en:"by contrast; whereas",pos:"adverb",nuance:"반면에 means 'on the other hand / whereas / by contrast' and explicitly sets two distinct sides, options, or qualities against each other. It comes from the Sino-Korean noun 반면 (反面, literally 'opposite + face/side,' i.e. 'the reverse side') plus the location particle 에 — so its very composition is 'on the opposite side,' which is why it demands a clear A and a clear B to weigh. This is its dividing line from 그런데/근데: those handle a single-topic surprise or twist ('I went out, but it was closed'), whereas 반면에 is analytical and comparative, ideal for pros-and-cons and 'A is X, B is Y' contrasts. It also differs from 한편 in being a sharper head-to-head contrast rather than a loose scene-shift. Note it has two shapes: as a free adverb starting a sentence (반면에 단점도 있어요) and as a bound clause ending -는/은 반면에 attached to the previous verb/adjective (비싼 반면에 'while it's expensive'). The English-speaker pitfall is dropping it onto a one-sided remark where there's no real B to contrast — without two sides, 반면에 has nothing to balance and sounds incomplete."},sentence:{ko:"첫 번째 사례는 적절하다. 반면에 두 번째 사례는 관련성이 약하다.",en:"The first case is appropriate. By contrast, the second case is weakly relevant."},target:"반면에",options:["therefore; accordingly","however; but","by contrast; whereas"],note:"반면에 compares two sides."},{kind:"guess",word:{ko:"즉",romanization:"jeuk",en:"that is; in other words",pos:"adverb",nuance:"즉 means 'that is / in other words / namely' and introduces a RESTATEMENT or precise clarification of what you just said — never new information, only the same point re-expressed more sharply or simply. It is a single Sino-Korean syllable from the hanja 卽 ('namely, that is to say'), and that one-syllable crispness gives it a slightly formal, definitional ring that suits writing, explanations, legal/technical text, and definitions. The contrast to watch: do not confuse 즉 with 그리고 ('and'), which ADDS a separate item; 즉 re-explains, so if what follows is genuinely new content, 즉 is wrong. It overlaps heavily with 다시 말해 ('in other words'), but 즉 is terser and more bookish while 다시 말해 feels more conversational. Punctuation-wise it almost always takes a comma right after it (즉,) and pairs naturally with the nominalizing tails ...라는 거예요 / ...뜻이에요. In very casual chat it can feel clipped, where 그러니까 or 말하자면 sound friendlier."},sentence:{ko:"문제는 결론 자체가 아니다. 즉, 근거와 논리의 연결이 약하다는 점이다.",en:"The problem is not the conclusion itself. In other words, the link between evidence and reasoning is weak."},target:"즉",options:["that is; in other words","therefore; accordingly","however; but"],note:"즉 clarifies the same point in a narrower form."},{kind:"guess",word:{ko:"결국",romanization:"gyeolguk",en:"ultimately; in the end",pos:"adverb",nuance:"결국 means 'in the end / eventually / after all' and sums up the FINAL outcome reached after a process, delay, or struggle. It is Sino-Korean, 결 (結, 'to conclude/tie up') + 국 (局, 'situation/end stage'), literally 'the concluding stage' — so it inherently looks back over a whole drawn-out affair to its settling point. The dividing line from near-synonym 드디어 is important: 드디어 celebrates a happy, long-awaited result with relief and excitement ('finally, at last!'), whereas 결국 is emotionally NEUTRAL and frequently tinged with resignation or a sense that the outcome was inevitable ('it came to this after all'). A second contrast English speakers stumble on: 결국 is NOT the 'finally/lastly' that orders items in a list — that ordinal sense ('firstly... finally...') is 마지막으로. 결국 is about how a story RESOLVED, not where an item sits in a sequence. It commonly follows a lead-in clause with -지만 or -는데 sketching the struggle, and the variant 결국엔 (with topic 은) adds extra weight to the final beat."},sentence:{ko:"결국 좋은 보고서는 주장, 근거, 사례가 서로 연결되어야 한다.",en:"Ultimately, a good report requires its claim, evidence, and cases to be connected."},target:"결국",options:["ultimately; in the end","therefore; accordingly","however; but"],note:"결국 summarizes what the whole discussion leads to."},{kind:"payoff",line:{speaker:"지훈",ko:"따라서 결론을 다시 검토해야 합니다.",en:"Therefore, the conclusion must be reviewed again."},hl:"따라서"}],canDo:"Distinguish three kinds of contrast with 그러나 / 반면에 / 한편",id:"chapter-63-b3",chapterId:"chapter-63",index:2},{kind:"pattern",title:"무늬 Pattern · 그러나 / 반면에 / 한편",cards:[{kind:"hunt",name:"그러나 / 반면에 / 한편",sub:"three kinds of contrast",lines:[{tokens:[{pre:"핵심",mid:"",post:"",hit:!1},{pre:"주장은",mid:"",post:"",hit:!1},{pre:"분명하다.",mid:"",post:"",hit:!1},{pre:"",mid:"그러나",post:"",hit:!0},{pre:"이를",mid:"",post:"",hit:!1},{pre:"뒷받침할",mid:"",post:"",hit:!1},{pre:"근거가",mid:"",post:"",hit:!1},{pre:"부족하다.",mid:"",post:"",hit:!1}],ko:"핵심 주장은 분명하다. 그러나 이를 뒷받침할 근거가 부족하다.",en:"The main claim is clear. However, the evidence to support it is insufficient.",romanization:"haeksim jujangeun bunmyeonghada. geureona ireul dwitbatchimhal geungeoga bujokhada."},{tokens:[{pre:"첫",mid:"",post:"",hit:!1},{pre:"번째",mid:"",post:"",hit:!1},{pre:"사례는",mid:"",post:"",hit:!1},{pre:"적절하다.",mid:"",post:"",hit:!1},{pre:"",mid:"반면에",post:"",hit:!0},{pre:"두",mid:"",post:"",hit:!1},{pre:"번째",mid:"",post:"",hit:!1},{pre:"사례는",mid:"",post:"",hit:!1},{pre:"관련성이",mid:"",post:"",hit:!1},{pre:"약하다.",mid:"",post:"",hit:!1}],ko:"첫 번째 사례는 적절하다. 반면에 두 번째 사례는 관련성이 약하다.",en:"The first case is fitting. By contrast, the second case is weakly relevant.",romanization:"cheot beonjjae saryeneun jeokjeolhada. banmyeone du beonjjae saryeneun gwallyeonseongi yakada."}],rule:{name:"그러나 / 반면에 / 한편",rows:[{when:"Direct reversal or limitation of the previous claim — the strong written 'however'",add:"그러나",ex:"핵심 주장은 분명하다. 그러나 근거가 부족하다."},{when:"Comparing two items as contrasting opposites; often after stating side A",add:"반면(에)",ex:"첫 사례는 적절하다. 반면에 두 번째 사례는 약하다."},{when:"Adding a separate, co-occurring angle or new actor — not a contradiction",add:"한편",ex:"보고서는 비용을 강조한다. 한편 안전 검토는 부족하다."}]},more:{func:"Formal writing splits into three the contrast that casual 하지만 lumps together. 그러나 directly reverses or limits what you just said ('however'). 반면에 sets two things side by side as opposites ('by contrast, whereas'). 한편 moves to a separate, co-occurring point ('meanwhile, for its part') without contradicting. Picking the right one is a mark of polished writing.",keyPoint:{label:"그러나 vs 반면에 vs 한편",body:"Test by relationship: if B cancels or limits A, use 그러나 (however). If B is the mirror-opposite of A, weighed against it, use 반면에 (by contrast). If B is just a separate development from another side, use 한편 (meanwhile). A common error is using 한편 where 반면에 is needed — 한편 does NOT mean 'in contrast,' it means 'from another quarter, at the same time.'"},pronunciation:"반면에 is [ban-myeo-ne] — the ㄴ of 면 links into 에, so it flows as one word, not 반/면/에 chopped apart. 한편 is [han-pyeon]."}},{kind:"drill",prompt:"The report stresses the cost issue. Meanwhile, the review of safety is not sufficient.",sentence:"보고서는 비용 문제를 강조한다. ___ 안전 문제 검토는 충분하지 않다.",options:[{text:"그러나",ok:!1},{text:"반면에",ok:!1},{text:"한편",ok:!0}],explanation:"한편 shifts to a separate line of discussion, not a flat contradiction."}],canDo:"Distinguish three kinds of contrast with 그러나 / 반면에 / 한편",id:"chapter-63-b4",chapterId:"chapter-63",index:3},{kind:"pattern",title:"무늬 Pattern · 즉 / 다시 말해서",cards:[{kind:"teach",name:"즉 / 다시 말해서",sub:"that is, in other words (restate, don't add)",rows:[{when:"Pinpointing an exact equivalent or narrower meaning — terse, very written 'namely, that is'",add:"즉",ex:"핵심 변수, 즉 가격이 결과를 좌우한다."},{when:"Rephrasing the whole idea in plainer words for the reader",add:"다시 말해서",ex:"수요가 공급을 넘었다. 다시 말해서, 물건이 부족하다."},{when:"Shorter written variant of 다시 말해서, often before a clause",add:"다시 말해",ex:"비용이 효용을 넘는다. 다시 말해 손해다."}],examples:[{ko:"문제는 결론 자체가 아니다. 즉, 근거와 논리의 연결이 약하다는 점이다.",en:"The problem is not the conclusion itself. That is, the link between evidence and reasoning is weak.",romanization:"munjeneun gyeollon jachega anida. jeuk, geungeowa nolliui yeongyeori yakadaneun jeomida.",note:"즉 restates the diagnosis in a more precise form, adding no new fact."},{ko:"이 문장은 너무 추상적이다. 다시 말해서, 독자가 떠올릴 사례가 없다.",en:"This sentence is too abstract. In other words, there is no example the reader can picture.",romanization:"i munjangeun neomu chusangjeogida. dasi malhaeseo, dokjaga tteoolril saryega eopda.",note:"다시 말해서 reframes the abstract point in concrete, plainer terms."}],more:{func:"These connectors signal that what follows is a RESTATEMENT or clarification of what you just said — not new information. 즉 is a compact written 'namely, that is,' used to pin down a precise equivalent or definition. 다시 말해서 ('to put it again, in other words') reframes the whole idea in plainer words. Both tell the reader: same point, said more clearly.",keyPoint:{label:"즉 vs 다시 말해서",body:"즉 is for a tight, near-mathematical equivalence ('X, namely Y') and often sits INSIDE a sentence right after the term it defines. 다시 말해서 is for rephrasing a whole idea more accessibly and usually starts a fresh sentence. Rule of thumb: 즉 swaps in a precise synonym; 다시 말해서 explains the same point again in different words. Neither one introduces new evidence — for that, use 또한 or 예를 들어."},pronunciation:"즉 is one tight syllable [jeuk], ending in a hard ㄱ stop. 다시 말해서 is [da-si mal-hae-seo], even and unstressed."}}],canDo:"Restate without adding new information using 즉 / 다시 말해서 (즉, …이다)",id:"chapter-63-b5",chapterId:"chapter-63",index:4},{kind:"pattern",title:"무늬 Pattern · 결국 / 궁극적으로",cards:[{kind:"hunt",name:"결국 / 궁극적으로",sub:"final synthesis (what it all comes to)",lines:[{tokens:[{pre:"",mid:"결국",post:"",hit:!0},{pre:"이",mid:"",post:"",hit:!1},{pre:"보고서의",mid:"",post:"",hit:!1},{pre:"핵심은",mid:"",post:"",hit:!1},{pre:"결론을",mid:"",post:"",hit:!1},{pre:"바꾸는",mid:"",post:"",hit:!1},{pre:"것이",mid:"",post:"",hit:!1},{pre:"아니라",mid:"",post:"",hit:!1},{pre:"근거를",mid:"",post:"",hit:!1},{pre:"보완하는",mid:"",post:"",hit:!1},{pre:"것이다.",mid:"",post:"",hit:!1}],ko:"결국 이 보고서의 핵심은 결론을 바꾸는 것이 아니라 근거를 보완하는 것이다.",en:"Ultimately, the key point of this report is not to change the conclusion but to strengthen the evidence.",romanization:"gyeolguk i bogoseoui haeksimeun gyeolloneul bakkuneun geosi anira geungeoreul bowanhaneun geosida."},{tokens:[{pre:"",mid:"궁극적으로",post:"",hit:!0},{pre:"좋은",mid:"",post:"",hit:!1},{pre:"글은",mid:"",post:"",hit:!1},{pre:"주장,",mid:"",post:"",hit:!1},{pre:"근거,",mid:"",post:"",hit:!1},{pre:"반론이",mid:"",post:"",hit:!1},{pre:"서로",mid:"",post:"",hit:!1},{pre:"연결되어야",mid:"",post:"",hit:!1},{pre:"한다.",mid:"",post:"",hit:!1}],ko:"궁극적으로 좋은 글은 주장, 근거, 반론이 서로 연결되어야 한다.",en:"Ultimately, good writing requires the claim, evidence, and counterargument to connect.",romanization:"gunggeukjeogeuro joeun geureun jujang, geungeo, balloni seoro yeongyeoldoeeoya handa."}],rule:{name:"결국 / 궁극적으로",rows:[{when:"Summing up the result after a process or chain of points",add:"결국",ex:"여러 자료를 검토했지만 결국 같은 결론에 도달했다."},{when:"Stating the deepest, most general principle behind it all",add:"궁극적으로",ex:"궁극적으로 좋은 글은 주장과 근거가 연결되어야 한다."},{when:"Marking an awaited event that finally happens (NOT synthesis — contrast only)",add:"드디어 (different meaning)",ex:"드디어 보고서를 제출했다. (at last — not a conclusion)"}]},more:{func:"These pull a chain of reasoning together and name the final point. 결국 means 'in the end, ultimately' — the result or conclusion reached after a process. 궁극적으로 is 'ultimately, fundamentally,' a touch more abstract and principle-like. They are not just 'finally' (which only marks the last item in time); they answer what everything has been leading to.",keyPoint:{label:"결국 vs 궁극적으로 vs 드디어",body:"결국 names the result a process arrives at ('in the end'). 궁극적으로 names the deepest principle behind everything ('fundamentally, ultimately'), so it fits broad closing statements. Neither is 드디어, which only means an awaited event 'finally' happened — a time word, not a synthesis. Save 결국/궁극적으로 for a real summary; don't open every paragraph with them."},pronunciation:"결국 is [gyeol-guk], two syllables both ending in a hard stop. 궁극적으로 is [gung-geuk-jeo-geu-ro], five even syllables — keep it steady, don't rush the middle."}},{kind:"drill",prompt:"Several sources were reviewed, but in the end they reached the same conclusion.",sentence:"여러 자료를 검토했지만 ___ 같은 결론에 도달했다.",options:[{text:"결국",ok:!0},{text:"궁극적으로",ok:!1}],explanation:"결국 marks the final result after the process of reviewing."}],canDo:"Keep a consistent written register with -다 / -ㄴ다·-는다 / -이다 endings (and 결국/궁극적으로 to synthesize)",id:"chapter-63-b6",chapterId:"chapter-63",index:5},{kind:"pattern",title:"무늬 Pattern · Written endings",cards:[{kind:"teach",name:"Written endings",sub:"-다 / -ㄴ다·-는다 / -이다",rows:[{when:"Adjective or descriptive verb (the plain dictionary -다 carries the written meaning)",add:"-다",ex:"이 글은 사례가 부족하다."},{when:"Action verb in expository prose — vowel stem +-ㄴ다, consonant stem +-는다",add:"-ㄴ다 / -는다",ex:"필자는 비용 문제를 강조한다. / 자료를 충분히 다루지 않는다."},{when:"Noun or pronoun statement (copula)",add:"-이다",ex:"핵심은 자료의 양이 아니라 관련성이다."}],examples:[{ko:"이 글은 사례가 부족하다. 따라서 설득력이 약하다.",en:"This piece lacks examples. Therefore it is not very persuasive.",romanization:"i geureun saryega bujokhada. ttaraseo seoldeungnyeogi yakada.",note:"Both sentences keep the plain written -다 on adjectives."},{ko:"필자는 비용 문제를 강조한다. 그러나 안전 문제는 충분히 다루지 않는다.",en:"The writer stresses cost. However, the safety issue is not treated sufficiently.",romanization:"piljaneun biyong munjereul gangjohanda. geureona anjeon munjeneun chungbunhi daruji anneunda.",note:"Action verbs in formal writing take -ㄴ다/-는다, not -해요."}],more:{func:"Formal connectors need formal endings around them. If a paragraph uses 따라서 but then ends every sentence in -해요, the logic sounds written but the voice sounds conversational. In expository Korean (essays, reports, articles) you use the plain written style: adjectives and the copula in -다, action verbs in -ㄴ다/-는다, and noun statements in -이다. This is the register that pairs with the connectors in this chapter.",keyPoint:{label:"One register per paragraph",body:"Decide the register first, then keep it. Expository writing uses the plain written style: adjectives/copula in -다·-이다 and action verbs in -ㄴ다/-는다. -습니다 is also formal and fits presentations and polite reports — but pick one. Mixing -해요 with academic connectors like 따라서 and 즉 makes a single paragraph feel stylistically uneven, even when every word is correct."},pronunciation:"-ㄴ다/-는다 endings end on a clean -다 [da]; don't soften them toward the spoken -다아. -이다 is [i-da], the 이 fully voiced after a consonant."}}],canDo:"Draw a conclusion in formal writing with 따라서 / 그러므로 (따라서 …다)",id:"chapter-63-b7",chapterId:"chapter-63",index:6},{kind:"dialogue",title:"대화 Dialogue · 진짜 한국어",cards:[{kind:"chat",setting:"Two classmates are revising a Korean report draft before submission.",lines:[{speaker:"민서",ko:"이 보고서는 근거가 부족합니다.",en:"This report lacks evidence.",romanization:"i bogoseoneun geungeoga bujokhamnida."},{speaker:"지훈",ko:"따라서 결론을 다시 검토해야 합니다.",en:"Therefore, the conclusion must be reviewed again.",romanization:"ttaraseo gyeolloneul dasi geomtohaeya hamnida."},{speaker:"민서",ko:"그러나 핵심 주장은 유지할 수 있습니다.",en:"However, the main claim can be maintained.",romanization:"geureona haeksim jujangeun yujihal su itseumnida."},{speaker:"지훈",ko:"반면에 사례 분석은 보완이 필요합니다.",en:"By contrast, the case analysis needs strengthening.",romanization:"banmyeone sarye bunseogeun bowani piryohamnida."},{speaker:"민서",ko:"한편 예상되는 반론도 따로 검토해야 합니다.",en:"Meanwhile, the expected counterarguments also need to be reviewed separately.",romanization:"hanpyeon yesangdoeneun ballondo ttaro geomtohaeya hamnida."},{speaker:"지훈",ko:"즉, 결론보다 근거와 논리를 보완해야 합니다.",en:"In other words, the evidence and reasoning need more work than the conclusion.",romanization:"jeuk, gyeollonboda geungeowa nollireul bowanhaeya hamnida."},{speaker:"민서",ko:"결국 보고서는 주장, 근거, 사례가 서로 연결되어야 합니다.",en:"Ultimately, a report's claim, evidence, and cases must be connected.",romanization:"gyeolguk bogoseoneun jujang, geungeo, saryega seoro yeongyeoldoeeoya hamnida."}]},{kind:"order",prompt:"Build: 'The evidence is weak. Therefore, the conclusion must be reviewed.'",tokens:["근거가 약하다.","따라서 결론을 다시 검토해야 한다."],correct:"근거가 약하다. 따라서 결론을 다시 검토해야 한다.",explanation:"따라서 connects evidence to a conclusion or required action. The written ending -다 keeps the register consistent."}],canDo:"Draw a conclusion in formal writing with 따라서 / 그러므로 (따라서 …다)",id:"chapter-63-b8",chapterId:"chapter-63",index:7},{kind:"reading",title:"읽기 Reading · 근거가 부족한 보고서 고치기",cards:[{kind:"read",title:"근거가 부족한 보고서 고치기",chunks:["초안 보고서는 결론이 분명했으나 근거가 부족했다. 따라서 결론을 유지하되 사례 분석을 보완해야 한다. 그러나 모든 내용을 새로 쓸 필요는 없다. 핵심 주장은 유지할 수 있다.","반면에 반론 검토는 아직 약하다. 즉, 문제는 결론 자체가 아니라 근거와 논리의 연결이다. 결국 좋은 보고서는 주장, 근거, 사례, 반론이 서로 연결될 때 설득력을 가진다."],translation:"The draft report had a clear conclusion, but the evidence was insufficient. Therefore, the conclusion can remain, but the case analysis needs to be strengthened. However, not all content needs to be rewritten. The main claim can be kept. By contrast, the counterargument review is still weak. In other words, the problem is not the conclusion itself but the link between evidence and reasoning. Ultimately, a good report is persuasive when claim, evidence, cases, and counterarguments are connected.",qas:[{q:"초안 보고서의 가장 큰 문제는 무엇인가요?",a:"결론 자체가 아니라 근거와 논리의 연결이 약한 것입니다."},{q:"왜 따라서가 쓰였나요?",a:"근거가 부족하다는 진단에서 사례 분석을 보완해야 한다는 결론이 이어지기 때문입니다."},{q:"글의 마지막 문장에서 결국은 어떤 역할을 하나요?",a:"앞의 수정 방향을 모아 좋은 보고서의 조건으로 정리합니다."}]}],canDo:"Distinguish three kinds of contrast with 그러나 / 반면에 / 한편",id:"chapter-63-b9",chapterId:"chapter-63",index:8},{kind:"boss",title:"보스 Boss bite · 다 걸어요",cards:[{kind:"drill",prompt:"근거가 부족하다. ___ 결론을 다시 검토해야 한다.",sentence:null,options:[{text:"따라서",ok:!0},{text:"한편",ok:!1},{text:"즉",ok:!1}],explanation:"The second sentence is a consequence of the first."},{kind:"drill",prompt:"첫 번째 사례는 적절하다. ___ 두 번째 사례는 관련성이 약하다.",sentence:null,options:[{text:"반면에",ok:!0},{text:"따라서",ok:!1},{text:"결국",ok:!1}],explanation:"Two comparable sides are being contrasted."},{kind:"drill",prompt:"문제는 결론이 아니다. ___ 근거와 논리의 연결이 약하다는 점이다.",sentence:null,options:[{text:"즉",ok:!0},{text:"그러나",ok:!1},{text:"한편",ok:!1}],explanation:"The second sentence restates the diagnosis more precisely."},{kind:"drill",prompt:"Which sentence keeps written register most consistently?",sentence:null,options:[{text:"결국 좋은 글은 근거와 사례가 연결되어야 한다.",ok:!0},{text:"결국 좋은 글은 근거랑 사례가 연결돼요.",ok:!1},{text:"결국 좋은 글은 근거랑 사례, 이런 게 중요해요.",ok:!1}],explanation:"결국 plus -다 style keeps the paragraph formal and written."},{kind:"drill",prompt:"근거___ 부족하다. (The evidence is insufficient.)",sentence:null,options:[{text:"가",ok:!0},{text:"를",ok:!1},{text:"에",ok:!1}],explanation:"부족하다 describes the evidence, so 근거 takes 가. 를 would make evidence an object, which does not fit this adjective."},{kind:"order",prompt:"Build: 'The evidence is weak. Therefore, the conclusion must be reviewed.'",tokens:["근거가 약하다.","따라서 결론을 다시 검토해야 한다."],correct:"근거가 약하다. 따라서 결론을 다시 검토해야 한다.",explanation:"따라서 connects evidence to a conclusion or required action. The written ending -다 keeps the register consistent."},{kind:"drill",prompt:"Which connector best contrasts two cases?",sentence:null,options:[{text:"반면에",ok:!0},{text:"즉",ok:!1},{text:"따라서",ok:!1}],explanation:"반면에 contrasts two sides or cases. 즉 restates, and 따라서 draws a conclusion."}],canDo:"Restate without adding new information using 즉 / 다시 말해서 (즉, …이다)",id:"chapter-63-b10",chapterId:"chapter-63",index:9}]},{id:"chapter-64",number:64,title:"Chat abbreviations: ㅋㅋ, ㅠㅠ, ㅇㅇ, ㄹㅇ, ㅇㅈ · Colloquial intensifiers: 완전 / 진짜 / 너무 / 대박 / 레전드",goal:"Recognize Korean consonant reactions such as ㅋㅋ, ㅠㅠ, ㅇㅇ, ㄹㅇ, and ㅇㅈ.",biteCount:9,bites:[{kind:"words",title:"단어 Words 1 · ㅋㅋ~",cards:[{kind:"guess",word:{ko:"ㅋㅋ",romanization:"kk",en:"haha; lol",pos:"expression",nuance:"ㅋㅋ is the texted shape of the snicker 크크/큭큭 (ㅋ is the consonant for the 'k' giggle), and among Korean 20-30s it is the default 'I'm-relaxed-and-friendly' marker — even more than a real laugh, it signals you're at ease, so chats feel cold without it. Length is meaning: ㅋㅋ is a polite chuckle, ㅋㅋㅋㅋㅋ is genuine laughter, and you stretch the string to match how funny something is (it helps that ㅋ sits under one key, so spamming it is effortless). Its near-rival ㅎㅎ is the softer cousin (a smile, not a laugh), so swapping them shifts tone — ㅋㅋ is funny, ㅎㅎ is gentle/warm. The sharp English-speaker pitfall is the lone ㅋ: in English a solo 'lol' is harmless, but a single ㅋ (or ㅋ.. / ㅋ?) can read as cold, sarcastic, even passive-aggressive — the texting equivalent of a flat 'ha,' so never go below ㅋㅋ. And keep all of it out of messages to a boss, professor, or stranger, where laughter letters look unserious; there you write plain-polite sentences with no ㅋ at all."},sentence:{ko:"이 댓글 완전 웃겨 ㅋㅋ.",en:"This comment is so funny lol."},target:"ㅋㅋ",options:["crying; T_T","yeah; yep","haha; lol"],note:"Casual digital laughter."},{kind:"guess",word:{ko:"ㅠㅠ",romanization:"yuyu",en:"crying; T_T",pos:"expression",nuance:"ㅠㅠ is a visual crying marker used for real sadness or playful frustration. Both 취소됐어ㅠㅠ and 취소됐어 ㅠㅠ are common: no space feels tightly attached, while a space treats it more like an emoji. Keep it to casual messages rather than formal or work writing."},sentence:{ko:"과제 제출 내일까지래 ㅠㅠ.",en:"They say the assignment is due tomorrow T_T."},target:"ㅠㅠ",options:["haha; lol","crying; T_T","yeah; yep"],note:"Sad, frustrated, or playfully distressed reaction."},{kind:"guess",word:{ko:"ㅇㅇ",romanization:"ngng",en:"yeah; yep",pos:"expression",nuance:"ㅇㅇ is the texted form of 응 (eung, casual 'yeah'), doubled to 응응, so it carries pure banmal — the informal register you'd use with people you speak 반말 to out loud. That register IS the meaning: it broadcasts 'we're equals/close.' Its near-neighbor is the polite 네/넵, and the gap between them is exactly the politeness gap, which is why the English-speaker pitfall is severe: English 'yeah' is fine to almost anyone, but firing ㅇㅇ at a boss, professor, or older stranger skips every layer of politeness and reads as blunt, even disrespectful — like grunting 'uh-huh' at a superior. The safe upgrade ladder for seniors is 네 (polite) → 넵 (cheerful-polite) → 네네 (warm). Don't confuse ㅇㅇ (yes/agreement, from 응응) with ㅇㅋ (okay/got it, from 오케이): you ANSWER a yes/no question with ㅇㅇ, but you CONFIRM an instruction with ㅇㅋ. And length carries warmth — a bare ㅇㅇ to a friend who's clearly excited can read as flat, even reluctant, so match their energy with ㅇㅇㅇㅇ or 응응!!; worse, a single curt ㅇ alone can feel like an annoyed 'k.'"},sentence:{ko:"ㅇㅇ 알겠어.",en:"Yeah, got it."},target:"ㅇㅇ",options:["haha; lol","crying; T_T","yeah; yep"],note:"Quick casual yes to a close peer."},{kind:"guess",word:{ko:"ㄹㅇ",romanization:"rieol",en:"for real; seriously",pos:"expression",nuance:"ㄹㅇ is the consonant skeleton of 리얼, Korea's borrowing of English 'real,' and it works two ways: as a reply it's emphatic agreement ('for real / no joke / facts'), and dropped inside a sentence it's an intensifier meaning 'genuinely/seriously' (이거 ㄹㅇ 웃겨 = 'this is genuinely funny'). It's very current 20-30s slang, at home in friend chats and comments, and frequently fused with ㅋㅋ as ㄹㅇㅋㅋ. Its native-Korean cousins are 진짜 and 정말 ('really/truly'), which carry the same meaning but sound a notch less slangy — and those are what you'd upgrade to in polite contexts (진짜요/정말요). Two English-speaker pitfalls: first, don't decode ㄹㅇ as 'right now' or any English-acronym guess — it's strictly '리얼/real (for real).' Second, ㄹㅇ overlaps heavily with the agreement word ㅇㅈ (인정, 'agreed'), but they aren't identical: ㄹㅇ asserts 'that's TRUE,' while ㅇㅈ concedes 'I ADMIT/agree' — close enough to stack (ㄹㅇ ㅇㅈ) but ㄹㅇ also works as a standalone intensifier where ㅇㅈ can't. And keep it casual: this is young-person slang, so with seniors say 진짜요/정말요, not ㄹㅇ. Note too that position rewrites the meaning — bare ㄹㅇ is 'true,' ㄹㅇ? is 'seriously?!', and mid-sentence ㄹㅇ is just 'really' — so the same two letters do three different jobs."},sentence:{ko:"이 노래 ㄹㅇ 좋아.",en:"This song is seriously good."},target:"ㄹㅇ",options:["for real; seriously","haha; lol","crying; T_T"],note:"Truth/intensity marker from 리얼."},{kind:"guess",word:{ko:"ㅇㅈ",romanization:"injeong",en:"agreed; true that",pos:"expression",nuance:"ㅇㅈ is the consonant frame of 인정 (Sino-Korean 認定, 'recognize + fix/settle'), literally 'to acknowledge/admit something as so' — and as slang it became young Koreans' punchy way to say 'agreed, that's facts.' Its polite equivalents are 맞아요 ('that's right'), 동의해요 ('I agree'), and very formal 동의합니다, which are what you'd use with seniors. Two English-speaker pitfalls. First, the literal core is 'acknowledge/admit,' so beyond cheerful agreement it can carry a faint flavor of conceding a point ('okay, I'll grant you that') — and the bare-noun 인정 even works as a real verb (그 실수는 인정 = 'I admit that mistake'); reading it as only upbeat 'yes!' misses that edge. Second, don't blur it with ㄹㅇ: ㅇㅈ = 'I agree/admit (인정),' a stance toward what you said; ㄹㅇ = 'for real/genuinely (리얼),' a claim about truth that can also intensify a sentence. They pair (ㄹㅇ ㅇㅈ) but aren't swappable everywhere. As always, keep ㅇㅈ casual — to a boss write 맞습니다 / 동의합니다. And mind the function: ㅇㅈ endorses an OPINION/take, so it fits 'good song / weekdays are better' — it is not a plain factual 'yeah' to a yes/no (that's ㅇㅇ)."},sentence:{ko:"A: 이 댓글이 제일 웃겨. / B: ㅇㅈ.",en:"A: This comment is the funniest. / B: Agreed."},target:"ㅇㅈ",options:["haha; lol","agreed; true that","crying; T_T"],note:"Endorses an opinion or take."},{kind:"guess",word:{ko:"완전",romanization:"wanjeon",en:"totally; really",pos:"adverb",nuance:"완전 literally means complete, but in casual speech it works as a general booster. It can sound youthful, excited, or blunt depending on context."},sentence:{ko:"그 영상 완전 웃겨.",en:"That video is totally funny."},target:"완전",options:["haha; lol","crying; T_T","totally; really"],note:"Casual intensifier, not formal writing."},{kind:"payoff",line:{speaker:"민서",ko:"그 댓글 봤어? 완전 웃겨 ㅋㅋㅋ.",en:"Did you see that comment? It's so funny lol."},hl:"ㅋㅋ"}],canDo:"Read and use chat tokens like ㅋㅋ, ㅠㅠ, ㅇㅇ, ㄹㅇ, ㅇㅈ in casual messages",id:"chapter-64-b1",chapterId:"chapter-64",index:0},{kind:"pattern",title:"무늬 Pattern · Chat abbreviations: ㅋㅋ, ㅠㅠ, ㅇㅇ, ㄹㅇ, ㅇㅈ",cards:[{kind:"teach",name:"Chat abbreviations: ㅋㅋ, ㅠㅠ, ㅇㅇ, ㄹㅇ, ㅇㅈ",sub:"",rows:[{when:"Something is funny; softening a message; showing you're amused",add:"ㅋㅋ (more ㅋ = harder laugh: ㅋㅋㅋㅋ)",ex:"아 진짜 웃겨 ㅋㅋㅋ (lol that's so funny)"},{when:"Crying, sad, disappointed, or begging cutely",add:"ㅠㅠ (also ㅜㅜ); pure emotion, no laugh",ex:"나 시험 망했어 ㅠㅠ (I bombed the test)"},{when:"A short 'yeah / yes / ok' reply between friends",add:"ㅇㅇ (= 응응, a casual yes)",ex:"ㅇㅇ 나도 갈게 (yeah, I'll go too)"},{when:"Stressing 'for real / seriously / no joke'",add:"ㄹㅇ (= 레알, from English 'real')",ex:"ㄹㅇ 그 카페 맛있어 (that cafe's legit good)"},{when:"Agreeing hard with what someone said",add:"ㅇㅈ (= 인정, 'I acknowledge it')",ex:"ㅇㅈ 그 영화 별로였음 (agreed, that movie was meh)"}],examples:[{ko:"ㅋㅋㅋ 너 진짜 웃긴다",en:"lololol you're so funny",romanization:"kkk neo jinjja utginda",note:"Repeating ㅋ = a bigger laugh; a single ㅋ can read as cold or sarcastic."},{ko:"비 와서 약속 취소됐어 ㅠㅠ",en:"It rained so the plan got cancelled",romanization:"bi waseo yaksok chwiso-dwaesseo",note:"ㅠㅠ carries the disappointment, so you don't need extra sad words."}],more:{func:"These are consonant-only shorthand 'reaction' tokens Koreans type in chat (KakaoTalk, comments, DMs). They're not words you pronounce out loud; they're typed signals, almost like emoji. ㅋㅋ shows laughter, ㅠㅠ shows crying/sadness, and ㅇㅇ / ㄹㅇ / ㅇㅈ are clipped one-shot replies (yeah / for real / agreed). They make a message feel casual and friendly, which is exactly why you use them with friends and peers, never with a boss, teacher, or stranger.",keyPoint:{label:"Typed sound vs spoken word",body:"ㅋㅋ and ㅠㅠ are typed, not spoken — you don't say 'kuh-kuh' out loud. ㅇㅇ / ㄹㅇ / ㅇㅈ are clipped spellings of 응응 / 레알 / 인정, so reading them aloud means saying the full word, not naming the letters."},pronunciation:""}}],canDo:"Read and use chat tokens like ㅋㅋ, ㅠㅠ, ㅇㅇ, ㄹㅇ, ㅇㅈ in casual messages",id:"chapter-64-b2",chapterId:"chapter-64",index:1},{kind:"words",title:"단어 Words 2 · 레전드~",cards:[{kind:"guess",word:{ko:"레전드",romanization:"rejeondeu",en:"legendary; iconic",pos:"noun",nuance:"레전드 can praise something impressive, but it can also be ironic when something is absurd or unbelievably bad."},sentence:{ko:"오늘 라이브 채팅 레전드였어.",en:"Today's live chat was legendary."},target:"레전드",options:["online comment","like button","legendary; iconic"],note:"Can be praise or ironic reaction."},{kind:"guess",word:{ko:"개웃겨",romanization:"gaeutgyeo",en:"hilarious; so funny",pos:"expression",nuance:"개웃겨 is stronger and rougher than 너무 웃겨 or 진짜 웃겨. It can sound friendly, but it can also sound careless if the relationship is not close."},sentence:{ko:"이 댓글 개웃겨 ㅋㅋㅋ.",en:"This comment is hilarious lolol."},target:"개웃겨",options:["haha; lol","hilarious; so funny","crying; T_T"],note:"Very casual and rougher than 진짜 웃겨."},{kind:"guess",word:{ko:"댓글",romanization:"daetgeul",en:"online comment",pos:"noun",nuance:"댓글 is online. For a spoken comment or opinion, 말 or 의견 may fit better."},sentence:{ko:"그 게시물에 댓글 달았어.",en:"I left a comment on that post."},target:"댓글",options:["legendary; iconic","online comment","like button"],note:"댓글을 달다 is the standard collocation."},{kind:"guess",word:{ko:"좋아요",romanization:"joayo",en:"like button",pos:"noun",nuance:"좋아요 is the 해요체 form of the adjective 좋다 'to be good, nice, likeable', but standing alone as a reply it works as a reaction expression: 'sounds good / I like it / okay, let's do that.' As a response to a suggestion (같이 갈까요? 내일 만날까요?) it's an enthusiastic yes — warmer and more committed than a bare 네, which just confirms. The critical dividing line is 괜찮아요. As a reply to an OFFER, 괜찮아요 usually means 'no thanks, I'm fine as I am' — it's a polite refusal — while 좋아요 means 'yes please.' English 'okay', 'fine', and 'that's good' map onto both of them, which is exactly why beginners accidentally decline the coffee, the bag, or the second helping they actually wanted. If someone offers you something and you want it, say 좋아요 or 네, 주세요; 괜찮아요 will get it taken away. 좋아요 also keeps its plain adjective sense ('it's good/nice': 날씨가 좋아요, 이 카페 좋아요), and it's the Korean name of the social-media Like button — 좋아요(를) 누르다 'to like a post.' Register ladder: 좋아 (banmal) → 좋아요 (polite) → 좋습니다 (formal); 좋네요 reacts in the moment to something in front of you. One caution upward: a bare 좋아요 in reply to a senior's proposal can read as you evaluating their idea, so with a boss the natural answers are 네, 좋습니다 or 네, 그렇게 하겠습니다. The second English-speaker pitfall is the 좋아요 / 좋아해요 split: 좋다 is an ADJECTIVE, so the thing takes 이/가 (김치가 좋아요 'I like kimchi / kimchi is good'), while 좋아하다 is a VERB, so the thing takes 을/를 (김치를 좋아해요 'I like kimchi'). 김치를 좋아요 is simply wrong — pick one pattern and match the particle to it."},sentence:{ko:"방금 좋아요 눌렀어.",en:"I just hit like."},target:"좋아요",options:["legendary; iconic","online comment","like button"],note:"The button is pressed, so use 누르다."},{kind:"guess",word:{ko:"공유하다",romanization:"gongyuhada",en:"to share",pos:"verb",nuance:"공유하다 is broader than sending. 보내다 is to send; 공유하다 emphasizes making content available or passing it along."},sentence:{ko:"재미있어서 친구한테 공유했어.",en:"It was funny, so I shared it with a friend."},target:"공유했",options:["to share","haha; lol","crying; T_T"],note:"The recipient takes 한테 or 에게."},{kind:"guess",word:{ko:"라이브 채팅",romanization:"raibeu chaeting",en:"live chat",pos:"noun",nuance:"라이브 채팅 is a channel, not a writing style. It invites short reactions, abbreviations, and fast turn-taking."},sentence:{ko:"라이브 채팅이 너무 빨라서 댓글을 다 못 읽었어.",en:"The live chat was so fast that I couldn't read all the comments."},target:"라이브 채팅",options:["live chat","legendary; iconic","online comment"],note:"A natural place for short reactions."},{kind:"payoff",line:{speaker:"민서",ko:"그 댓글 봤어? 완전 웃겨 ㅋㅋㅋ.",en:"Did you see that comment? It's so funny lol."},hl:"댓글"}],canDo:"Crank up the feeling with colloquial intensifiers (완전 / 진짜 / 대박 / 레전드)",id:"chapter-64-b3",chapterId:"chapter-64",index:2},{kind:"pattern",title:"무늬 Pattern · Colloquial intensifiers: 완전 / 진짜 / 너무 / 대박 / 레전드",cards:[{kind:"hunt",name:"Colloquial intensifiers: 완전 / 진짜 / 너무 / 대박 / 레전드",sub:"",lines:[{tokens:[{pre:"이",mid:"",post:"",hit:!1},{pre:"카페",mid:"",post:"",hit:!1},{pre:"분위기",mid:"",post:"",hit:!1},{pre:"",mid:"완전",post:"",hit:!0},{pre:"좋아",mid:"",post:"",hit:!1}],ko:"이 카페 분위기 완전 좋아",en:"This cafe's vibe is totally great",romanization:"i kape bunwigi wanjeon joa"},{tokens:[{pre:"나",mid:"",post:"",hit:!1},{pre:"",mid:"진짜",post:"",hit:!0},{pre:"배고파",mid:"",post:"",hit:!1},{pre:"죽겠어",mid:"",post:"",hit:!1}],ko:"나 진짜 배고파 죽겠어",en:"I'm seriously starving",romanization:"na jinjja baegopa jukgesseo"}],rule:{name:"Colloquial intensifiers: 완전 / 진짜 / 너무 / 대박 / 레전드",rows:[{when:"'so / totally' before an adjective; very common in casual talk",add:"완전 + adjective",ex:"이거 완전 맛있어 (this is so good)"},{when:"'really / seriously'; the most neutral, works almost anywhere",add:"진짜 + adjective/verb",ex:"진짜 피곤해 (I'm really tired)"},{when:"'so (much)'; in casual speech often just means 'very', not 'excessively'",add:"너무 + adjective",ex:"너무 좋아 (I love it / it's so nice)"},{when:"'awesome / no way!'; exclamation for shocking-good (or shocking-bad) news",add:"대박 (standalone or 대박이다)",ex:"헐 대박 (omg no way!)"},{when:"'legendary / epic'; calling something unforgettably great (or hilariously bad)",add:"레전드 (standalone or 레전드 + 이다)",ex:"어제 공연 레전드였어 (last night's show was legendary)"}]},more:{func:"These are casual booster words meaning roughly 'so / totally / really / insanely (good)'. Speakers drop them in front of an adjective or verb, or use them alone as an exclamation, to crank up the feeling. 진짜 and 너무 are everyday-neutral; 완전 sounds breezy and young; 대박 and 레전드 are slangy hype words for something amazing or unforgettable. They live in speech, chat, and reviews, and they carry the emotion that flat, polite sentences leave out.",keyPoint:{label:"너무: textbook 'too much' vs real-life 'very'",body:"Textbooks teach 너무 = 'too (excessively)', but in everyday speech 너무 좋아 just means 'I love it', not 'I like it too much'. Context, not the word itself, decides whether it's negative."},pronunciation:"대박 is often stretched as 대애박~ for emphasis, and 헐 frequently leads into it (헐 대박). 완전 is written 완전 but in fast speech can sound like a quick 완젼."}},{kind:"drill",prompt:"Whoa, no way — is that for real?",sentence:"헐 ___, 그거 진짜야?",options:[{text:"완전",ok:!1},{text:"진짜",ok:!1},{text:"대박",ok:!0}],explanation:"대박 works as a one-word reaction to surprising news, good or bad."}],canDo:"Crank up the feeling with colloquial intensifiers (완전 / 진짜 / 대박 / 레전드)",id:"chapter-64-b4",chapterId:"chapter-64",index:3},{kind:"pattern",title:"무늬 Pattern · Platform verbs: 댓글 달다, 좋아요 누르다, 공유하다, 구독하다",cards:[{kind:"teach",name:"Platform verbs: 댓글 달다, 좋아요 누르다, 공유하다, 구독하다",sub:"",rows:[{when:"Leaving / writing a comment on a post or video",add:"댓글(을) 달다 (lit. 'hang a comment')",ex:"영상에 댓글 달았어 (I left a comment on the video)"},{when:"Tapping the like button / heart",add:"좋아요(를) 누르다 (lit. 'press the like')",ex:"사진에 좋아요 눌러 줘 (hit like on the photo)"},{when:"Forwarding / reposting content to others",add:"공유하다 (share)",ex:"이 글 친구한테 공유했어 (I shared this post with a friend)"},{when:"Following a channel/creator to get new uploads",add:"구독하다 (subscribe)",ex:"그 채널 구독했어 (I subscribed to that channel)"}],examples:[{ko:"구독하고 좋아요 눌러 주세요!",en:"Please subscribe and hit like!",romanization:"gudok-hago joayo nulleo juseyo!",note:"The set phrase every Korean YouTuber says; note 좋아요 pairs with 누르다, never 하다."},{ko:"내 사진에 누가 댓글 달았어",en:"Someone left a comment on my photo",romanization:"nae sajin-e nuga daetgeul darasseo",note:"달다 conjugates to 달았어 (darasseo); the 을 is dropped, which is normal in casual speech."}],more:{func:"Every social-media action in Korean has a fixed noun + verb pairing you have to memorize rather than translate from English. You 'hang' a comment (댓글을 달다), 'press' a like (좋아요를 누르다), 'share' (공유하다), and 'subscribe' (구독하다). The object particle 을/를 is often dropped in casual chat (댓글 달았어), but the verb pairing is fixed — pick the wrong verb and it sounds off even when every word is technically correct.",keyPoint:{label:"좋아요 누르다, not 좋아요 하다",body:"English 'like' is one word, so learners reach for 좋아요 하다 — but Korean fixes each action to its own verb: a like is pressed (누르다), a comment is hung (달다). Memorize the pair instead of translating the verb."},pronunciation:""}}],canDo:"Use fixed platform verb pairings (좋아요 누르다, 댓글 달다, 공유하다)",id:"chapter-64-b5",chapterId:"chapter-64",index:4},{kind:"pattern",title:"무늬 Pattern · Register: ㅇㅇ vs 네 / 알겠어요",cards:[{kind:"teach",name:"Register: ㅇㅇ vs 네 / 알겠어요",sub:"",rows:[{when:"Close friend / peer, in chat — quick 'yeah'",add:"ㅇㅇ / 응",ex:"ㅇㅇ 거기서 보자 (yeah, see you there)"},{when:"Close friend / peer — strong 'agreed, true'",add:"ㅇㅈ / 인정",ex:"ㅇㅈ 그건 좀 너무했어 (agreed, that was a bit much)"},{when:"Anyone you respect — polite 'yes'",add:"네 (not ㅇㅇ)",ex:"네, 알겠어요 (yes, got it)"},{when:"Boss / teacher / customer — polite 'understood'",add:"알겠어요 / 알겠습니다",ex:"네, 알겠습니다 (yes, understood)"}],examples:[{ko:"A: 내일 회의 2시야 / B: ㅇㅇ 알았어",en:"A: tomorrow's meeting is at 2 / B: yep, got it",romanization:"naeil hoeui du-siya / eung-eung arasseo",note:"Friend-to-friend, so ㅇㅇ + 반말 (알았어) is natural and warm."},{ko:"네, 알겠습니다. 바로 처리할게요",en:"Yes, understood. I'll take care of it right away",romanization:"ne, algetseumnida. baro cheori-halgeyo",note:"To a boss or client; 네 + 알겠습니다 is the safe default at work."}],more:{func:"The same meaning ('yes / got it / agreed') wears very different clothes depending on who you're talking to. ㅇㅇ, 응, ㅇㅈ, and 반말 belong to text chat with close friends and peers. 네 / 알겠어요 / 알겠습니다 are what you say or type to anyone you respect — a teacher, a customer, an older person, a boss. Picking the wrong register isn't a grammar mistake; it's a social one. So before you reply, read the relationship: is this someone you'd speak 반말 to, or someone you owe 존댓말?",keyPoint:{label:"Register is a relationship choice, not a vocab choice",body:"ㅇㅇ and 네 mean the same thing; what differs is who you're allowed to say it to. When unsure, default to 네/알겠어요 — being slightly too polite is invisible, but being too casual is rude."},pronunciation:""}}],canDo:"Switch register correctly — ㅇㅇ with friends vs 네 / 알겠어요 in formal replies",id:"chapter-64-b6",chapterId:"chapter-64",index:5},{kind:"dialogue",title:"대화 Dialogue · 진짜 한국어",cards:[{kind:"chat",setting:"Friends react to a comment thread, then rewrite the same reaction for a formal setting.",lines:[{speaker:"민서",ko:"그 댓글 봤어? 완전 웃겨 ㅋㅋㅋ.",en:"Did you see that comment? It's so funny lol.",romanization:"geu daetgeul bwasseo? wanjeon utgyeo kkk."},{speaker:"지훈",ko:"ㅇㅇ 봤어. 헐, 좋아요 눌렀어?",en:"Yeah, I saw it. Whoa, did you hit like?",romanization:"ngng bwasseo. heol, joayo nulleosseo?"},{speaker:"민서",ko:"응, 친구한테 공유했어. 댓글 반응도 레전드야.",en:"Yeah, I shared it with a friend. The comment reactions are legendary too.",romanization:"eung, chinguhante gongyuhaesseo. daetgeul baneungdo rejeondeuya."},{speaker:"지훈",ko:"공식 글에는 ㅋㅋ 빼고 재미있었습니다처럼 써야 해.",en:"In an official post, you should leave out ㅋㅋ and write something like 'it was interesting.'",romanization:"gongsik geureneneun kk ppaego jaemiisseotseumnidacheoreom sseoya hae."}]},{kind:"order",prompt:"Build a close-friend chat reply: 'Yep, see you tomorrow.'",tokens:["ㅇㅇ","내일 봐"],correct:"ㅇㅇ 내일 봐",explanation:"ㅇㅇ is a casual yes/yeah used with close friends. It should not be used with teachers or formal contacts."}],canDo:"Read and use chat tokens like ㅋㅋ, ㅠㅠ, ㅇㅇ, ㄹㅇ, ㅇㅈ in casual messages",id:"chapter-64-b7",chapterId:"chapter-64",index:6},{kind:"reading",title:"읽기 Reading · 친구 단톡방과 공식 글 구분하기",cards:[{kind:"read",title:"친구 단톡방과 공식 글 구분하기",chunks:["친구 단톡방에서는 이 댓글 완전 웃겨 ㅋㅋㅋ처럼 짧고 감정적인 표현이 자연스럽다. ㅇㅇ은 빠른 대답이고, ㄹㅇ ㅇㅈ은 상대의 의견에 강하게 동의하는 반응이다. 라이브 채팅에서는 이런 표현이 빠르게 올라오기 때문에 글이 문장보다 반응에 가깝다.","그러나 교수님께 보내는 메시지나 회사 계정의 공식 글에서는 같은 표현을 그대로 쓰면 가볍거나 무례하게 들릴 수 있다. 이때는 네, 확인했습니다, 정말 재미있었습니다, 저도 그렇게 생각합니다처럼 완전한 문장으로 바꾸는 것이 안전하다."],translation:"In a friend group chat, short emotional lines like 'this comment is so funny lol' feel natural. ㅇㅇ is a quick answer, and ㄹㅇ ㅇㅈ strongly agrees with someone's opinion. In live chat, these forms appear quickly, so the writing feels more like reactions than full sentences. However, if you use the same expressions in a message to a professor or an official company post, they can sound too casual or rude. In those settings, it is safer to rewrite them as full sentences such as 'Yes, I have confirmed it,' 'It was really interesting,' or 'I also think so.'",qas:[{q:"친구 단톡방에서 자연스러운 표현은 무엇인가요?",a:"이 댓글 완전 웃겨 ㅋㅋㅋ 같은 짧고 감정적인 표현입니다."},{q:"ㄹㅇ ㅇㅈ은 어떤 반응인가요?",a:"상대의 의견에 강하게 동의하는 반응입니다."},{q:"공식 글에서는 왜 표현을 바꿔야 하나요?",a:"그대로 쓰면 가볍거나 무례하게 들릴 수 있기 때문입니다."}]}],canDo:"Crank up the feeling with colloquial intensifiers (완전 / 진짜 / 대박 / 레전드)",id:"chapter-64-b8",chapterId:"chapter-64",index:7},{kind:"boss",title:"보스 Boss bite · 다 걸어요",cards:[{kind:"drill",prompt:"A close friend asks, 내일 7시에 볼까? Which reply fits casual chat?",sentence:null,options:[{text:"ㅇㅇ 알겠어.",ok:!0},{text:"네, 확인했습니다.",ok:!1},{text:"따라서 참석하겠습니다.",ok:!1}],explanation:"ㅇㅇ is natural only with close peers."},{kind:"drill",prompt:"Which sentence is safest for a professor after a funny class video?",sentence:null,options:[{text:"정말 재미있었습니다.",ok:!0},{text:"개웃겨요 ㅋㅋ.",ok:!1},{text:"ㄹㅇ 레전드였어요.",ok:!1}],explanation:"The polite/formal sentence keeps the reaction respectful."},{kind:"drill",prompt:"Which verb naturally goes with 좋아요?",sentence:null,options:[{text:"누르다",ok:!0},{text:"하다",ok:!1},{text:"치다",ok:!1}],explanation:"좋아요 is treated as a button, so Koreans press it."},{kind:"drill",prompt:"Which expression agrees with someone's opinion?",sentence:null,options:[{text:"ㅇㅈ",ok:!0},{text:"ㅠㅠ",ok:!1},{text:"ㅋㅋ",ok:!1}],explanation:"ㅇㅈ comes from 인정 and means agreed or true that."},{kind:"drill",prompt:"Which expression is the roughest, most casual way to say something is hilarious?",sentence:null,options:[{text:"개웃겨",ok:!0},{text:"정말 재미있습니다",ok:!1},{text:"너무 웃겨요",ok:!1}],explanation:"개웃겨 is natural in close peer chat but too rough for formal settings."},{kind:"drill",prompt:"댓글___ 달았어요. (I left a comment.)",sentence:null,options:[{text:"을",ok:!0},{text:"이",ok:!1},{text:"에",ok:!1}],explanation:"댓글을 달다 is the natural verb phrase for leaving a comment. 이 would make the comment the subject."},{kind:"order",prompt:"Build a close-friend chat reply: 'Yep, see you tomorrow.'",tokens:["ㅇㅇ","내일 봐"],correct:"ㅇㅇ 내일 봐",explanation:"ㅇㅇ is a casual yes/yeah used with close friends. It should not be used with teachers or formal contacts."},{kind:"drill",prompt:"Which abbreviation means “for real / seriously” in casual chat?",sentence:null,options:[{text:"ㄹㅇ",ok:!0},{text:"ㅠㅠ",ok:!1},{text:"ㅇㅈ",ok:!1}],explanation:"ㄹㅇ is shorthand for real/seriously. ㅠㅠ shows crying, and ㅇㅈ means agreed."}],canDo:"Use fixed platform verb pairings (좋아요 누르다, 댓글 달다, 공유하다)",id:"chapter-64-b9",chapterId:"chapter-64",index:8}]},{id:"chapter-65",number:65,title:"Integrated production checklist · Rewrite by relationship, not by adding 요",goal:"Run a production checklist before sending or saying Korean.",biteCount:9,bites:[{kind:"words",title:"단어 Words 1 · 상황~",cards:[{kind:"guess",word:{ko:"상황",romanization:"sanghwang",en:"situation; circumstances",pos:"noun",nuance:"상황 (狀況, '狀 condition/form + 況 circumstances' — the configuration of circumstances) describes the overall set of conditions surrounding a moment or event, broader than a single 경우 (a specific case or instance — 이런 경우 = 'in this one case', vs 이런 상황 = 'in this whole situation'). The reflexive phrase 상황에 따라(서) 다르다 ('it depends on the situation') is one of the most useful hedges in Korean, and 이런/그런 상황에서 sets up advice or reactions. Register is neutral. Two pitfalls: keep 상황 (the circumstances around an event) distinct from 상태 (狀態, the state/condition of a single thing or body — 건강 상태 'health condition', 배터리 상태 'battery state'); you describe a person's mood with a 상태, but the events around them with a 상황. And use 에 따라 (not 으로) for 'depending on': 상황에 따라, never 상황으로."},sentence:{ko:"먼저 상황과 상대방을 정해야 해요.",en:"First, you need to decide the situation and listener."},target:"상황",options:["the other person; listener","writing style; register style","situation; circumstances"],note:"The first step in production review."},{kind:"guess",word:{ko:"상대방",romanization:"sangdaebang",en:"the other person; listener",pos:"noun",nuance:"상대방 is neutral. It is not necessarily an opponent; it can simply mean the other person in the interaction."},sentence:{ko:"상대방이 누구인지에 따라 문체가 달라져요.",en:"The style changes depending on who the listener is."},target:"상대방",options:["situation; circumstances","writing style; register style","the other person; listener"],note:"Relationship decides register."},{kind:"guess",word:{ko:"문체",romanization:"munche",en:"writing style; register style",pos:"noun",nuance:"문체 is broader than one polite ending. It covers the whole feel of the text: vocabulary, endings, connectors, and sentence shape."},sentence:{ko:"공식 이메일에서는 문체를 끝까지 격식 있게 맞춰야 해요.",en:"In a formal email, the style should stay formal until the end."},target:"문체",options:["situation; circumstances","writing style; register style","the other person; listener"],note:"Style consistency is the final chapter's main habit."},{kind:"guess",word:{ko:"조사",romanization:"josa",en:"particle",pos:"noun"},sentence:{ko:"마지막으로 조사 하나까지 다시 확인하겠습니다.",en:"Lastly, I will check every particle again."},target:"조사",options:["situation; circumstances","particle","the other person; listener"],note:"Particles are small but high-impact."},{kind:"guess",word:{ko:"시제",romanization:"sije",en:"tense",pos:"noun",nuance:"시제 is not just past, present, and future labels. It is how the listener tracks whether an event happened, is happening, or is planned."},sentence:{ko:"면접 답변에서는 시제를 안정적으로 유지해야 해요.",en:"In an interview answer, you need to keep the tense stable."},target:"시제",options:["situation; circumstances","tense","the other person; listener"],note:"Experience answers often fail when tense shifts."},{kind:"payoff",line:{speaker:"지훈",ko:"먼저 상황과 상대방을 정하고 문체를 맞춰야 해요.",en:"First, decide the situation and listener, then match the style."},hl:"상황"}],canDo:"Build one coherent message that fits the situation and the listener (상황·상대방에 맞게)",id:"chapter-65-b1",chapterId:"chapter-65",index:0},{kind:"pattern",title:"무늬 Pattern · Integrated production checklist",cards:[{kind:"teach",name:"Integrated production checklist",sub:"",rows:[],examples:[{ko:"면접 답변은 정중하게 말하고, 경험의 시제를 흔들리지 않게 맞춰야 해요.",en:"For an interview answer, speak courteously and keep the tense of your experience consistent.",romanization:"myeonjeop dapbyeoneun jeongjunghage malhago, gyeongheomui sijereul heundeulliji anke matchwoya haeyo.",note:"Interview Korean checks register and tense together."},{ko:"공식 이메일에서는 확인 부탁드립니다처럼 마무리를 격식 있게 써야 해요.",en:"In a formal email, the closing should be formal, like 확인 부탁드립니다.",romanization:"gongsik imeireseoneun hwagin butakdeurimnidacheoreom mamurireul gyeoksik itge sseoya haeyo.",note:"Email Korean needs closing phrases, not only correct grammar."},{ko:"친구 카톡에서는 편하게 써도 되지만 회사 메일에는 ㅋㅋ를 빼야 해요.",en:"You can write casually in a friend's KakaoTalk chat, but you must remove ㅋㅋ from a company email.",romanization:"chingu katogeseoneun pyeonhage sseodo doejiman hoesa meileneun kkreul ppaeya haeyo.",note:"Same feeling, different style."}],more:{func:"",keyPoint:null,pronunciation:""}}],canDo:"Build one coherent message that fits the situation and the listener (상황·상대방에 맞게)",id:"chapter-65-b2",chapterId:"chapter-65",index:1},{kind:"words",title:"단어 Words 2 · 연결어~",cards:[{kind:"guess",word:{ko:"연결어",romanization:"yeongyeoreo",en:"connector; linking word",pos:"noun",nuance:"연결어 is about logic, not decoration. A connector tells the reader how to understand the next sentence."},sentence:{ko:"이메일에서는 연결어와 마무리를 같이 확인해야 해요.",en:"In an email, you need to check the connectors and the closing together."},target:"연결어",options:["situation; circumstances","the other person; listener","connector; linking word"],note:"Formal writing needs logical links and a closing."},{kind:"guess",word:{ko:"높임말",romanization:"nopimmal",en:"honorific or respectful language",pos:"noun",nuance:"높임말 is not only being polite to the listener. It can honor a third person, such as a teacher or parent."},sentence:{ko:"면접 답변은 높임말부터 확인해야 해요.",en:"For an interview answer, you should check honorific language first."},target:"높임말",options:["situation; circumstances","the other person; listener","honorific or respectful language"],note:"Respectful language belongs to relationship control."},{kind:"guess",word:{ko:"확인 부탁드립니다",romanization:"hwagin butakdeurimnida",en:"Please check / kindly confirm",pos:"expression",nuance:"확인 부탁드립니다 is 확인 ('confirmation/checking', Sino-Korean 確認) + 부탁드립니다 ('I humbly ask'), the single most common closing request in Korean work email. 확인 covers both 'verify it is correct' and 'acknowledge you have seen it', so it is wonderfully versatile. The politeness lives in 부탁드리다 (humble 'to request'), making this safe upward to bosses and clients. The near-synonym contrast: 검토 (檢討) means a deeper REVIEW — reading critically, forming a judgment — while 확인 is a lighter 'check/confirm'. Asking a senior to 확인 a number is fine; if you want their considered opinion, use 검토 부탁드립니다. The English-speaker pitfall is reaching for the loanword 체크 (체크 부탁드립니다) — understandable but casual Konglish; professional mail uses 확인. Another trap is the plain imperative 확인하세요, which can sound curt or bossy upward; 확인 부탁드립니다 frames the same request as a humble ask. 확인 is a 하다-noun; if you want the full verb form, it is 확인해 주세요, never 확인 주세요."},sentence:{ko:"첨부 파일 확인 부탁드립니다.",en:"Please check the attached file."},target:"확인 부탁드립니다",options:["situation; circumstances","the other person; listener","Please check / kindly confirm"],note:"Formal email closing phrase."},{kind:"guess",word:{ko:"답장",romanization:"dapjang",en:"reply",pos:"noun",nuance:"답장(答狀) is Sino-Korean — 答 'to answer' + 狀 'a written document/letter' — literally 'an answering document,' i.e. a written reply to a letter, text, or email. The sharp contrast every learner needs is with 대답(對答) 'a (spoken) answer/response': you give a 대답 out loud to a question someone asks face-to-face, but you write a 답장 back to a message. A third neighbor is 회신(回信) 'a reply,' the stiff, formal/business word used in official correspondence. So a casual text-back is 답장, answering a teacher's spoken question is 대답, and a corporate email response is often 회신. Collocations: 답장을 하다/보내다/받다, 답장이 늦다 'reply is late,' 답장이 없다. The English-speaker pitfall: English 'answer/reply' is one word, so learners use 대답 for everything — but if it's written, it's 답장; and bare 답장 isn't a verb, so 'to reply' must be 답장하다 / 답장을 하다. The thing you reply to is marked with 에 (문자에 답장하다)."},sentence:{ko:"답장이 늦어져 죄송합니다.",en:"I apologize for the delayed reply."},target:"답장",options:["situation; circumstances","reply","the other person; listener"],note:"Formal email apology frame."},{kind:"guess",word:{ko:"정중하다",romanization:"jeongjunghada",en:"courteous; respectful",pos:"adjective",nuance:"정중하다 (鄭重하다; the 重 carries 'weighty/grave,' so the word evokes treating someone with weighty respect) means courteous and respectful in a formal, dignified way — proper manners and respectful language. The near-synonym you must separate is 친절하다 (kind/friendly), and the dividing line is warmth vs. form: 친절하다 is personal warmth and helpfulness (a 친절한 점원 smiles and helps you happily), while 정중하다 is formal respect shown through correct manners and language (a 정중한 점원 is impeccably proper, not necessarily warm). For a careful apology, a polite refusal, or staff toward an important guest, you reach for 정중하다, where 친절하다 would feel too casual-warm. Also distinguish 겸손하다 (inner humility about oneself) from 정중하다 (outward courtesy toward others) — different directions. Register: 정중하다 is itself a formal-leaning word, at home in business Korean and written apologies (정중히 사과드립니다). The English-speaker pitfall is collapsing all 'polite' into one word: friendly-polite is 친절하다, formally-courteous is 정중하다. Stem note: 정중해요, not 정중하해요."},sentence:{ko:"면접에서는 정중하게 대답하는 것이 좋아요.",en:"In an interview, it is good to answer courteously."},target:"정중하",options:["situation; circumstances","courteous; respectful","the other person; listener"],note:"Useful register adjective for speech style."},{kind:"payoff",line:{speaker:"민서",ko:"오늘 면접 답변, 이메일, 카톡 답장을 한 번에 검수해 볼까요?",en:"Shall we review today's interview answer, email, and KakaoTalk reply together?"},hl:"답장"}],canDo:"Hold register, tense, and particles consistent across several sentences (문체·시제·조사)",id:"chapter-65-b3",chapterId:"chapter-65",index:2},{kind:"pattern",title:"무늬 Pattern · Rewrite by relationship, not by adding 요",cards:[{kind:"teach",name:"Rewrite by relationship, not by adding 요",sub:"",rows:[],examples:[{ko:"친구: ㅇㅇ 확인했어. / 회사 메일: 네, 확인했습니다.",en:"Friend: Yep, I checked. / Company email: Yes, I have confirmed it.",romanization:"chingu: ngng hwaginhaesseo. / hoesa meil: ne, hwaginhaetseumnida.",note:"ㅇㅇ changes to 네, and the ending changes to -했습니다."},{ko:"친구: 그 영상 개웃겨. / 면접: 그 사례가 매우 인상적이었습니다.",en:"Friend: That video is hilarious. / Interview: That example was very impressive.",romanization:"chingu: geu yeongsang gaeutgyeo. / myeonjeop: geu saryega maeu insangjeogieotseumnida.",note:"The rough slang is rewritten, not decorated."},{ko:"친구: 늦어서 미안. / 공식 이메일: 답장이 늦어져 죄송합니다.",en:"Friend: Sorry I'm late. / Formal email: I apologize for the delayed reply.",romanization:"chingu: neujeoseo mian. / gongsik imeil: dapjangi neujeojyeo joesonghamnida.",note:"Formal email uses a different phrase and a different sentence shape."}],more:{func:"",keyPoint:null,pronunciation:""}}],canDo:"Hold register, tense, and particles consistent across several sentences (문체·시제·조사)",id:"chapter-65-b4",chapterId:"chapter-65",index:3},{kind:"pattern",title:"무늬 Pattern · The three quiet failure points",cards:[{kind:"teach",name:"The three quiet failure points",sub:"",rows:[],examples:[{ko:"이 문장은 뜻은 맞지만 조사가 어색해요.",en:"The meaning of this sentence is right, but the particle is awkward.",romanization:"i munjangeun tteuseun matjiman josaga eosaekaeyo.",note:"A common review comment."},{ko:"경험을 말할 때는 과거 시제를 안정적으로 유지해야 해요.",en:"When talking about experience, you need to keep the past tense stable.",romanization:"gyeongheomeul malhal ttaeneun gwageo sijereul anjeongjeogeuro yujihaeya haeyo.",note:"Interview answers often talk about past experience."},{ko:"공식 글에서는 그래서보다 따라서가 더 자연스러울 수 있어요.",en:"In formal writing, 따라서 can be more natural than 그래서.",romanization:"gongsik geureseoneun geuraeseoboda ttaraseoga deo jayeonseureoul su isseoyo.",note:"Connector choice depends on register and logic."}],more:{func:"",keyPoint:null,pronunciation:""}}],canDo:"Combine multiple grammar points — past tense, V-기로 했어요, soft guess, connectors — without breaking the flow",id:"chapter-65-b5",chapterId:"chapter-65",index:4},{kind:"pattern",title:"무늬 Pattern · One idea, four Korean versions",cards:[{kind:"teach",name:"One idea, four Korean versions",sub:"",rows:[],examples:[{ko:"면접: 관련 경험을 검토했고, 필요한 부분을 개선하겠습니다.",en:"Interview: I have reviewed the related experience and will improve the necessary parts.",romanization:"myeonjeop: gwallyeon gyeongheomeul geomtohaetgo, piryohan bubuneul gaeseonhagetseumnida.",note:"Formal speech with -겠습니다."},{ko:"이메일: 자료 확인 후 수정해서 다시 보내드리겠습니다.",en:"Email: After checking the materials, I will revise them and send them again.",romanization:"imeil: jaryo hwagin hu sujeonghaeseo dasi bonaedeurigetseumnida.",note:"Formal email with 보내드리겠습니다."},{ko:"동료 대화: 자료 확인했고, 필요한 부분은 다시 고칠게요.",en:"Coworker talk: I checked the materials, and I'll fix the necessary parts.",romanization:"dongnyo daehwa: jaryo hwaginhaetgo, piryohan bubuneun dasi gochilgeyo.",note:"Polite but softer."},{ko:"친구 카톡: 봤어. 내가 다시 고칠게 ㅋㅋ.",en:"Friend KakaoTalk: Saw it. I'll fix it again lol.",romanization:"chingu katok: bwasseo. naega dasi gochilge kk.",note:"Casual, private, and relationship-dependent."}],more:{func:"",keyPoint:null,pronunciation:""}}],canDo:"Close politely with honorific phrasing (확인 부탁드립니다 · 죄송합니다)",id:"chapter-65-b6",chapterId:"chapter-65",index:5},{kind:"dialogue",title:"대화 Dialogue · 진짜 한국어",cards:[{kind:"chat",setting:"A learner reviews four Korean outputs from the same day.",lines:[{speaker:"민서",ko:"오늘 면접 답변, 이메일, 카톡 답장을 한 번에 검수해 볼까요?",en:"Shall we review today's interview answer, email, and KakaoTalk reply together?",romanization:"oneul myeonjeop dapbyeon, imeil, katok dapjangeul han beone geomsuhae bolkkayo?"},{speaker:"지훈",ko:"먼저 상황과 상대방을 정하고 문체를 맞춰야 해요.",en:"First, decide the situation and listener, then match the style.",romanization:"meonjeo sanghwanggwa sangdaebangeul jeonghago munchereul matchwoya haeyo."},{speaker:"민서",ko:"면접 답변은 높임말과 시제를 확인하고, 이메일은 연결어와 마무리를 봐요.",en:"For the interview answer, check honorifics and tense; for the email, check connectors and the closing.",romanization:"myeonjeop dapbyeoneun nopimmalgwa sijereul hwaginhago, imeireun yeongyeoreowa mamurireul bwayo."},{speaker:"지훈",ko:"카톡에서는 편하게 써도 되지만 회사 메일에는 ㅋㅋ를 빼야 해요.",en:"You can write casually in KakaoTalk, but in a company email you need to remove ㅋㅋ.",romanization:"katogeseoneun pyeonhage sseodo doejiman hoesa meileneun kkreul ppaeya haeyo."},{speaker:"민서",ko:"마지막으로 조사 하나까지 다시 확인하겠습니다.",en:"Lastly, I will check every particle again.",romanization:"majimageuro josa hanakkaji dasi hwaginhagetseumnida."}]},{kind:"order",prompt:"Build a formal email line: 'After checking, please reply.'",tokens:["확인 후","답장 부탁드립니다"],correct:"확인 후 답장 부탁드립니다",explanation:"확인 후 is concise written Korean for after checking. 부탁드립니다 keeps the email formal and courteous."}],canDo:"Build one coherent message that fits the situation and the listener (상황·상대방에 맞게)",id:"chapter-65-b7",chapterId:"chapter-65",index:6},{kind:"reading",title:"읽기 Reading · 하루 안에서 문체 바꾸기",cards:[{kind:"read",title:"하루 안에서 문체 바꾸기",chunks:["한국어를 잘 쓴다는 것은 단어를 많이 아는 것만으로 끝나지 않는다. 면접 답변에서는 정중한 문체와 안정적인 시제가 필요하고, 공식 이메일에서는 확인 부탁드립니다 같은 마무리 표현과 자연스러운 연결어가 필요하다. 반면에 친구 카톡에서는 짧고 편한 표현이 더 자연스러울 수 있다.","중요한 것은 같은 생각을 상황에 맞게 다시 쓰는 능력이다. 문장을 보내기 전에는 상대방, 목적, 문체, 조사, 시제, 연결어를 차례로 확인해야 한다."],translation:"Writing Korean well is not just knowing many words. An interview answer needs a courteous style and stable tense, while a formal email needs closing phrases such as 확인 부탁드립니다 and natural connectors. By contrast, short and relaxed expressions may be more natural in a friend's KakaoTalk chat. What matters is the ability to rewrite the same idea for the situation. Before sending a sentence, check the listener, purpose, style, particles, tense, and connectors in order.",qas:[{q:"면접 답변에서 필요한 것은 무엇인가요?",a:"정중한 문체와 안정적인 시제입니다."},{q:"공식 이메일에서는 무엇을 확인해야 하나요?",a:"마무리 표현과 자연스러운 연결어를 확인해야 합니다."},{q:"문장을 보내기 전에 어떤 항목을 확인해야 하나요?",a:"상대방, 목적, 문체, 조사, 시제, 연결어를 확인해야 합니다."}]}],canDo:"Hold register, tense, and particles consistent across several sentences (문체·시제·조사)",id:"chapter-65-b8",chapterId:"chapter-65",index:7},{kind:"boss",title:"보스 Boss bite · 다 걸어요",cards:[{kind:"drill",prompt:"Which sentence fits a formal company email?",sentence:null,options:[{text:"첨부 파일 확인 부탁드립니다.",ok:!0},{text:"파일 봐 줘 ㅋㅋ.",ok:!1},{text:"ㅇㅇ 파일 봤어.",ok:!1}],explanation:"부탁드립니다 is a formal written request ending."},{kind:"drill",prompt:"Which item should you decide before choosing slang or honorifics?",sentence:null,options:[{text:"상대방과 상황",ok:!0},{text:"romanization",ok:!1},{text:"sentence length only",ok:!1}],explanation:"Relationship and situation determine register."},{kind:"drill",prompt:"따라서와 ㅋㅋ가 한 문단에 같이 있으면 무엇이 문제인가요?",sentence:null,options:[{text:"문체가 섞입니다.",ok:!0},{text:"시제가 없습니다.",ok:!1},{text:"조사가 너무 많습니다.",ok:!1}],explanation:"Formal connectors and casual chat reactions usually do not belong in the same paragraph."},{kind:"drill",prompt:"Which review layer checks 은/는, 이/가, 을/를?",sentence:null,options:[{text:"조사",ok:!0},{text:"시제",ok:!1},{text:"마무리",ok:!1}],explanation:"은/는, 이/가, 을/를 are particles."},{kind:"drill",prompt:"친구 카톡: 봤어. 내가 다시 고칠게 ㅋㅋ. What should change for a formal email?",sentence:null,options:[{text:"자료 확인 후 수정해서 다시 보내드리겠습니다.",ok:!0},{text:"봤어요 ㅋㅋ.",ok:!1},{text:"고칠게요 ㄹㅇ.",ok:!1}],explanation:"The formal email version rewrites the sentence, removes slang, and uses a formal ending."},{kind:"drill",prompt:"답장___ 확인해 주시기 바랍니다. (Please check the reply.)",sentence:null,options:[{text:"을",ok:!0},{text:"이",ok:!1},{text:"에",ok:!1}],explanation:"확인하다 takes the thing checked as an object, so 답장을 fits. 이 would make the reply the subject."},{kind:"order",prompt:"Build a formal email line: 'After checking, please reply.'",tokens:["확인 후","답장 부탁드립니다"],correct:"확인 후 답장 부탁드립니다",explanation:"확인 후 is concise written Korean for after checking. 부탁드립니다 keeps the email formal and courteous."},{kind:"drill",prompt:"Before sending Korean, which review order is safest?",sentence:null,options:[{text:"상황과 상대방 → 문체 → 조사/시제/높임말",ok:!0},{text:"ㅋㅋ 추가 → 문체 무시 → 조사 확인",ok:!1},{text:"단어만 번역 → 바로 전송",ok:!1}],explanation:"Relationship and situation decide the register first. Then you check grammar details like particles, tense, and honorifics."}],canDo:"Combine multiple grammar points — past tense, V-기로 했어요, soft guess, connectors — without breaking the flow",id:"chapter-65-b9",chapterId:"chapter-65",index:8}]}],n={generatedFrom:e,chapters:t};export{t as chapters,n as default,e as generatedFrom};
